["pln_ff3_07_any_06"] = "AMAN! İYİ SENATÖRÜMÜZ HEM ANLAŞMAYI YAPMIŞ HEM PARTİ VERMİŞ GALİBA. SİLAH-ALTIN-KOKAİN ANLAŞMASINA BENZİYOR.",
["pln_ff3_07_any_07"] = "TAMAM! BURADA GERÇEK BİR SKANDAL VAR. DEVLETİN SİLAHLARINI HAYDUT BİR DEVLETE SATMIŞ, KARŞILIĞINDA ALTIN ALMIŞ. DEMOKRATLAR BUNDAN HOŞLANMAYACAK.",
["pln_ff3_07_any_08"] = "BASIN BU ZAVALLI ADAMLA BAYRAM EDECEK. ANLAŞMA KAMU GÖREVİ SIRASINDA DA YAPILMIŞ GİBİ!",
["pln_ff3_07_any_09"] = "BUNU DOSYALARA PAKETLEYİP BASINA GÖNDERMEYE HAZIRLANACAĞIM.",
["pln_ff3_07_any_10"] = "O HABER AKIŞINI AÇIK TUTUN, BEN DE SİZE ÇIKIŞ YOLU BULMAYA BAŞLAYAYIM.",
["pln_ff3_08_any_01"] = "SUÇU ÜSTÜNE ATMAYA YARAR. MUHTEŞEM OLMAYACAK AMA PARAMIZI ALIRIZ. SİZİ ÇIKARALIM!",
["pln_ff3_09_any_01"] = "NE DAİRE AMA! SİLAH ANLAŞMALARI SENATÖR MAAŞINA GÜZEL EK GELİR SAĞLIYOR.",
["pln_ff3_10_any_01"] = "VAY BE... ŞU MEKÂNA BAKIN... O ALTINI BULUN, KENDİMİZE DE BİR TANE ALALIM.",
["pln_ff3_11_any_01"] = "TAMAM, DİKKATLİ OLUN! BAŞTAN SONA GİZLİCE GİTMEYE DEĞECEK ÇOCUKLAR. ALARM OLMAZSA BU KUMPAS KUSURSUZ OLACAK!",
["pln_ff3_12_any_01"] = "ŞU GÜZEL ŞEYLERE BAKIN. KARİYERİ BOYUNCA HALKA NE ÇOK HİZMET ETMİŞ OLMALI.",
["pln_ff3_13_any_01"] = "KAMU GÖREVİ. VAY BE, YANLIŞ İŞ KOLUNDAYIZ BEYLER.",
["pln_ff3_14_any_01"] = "ŞU MANZARAYA BAKIN...",
["pln_ff3_15_any_01"] = "EVET, MERKEZ TAM ORASI. O EVDE NE TÜR HAZİNELER VAR ACABA? TAMAM, BURADAKİ SOYGUNUMUZA DÖNELİM.",
["pln_ff3_16_any_01"] = "1600 PENN, BELKİ SONRAKİ BÜYÜK VURGUN İÇİN ORAYA GİDERİZ.",
["pln_ff3_17_any_01"] = "AH, KASA DAİRESİ BU MİLLET. BU SEFER O KAPIYI GEÇEMEYİZ. AMA ALTINLAR... ÖBÜR TARAFTAKİ ALTINLAR! NEYSE, BIRAKMAK ZORUNDAYIZ.",
["pln_ff3_18_any_01"] = "ALTINLARI BIRAKMAK KOYUYOR AMA PARAMIZI ALACAĞIZ. BELKİ GERİ DÖNERİZ.",
["pln_firestarter_stage1_brief_01"] = "BİR KUŞ, MENDOZA'LARIN HECTOR'LA SAVAŞA HAZIRLANIRKEN UÇAKLA DAHA FAZLA SİLAH GETİRDİĞİNİ SÖYLEDİ. HAVAALANLARINA GİDİP SİLAHLARI BULACAĞIZ. YA HEPSİNİ ALACAĞIZ YA YOK EDECEĞİZ.",
["pln_firestarter_stage1_brief_01b"] = "TERCİHEN ALIN, ÇÜNKÜ ÖYLE YAPARSAK GÜZEL PARA VAR.",
["pln_firestarter_stage1_brief_02"] = "HECTOR, ÖZEL HAVAALANLARINA GİREN MENDOZA KARTELİNE, KENDİ DEYİMİYLE KAN VE ATEŞLE BİR MESAJ GÖNDERMEK İSTİYOR. ZOR OLABİLİR... AMA BENCE YAPARIZ.",
["pln_firestarter_stage1_brief_02b"] = "KÜÇÜK BİR KUŞ, MENDOZA'LARIN HECTOR'LA SAVAŞA HAZIRLANMAK İÇİN UÇAKLA DAHA FAZLA SİLAH GETİRDİĞİNİ SÖYLEDİ.",
["pln_firestarter_stage1_brief_02c"] = "KÜÇÜK ÖZEL HAVAALANLARINA GİDECEĞİZ, SİLAHLARI BULUP YA HEPSİNİ ALACAĞIZ YA DA YOK EDECEĞİZ... AMA ALIRSAK DAHA KÂRLI OLUR.",
["pln_firestarter_stage1_end_a_01"] = "ARTIK MENDOZA VE ADAMLARININ ATEŞ GÜCÜ EPEY AZALDI. SAYENİZDE HECTOR'IN ADAMLARI ÇOK DAHA AZ DİRENİŞLE KARŞILAŞACAK. BELKİ BİZİ TAKDİR BİLE EDER. İYİ İŞ.",
["pln_firestarter_stage1_end_a_01b"] = "TAMAM, GİTMEYE HAZIRIZ. GÜVENLİ EVE GEÇİŞİNİZİ AYARLARIM. CEPHANELİKLERİ GİTTİ. ASKERLERİNİN DİŞLERİ SÖKÜLDÜ.",
["pln_firestarter_stage1_end_a_02"] = "BU İŞTE MENDOZA'NIN DİŞLERİNİ SÖKTÜK. O SİLAHLARI YOK ETTİĞİMİZ İÇİN ARTIK ISIRAMAYACAK, SADECE HAVLAYACAK. EMİNİM HECTOR BİZİ KESİN DAHA BÜYÜK İŞLERE TAŞIR.",
["pln_firestarter_stage1_end_a_02b"] = "İYİ UYGULANDI. SİLAHLAR YOK EDİLDİ, HECTOR'A HABER VERİLDİ. HADİ PARAYI ALALIM.",
["pln_firestarter_stage1_end_a_03"] = "UCUZ ATLATTIK. O SİLAHLARI ORTADAN KALDIRMAKTA İYİ İŞ ÇIKARDINIZ. HECTOR ŞİMDİ ORDUSUNU SOKACAK, BİZ DE ÇOK GÜZEL PARA ALACAĞIZ.",
["pln_firestarter_stage1_end_b_01"] = "BENİ HAYAL KIRIKLIĞINA UĞRATMIYORSUNUZ. HECTOR BU İŞLE GURUR DUYACAK. ARTIK GERÇEKTEN İŞ YAPIYORUZ.",
["pln_firestarter_stage1_end_b_01b"] = "İYİ İŞ MİLLET. KÖTÜ GİDEBİLİRDİ AMA KÂRDA KALMAMIZI SAĞLADINIZ. SİLAH TİCARETİNE VAR MISINIZ?",
["pln_firestarter_stage1_end_b_02"] = "EPEY YÜKLENMİŞSİNİZ, SİLAHLARIN HEPSİ BUYDU DEĞİL Mİ? BİR DAHAKİNE ZORLAŞTIRMAM GEREKECEK. BELKİ GÖZLERİNİZİ BAĞLARIM FALAN. AFERİN.",
["pln_firestarter_stage1_end_b_03"] = "TIKIR TIKIR İŞLEDİ. İYİ SAVAŞTINIZ, İYİ TAŞIDINIZ; NE DEMEK İSTEDİĞİMİ ANLIYORSANIZ. HAK EDİLMİŞ PARAMIZ GELİYOR.",
["pln_firestarter_stage1_end_b_04"] = "DAHA ÇOK SİLAH, DAHA ÇOK PARA. HARİKA İŞ. HECTOR BİZİ BEKLİYOR.",
["pln_firestarter_stage1_intro_a_01"] = "TAMAM, HAVAALANI HEMEN YOKUŞ AŞAĞIDA. ÇİTİ KESİP GEÇİN. KASALARIN YÜKLÜ OLDUĞU KAMYONUN BULUNDUĞU HANGARI BULUN. MENDOZA'LAR MUHTEMELEN ORADADIR. GİDİP O SİLAHLARI ALIN YA DA ONLARIN ALAMAMASINI SAĞLAYIN. ",
["pln_firestarter_stage1_intro_a_01b"] = "ÇİTTEN GİRECEK, SİLAHLARI BULUP BURAYA GETİRECEKSİNİZ. SAVAŞMADAN PES ETMEZLER. İŞLER BOKA SARARSA SİLAHLARI YOK EDİN.",
["pln_firestarter_stage1_intro_a_02"] = "MENDOZA'LAR DEPODA SİLAH YÜKLEMEKLE MEŞGUL OLACAK. LORD OF WAR'A BAĞLAMADAN İÇERİ GİRİP HIZLICA VURUN. SİLAHLARI ALIN YA DA YOK EDİN. ",
["pln_firestarter_stage1_intro_a_02b"] = "İÇERİ GİRİNCE SANDIKLARI BULUP YOK EDİN YA DA GERİ GETİRİN. DAHA FAZLASINI YAPMAK İSTERSENİZ BUYURUN.",
["pln_firestarter_stage2_01_any_01"] = "TAMAM, İÇERİ GİRMENİN YOLUNU BULUN, BAŞINIZI EĞİN, MUHAFIZLARA VE KAMERALARA DİKKAT EDİN.",
["pln_firestarter_stage2_03_any_01"] = "GÜZEL, İÇERİDESİNİZ. ŞİMDİ SUNUCU ODASINI BULUN.",
["pln_firestarter_stage2_04_any_01"] = "GENSEC GÜVENLİK KAPISI ARIYORUZ. GÜVENLİK ODASI ONUN ARKASINDA.",
["pln_firestarter_stage2_05_any_01"] = "YÜKSEK GÜVENLİKLİ BİR KAPI OLMALI, GENSEC LOGOSUNU ARAYIN.",
["pln_firestarter_stage2_06_any_01"] = "TAMAM, SUNUCU ODASINI BULUP İÇERİ GİRİN. ARTIK ALARMLARI DEVRE DIŞI BIRAKMANIN ANLAMI YOK.",
["pln_firestarter_stage2_07_any_01"] = "TAMAM, SUNUCU ODASININ KAPISI BU.",
["pln_firestarter_stage2_08_any_01"] = "ALARMI VAR, HENÜZ AÇMAYIN. ÖNCE ALARMI KAPATMAMIZ GEREK.",
["pln_firestarter_stage2_09_any_01"] = "O KAPIYI AÇIN.",
["pln_firestarter_stage2_10_any_01"] = "SIRADA BİLGİSAYAR VAR.",
["pln_firestarter_stage2_11_any_01"] = "O TERMİNALİ KULLANIN, SİSTEMLERİNE ERİŞMEK İSTİYORUM.",
["pln_firestarter_stage2_12_any_01"] = "TAMAM, GİRDİM. BEKLEYİN...",
["pln_firestarter_stage2_13_any_01"] = "TAMAM, ERİŞİM SAĞLADIM...",
["pln_firestarter_stage2_14_any_01"] = "...DEVRE DIŞI BIRAKMAMIZ GEREKEN 3 GENSEC GÜVENLİK KUTUSU VAR.",
["pln_firestarter_stage2_15_any_01"] = "...DEVRE DIŞI BIRAKMAMIZ GEREKEN 2 GENSEC GÜVENLİK KUTUSU VAR.",
["pln_firestarter_stage2_16_any_01"] = "...DEVRE DIŞI BIRAKMAMIZ GEREKEN 1 GENSEC GÜVENLİK KUTUSU VAR.",
["pln_firestarter_stage2_17_any_01"] = "SİZİN İÇİN İŞARETLEDİM. GİDİP KABLOYU KESİN.",
["pln_firestarter_stage2_18_any_01"] = "GÜZEL.",
["pln_firestarter_stage2_19_any_01"] = "2 KALDI.",
["pln_firestarter_stage2_20_any_01"] = "1 KALDI.",
["pln_firestarter_stage2_21_any_01"] = "SONUNCUYU ALIN.",
["pln_firestarter_stage2_22_any_01"] = "HARİKA, TAMAMDIR. ARTIK KAPIYI AÇABİLİRSİNİZ.",
["pln_firestarter_stage2_23_any_01"] = "AH, GÜVENLİK KUTULARINI ÇOKTAN HALLETMİŞSİNİZ. ÖNCEDEN PLANLAMAK, HOŞUMA GİTTİ.",
["pln_firestarter_stage2_24_any_01"] = "NE YAPIYORSUNUZ? İŞARETLEMEMİ BEKLEYİN. DOĞRU KABLOYU KESMELİYİZ.",
["pln_firestarter_stage2_25_any_01"] = "İÇERİDE MİSİNİZ? İYİ İŞ.",
["pln_firestarter_stage2_26_any_01"] = "ARTIK SUNUCUYLA ARANIZDA TEK KAPI KALDI.",
["pln_firestarter_stage2_27_any_01"] = "O SON KAPIYI AÇIP SUNUCUYA ULAŞIN.",
["pln_firestarter_stage2_28_any_01"] = "MÜTHİŞ İŞ, EKİP! SON ADIM: SUNUCUYU SÖKÜP ARABAYA GETİRMENİZ GEREK.",
["pln_firestarter_stage2_29_any_01"] = "TAMAM, ALDINIZ. ÇIKALIM BURADAN!",
["pln_firestarter_stage2_30_any_01"] = "ŞİMDİ HATA YAPMAYIN, GÖRÜNMEYİN. AZ KALDI...",
["pln_firestarter_stage2_31_any_01"] = "YOLUN HEMEN KARŞISINDA SİZİ BEKLEYEN BİR ARABA VAR.",
["pln_firestarter_stage2_32_any_01"] = "GELDİĞİMİZİ BİLE FARK ETMEDİLER. HARİKA İŞ! GÜVENLİ EVDE GÖRÜŞÜRÜZ.",
["pln_firestarter_stage2_33_any_01"] = "OLAMAZ, ALARM ÇALDI! B PLANINA GEÇELİM.",
["pln_firestarter_stage2_34_any_01"] = "O SUNUCUYU NASIL OLURSA OLSUN ALIN!",
["pln_firestarter_stage2_36_any_01"] = "NE YAPIYORSUNUZ!? İÇERİ BİLE GİREMEDİNİZ. B PLANINA GEÇELİM. BİR DAHAKİ SEFERE GÖZE BATMAYIN.",
["pln_firestarter_stage2_37_any_01"] = "SWAT EKİPLERİ HALATLA OFİSE İNİYOR!",
["pln_firestarter_stage2_38_any_01"] = "ARA SOKAĞIN KARŞISINDA KESKİN NİŞANCILAR!",
["pln_firestarter_stage2_39_any_01"] = "KESKİN NİŞANCILAR! ÇATIDA.",
["pln_firestarter_stage2_brief_01"] = "HECTOR ŞİMDİ DE BİLGİ ALMAK İÇİN DOĞRUDAN MENDOZA'LARI VURMAMIZ GEREKTİĞİNİ SÖYLÜYOR. ASIL ÖĞRENMEK İSTEDİĞİ, PARALARINI NEREDE TUTTUKLARI.",
["pln_firestarter_stage2_brief_01b"] = "NEYSE Kİ MENDOZA KARTELİNDEN BİRİ FBI'IN ONLARI SORUŞTURDUĞUNU AĞZINDAN KAÇIRMIŞ. VERİLERİ ALMAK İÇİN KARTELİN DOSYASINA BAKAN YEREL FBI OFİSİNİ VURMAMIZ YETERLİ.",
["pln_firestarter_stage2_brief_01c"] = "EVET, BİLİYORUM. YAĞMURDAN KAÇARKEN DOLUYA TUTULMAK...",
["pln_firestarter_stage2_end_a_01"] = "VAY BE. BUNDAN HARİKA BİR TELEVİZYON FİLMİ OLUR. SİZİN DIŞINIZDA BİRİ İÇİN. NEYSE, ARTIK MENDOZA BANKASININ YERİNİ BİLİYORUZ. ",
["pln_firestarter_stage2_end_a_02"] = "HARİKA. SAYENİZDE MENDOZA'NIN BÜTÜN PARASINI NEREYE SAKLADIĞINI BİLİYORUZ. TRUSTEE'NİN BANKA ŞUBELERİNDEN BİRİNE. SIRADA NE OLDUĞUNU TAHMİN EDİYORSUNUZDUR, HA?",
["pln_firestarter_stage2_end_a_03"] = "İYİ İŞ EKİP. HECTOR, BİLGİ İÇİN FBI'I BASTIĞIMIZI BİLSE BİRAZ ENDİŞELENİRDİ. AMA HECTOR'IN BİLMEDİĞİ ŞEY CANINI YAKMAZ. HADİ BANKACILIK YAPALIM MI?",
["pln_firestarter_stage2_end_b_01"] = "GALİBA DİKKAT ÇEKMEME İŞİ ARTIK MÜMKÜN DEĞİL. ÖTE YANDAN REKLAMIN KÖTÜSÜ OLMAZ, ALMAYA GELDİĞİMİZİ DE ALDIK. İYİ İŞ.",
["pln_firestarter_stage2_end_b_02"] = "DIŞARISI EPEY SICAK. HATTA BAHSE GİRERİM ŞU AN MENDOZA'DAN DAHA ÇOK ARANIYORSUNUZ. HECTOR APTAL OLMADIĞI İÇİN ARKASINDA BİZİM OLDUĞUMUZU DÜŞÜNÜR HERHÂLDE.",
["pln_firestarter_stage2_end_b_02b"] = "ŞU BANKAYI HALLEDİP MENDOZA'NIN PARASINI BİR AN ÖNCE YAKALIM. SONRA SİZE YENİ KİMLİKLER BULURUZ.",
["pln_firestarter_stage2_intro_a_01"] = "FBI'IN GEÇİCİ OFİSİ SOKAĞIN KARŞISINDA. GİZLİCE GİRİN, SUNUCU ODALARINA ERİŞMEMİ SAĞLAYIN. ETRAFTA MENDOZA'LARLA İLGİLİ BAŞKA NE BİLGİ VAR, BAKIN.",
["pln_firestarter_stage2_intro_a_01b"] = "FARK EDİLİRSENİZ NE OLACAĞINI SÖYLEMEME GEREK YOK SANIRIM.",
["pln_firestarter_stage2_intro_a_02"] = "EŞEK ARISI YUVASINA GİRİYORSUNUZ. SAKIN YUVAYA TEKME ATMAYIN, TAMAM MI?",
["pln_firestarter_stage2_intro_a_02b"] = "GİZLİCE GİRİN. KAMERALARDAN FEDERALLERİN O NANKÖR MESAİ SAATLERİNİ İZLEYİN. FBI SUNUCUSUNDAKİ MENDOZA BİLGİSİNİ ALIP ÇIKIN. SAKİN GİDİN.",
["pln_firestarter_stage2_intro_a_03"] = "TAMAM MİLLET. DOĞRUDAN KAYNAĞA GİDİYORUZ. ORADA İHTİYACIMIZ OLAN BİLGİ VAR, BİR DE YAKININDA OLMAK İSTEMEYECEĞİMİZ KADAR ÇOK KOLLUK KUVVETİ. SUNUCU ODALARINI BULUP BANKAYLA İLGİLİ BİLGİYİ ALIN. GERİSİNİ BEN YAPARIM.",
["pln_firestarter_stage3_01_any_01"] = "TAMAM MİLLET, BANKAYA GİRİN. KASA DAİRESİ'Nİ BULUP MATKAPLA AÇIN. KİMSENİN ALARMI ÇALIŞTIRMASINA YA DA KAÇMASINA İZİN VERMEYİN.",
["pln_firestarter_stage3_02_any_01"] = "HAY SİKEYİM! KASA DAİRESİNE ELEKTRİK VERMİŞLER GİBİ!",
["pln_firestarter_stage3_03_any_01"] = "ÇATIDAKİ JENERATÖRE GİDİP KAPATIN.",
["pln_firestarter_stage3_04_any_01"] = "BU İŞ GÖRÜR, ŞİMDİ MATKABI YERLEŞTİREBİLİRSİNİZ.",
["pln_firestarter_stage3_05_any_01"] = "MÜKEMMEL! MATKABI ÇALIŞIR DURUMDA TUTUN.",
["pln_firestarter_stage3_06_any_01"] = "TAMAM, HECTOR BUNU KAYDETMEMİZİ İSTİYOR, ÖNCE KAMERAYI KURUN.",
["pln_firestarter_stage3_07_any_01"] = "ŞİMDİ PARAYI TUTUŞTURUN...",
["pln_firestarter_stage3_08_any_01"] = "TAMAM, PARANIN YANMASINI BEKLERKEN ŞU KİRALIK KASALARDAN BAZILARINI AÇABİLİRSİNİZ. İÇLERİNDE NE BULURSAK BİZİM.",
["pln_firestarter_stage3_09_any_01"] = "TAMAM, BU KADAR YETER. KAYDI ALIN DA ÇIKALIM BURADAN.",
["pln_firestarter_stage3_10_any_01"] = "ARABA SİZİ KÖŞEYİ DÖNÜNCE ALACAK.",
["pln_firestarter_stage3_11_any_01"] = "BİR SİVİL KAÇTI, POLİSİ ARAMIŞ OLMALI!",
["pln_firestarter_stage3_12_any_01"] = "BİRİ ALARM DÜĞMESİNE BASTI.",
["pln_firestarter_stage3_13_any_01"] = "KAMERALARI İZLEYEN MUHAFIZ ALARMI ÇALDI.",
["pln_firestarter_stage3_14_any_01"] = "POLİSLER HER AN GELEBİLİR.",
["pln_firestarter_stage3_15_any_01"] = "BİRİ POLİSİ ARADI!",
["pln_firestarter_stage3_16_any_01"] = "ÇATIDA SWAT HELİKOPTERİ VAR.",
["pln_firestarter_stage3_17_any_01"] = "ÇEVREDEKİ BİNALARDA KESKİN NİŞANCILAR VAR.",
["pln_firestarter_stage3_brief_01"] = "İŞTE BURASI MİLLET... BU BANKA, MENDOZA'LARIN SINIRIN KUZEYİNDEKİ BÜTÜN SERMAYESİNİ TUTUYOR.",
["pln_firestarter_stage3_brief_01b"] = "KÜÇÜK YAŞLI NİNELER HER GÜN KANLI PARALARININ YANINDAN GEÇİP GİDİYOR. HECTOR, GÖZ ÖNÜNDE SAKLI DİYOR. EN AZ 100 MİLYON DOLAR KARA PARA.",
["pln_firestarter_stage3_brief_01c"] = "YAPACAĞINIZ ŞEY İÇERİ GİRİP KALABALIĞI KONTROL ETMEK, ALARMLAR ÇALMADAN KASA DAİRESİNE GİRMEK. SONRA ATEŞ YAKIP KENDİNİZİ FİLME ALIN. HECTOR BÖYLE İSTİYOR.",
["pln_firestarter_stage3_end_a_01"] = "HECTOR GÖRÜNTÜLERİ ALDI. UZUN UZUN GÜLDÜĞÜNÜ SÖYLEDİLER. ARTIK FBI İNANILMAZ BECERİKSİZ GÖRÜNÜYOR, BU DA ÜZERİMİZDEKİ BASKIYI EPEY AZALTIYOR. HARİKA İŞ.",
["pln_firestarter_stage3_end_a_02"] = "BİLİYORUM, YAKIP KÜL ETTİĞİMİZ PARA ÇOKTU. KUSURA BAKMAYIN, DOĞANIZA AYKIRI OLDUĞUNU BİLİYORUM. AMA UMARIM ALACAĞINIZ ÜCRETİ TATMİN EDİCİ BULURSUNUZ.",
["pln_firestarter_stage3_end_a_02b"] = "BURADA HECTOR'LA UĞRAŞMAMAK DOĞRU KARARDI. ATEŞLE OYNASAK YANARDIK.",
["pln_firestarter_stage3_end_a_03"] = "FBI KARMAKARIŞIK. BİR SÜRÜ KİŞİ PATRONUNUN ODASINA ÇAĞRILMAK ÜZERE. MENDOZA'LAR FELÇ OLDU, BİZ DE PARAMIZI ALMAK ÜZEREYİZ. GÜZEL YAKTINIZ MİLLET.",
["pln_firestarter_stage3_end_a_04"] = "MENDOZA BU SONUÇTAN HOŞLANMAYACAK. BİZ HOŞLANMALIYIZ AMA. AFERİN. GİDİP PARANIZI ALIN.",
["pln_firestarter_stage3_end_b_01"] = "MENDOZA KARTELİ AZ ÖNCE KIÇININ ÜSTÜNE OTURTULDU. MADDİ DARBE KADAR CAN YAKAN BİR ŞEY YOKTUR, BÜYÜK DARBE ALDILAR. HECTOR YÜKSELECEK, BU DA İLERİDE BİZİM İÇİN İYİ ŞANS DEMEK.",
["pln_firestarter_stage3_end_b_02"] = "100 MİLYON DOLAR YAKMAK MÜTHİŞ BİR ŞEY. KENDİMİ GERÇEK BİR BANKACI GİBİ HİSSEDİYORUM. GÜNLÜK İŞ İŞTE. GÜVENLİ EVDE GÖRÜŞÜRÜZ.",
["pln_firestarter_stage3_intro_a_01"] = "BİR KEZ DAHA: GİZLİCE GİRİN, KAMERALARA, MUHAFIZLARA VE DİĞER BÜTÜN ALARMLARA DİKKAT EDİN. HIZLI AMA DİKKATLİ GİRİN. İŞİ GEVŞETMEYİN.",
["pln_firestarter_stage3_intro_a_01b"] = "SONRA PARAYI BULUN, YAKIN VE TANRI AŞKINA, VERDİĞİM KAMERAYLA KAYDEDİN.",
["pln_firestarter_stage3_intro_a_01c"] = "HECTOR PARAYI SADECE CEBE İNDİRMEDİĞİMİZE DAİR KANIT İSTİYOR.",
["pln_firestarter_stage3_intro_a_02"] = "TAMAM MİLLET: GİRİN, TERMAL MIZRAKLA KASA DAİRESİNİ YARIN, PARAYI YAKIN VE FİLME ALMAYI UNUTMAYIN.",
["pln_firestarter_stage3_intro_a_02b"] = "HECTOR'IN DÜNYAYA GÖSTERMEK İÇİN GÖRÜNTÜYE İHTİYACI VAR. BİR DE, ŞEY, KENDİ GÜVENLİĞİMİZ İÇİN.",
["pln_firestarter_stage3_intro_a_02c"] = "KARTELİ KIZDIRMAMAYI TERCİH EDERİM.",
["pln_firestarter_stage3_intro_a_03"] = "TRUSTEE BANKASI İLERİDE. GİRİN, KASA DAİRESİNİ BULUN, PARAYI YAKIN, HER ŞEYİ VİDEOYA ALIN VE ÇIKIN. FBI EN ÜST ALARM SEVİYESİNDE, HIZLI VE TEMİZ YAPIN. HADİ BAŞLAYALIM.",
["pln_fish_01a_01"] = "VAY, PAHALI TEKNEYMİŞ. POWELL DENEN ADAMDA PARA VAR.",
["pln_fish_01a_02"] = "HEH, ACABA BU TEKNE ÜSTÜNDE SAKLANAN ŞEYDEN DAHA MI DEĞERLİ?",
["pln_fish_01a_03"] = "GÖRÜNÜŞE GÖRE MCKENDRİCK'İN BU DOSTU GÖSTERİŞİ SEVİYOR.",
["pln_fish_01b_01"] = "ŞİMDİ TEKNEYİ ARAYIN AMA DİKKATLİ OLUN.",
["pln_fish_01b_02"] = "SESSİZ GİDİN, GÖZÜNÜZÜ AÇIK TUTUN.",
["pln_fish_01b_03"] = "DİKKATLİ OLUN. UMARIM GICIRDAYAN AYAKKABILARINIZI GETİRMEMİŞSİNİZDİR.",
["pln_fish_02_01"] = "PARANIN SAKLANDIĞI YERLERE DAİR BİLGİ İÇEREN BİR DİZÜSTÜ BİLGİSAYAR OLMALI. PAROLAYI CHARON'DAN ALDIK, SİZİN ONU BULMANIZ YETERLİ.",
["pln_fish_02_02"] = "CHARON, PARANIN YERİYLE İLGİLİ VERİLERİ İÇEREN BİR DİZÜSTÜ BİLGİSAYARIN PAROLASINI VERDİ. BULUN!",
["pln_fish_02_03"] = "PARANIN SAKLANDIĞI YERİN BİLGİSİ BİR DİZÜSTÜNDE. PAROLAYI CHARON VERDİ. BULMAYA ÇALIŞIN!",
["pln_fish_03_01"] = "O DİZÜSTÜ BİLGİSAYARI BULUN MİLLET!",
["pln_fish_03_02"] = "DİZÜSTÜ BİLGİSAYARI ARAMAYI UNUTMAYIN!",
["pln_fish_03_03"] = "O DİZÜSTÜNÜ BULDUNUZ MU?",
["pln_fish_03_04"] = "DİZÜSTÜ BİLGİSAYAR NEREDE? BULDUNUZ MU?",
["pln_fish_03_05"] = "PARAYI İSTİYORSANIZ DİZÜSTÜNÜ BULMALISINIZ.",
["pln_fish_03_06"] = "MİLLET, DİZÜSTÜ BİLGİSAYAR. BULDUNUZ MU?",
["pln_fish_03_07"] = "DİZÜSTÜ BİLGİSAYAR ORALARDA BİR YERDE OLMALI. BULUN!",
["pln_fish_03_08"] = "DİZÜSTÜNÜ BULANA KADAR ARAMAYA DEVAM ETMELİSİNİZ.",
["pln_fish_04_01"] = "İŞTE ORADA.",
["pln_fish_04_02"] = "EVET, ARADIĞIMIZ BU.",
["pln_fish_04_03"] = "TAMAM, DİZÜSTÜ BİLGİSAYAR BU. AFERİN!",
["pln_fish_05_01"] = "ŞİMDİ PAROLAYI GİRİN.",
["pln_fish_05_02"] = "ŞİMDİ PAROLAYI GİRMENİZ GEREKİYOR.",
["pln_fish_05_03"] = "PAROLAYI GİRİP DOSYALARA ERİŞİN.",
["pln_fish_06_01"] = "BU ALTIN DEĞERİNDE. GİZLİ PARANIN BÜTÜN KONUMLARI VAR.",
["pln_fish_06_02"] = "PARANIN SAKLANDIĞI YERLERİN LİSTESİ GALİBA. YATIN HER YANINA DAĞILMIŞ.",
