["pln_fish_33_01"] = "CESETLERİ TEKNENİN ARKASINDAKİ KORKULUĞUN ÜZERİNDEN DENİZE ATABİLİRSİNİZ.",
["pln_fish_33_02"] = "CESETLERİ TEKNENİN ARKASINDAN DENİZE ATARAK SAKLAYABİLİRSİNİZ.",
["pln_fish_33_03"] = "ARKA TARAFTA CESETLERİ KORKULUĞUN ÜZERİNDEN DENİZE ATABİLİRSİNİZ.",
["pln_fish_34_01"] = "ŞUNA BAKIN. YUKARIDA BİR SÜRÜ ZENGİN KEYİF ÇATIYOR.",
["pln_fish_34_02"] = "MCKENDRİCK'İN YUKARIDA BAYAĞI NÜFUZLU DESTEKÇİLERİ VAR. KAZANIRSA NEMALANMAYI BEKLEDİKLERİNE EMİNİM.",
["pln_fish_34_03"] = "PARTİNİN ÇOĞUNUN YUKARIDA OLMASINA ÇOK SEVİNDİM. BURADA RAHAT VE SESSİZ ÇALIŞABİLİRİZ.",
["pln_fish_35_01"] = "ŞU BİR TELEVİZYON HABER EKİBİ Mİ? ONLARDAN UZAK DURMAYA ÇALIŞIN.",
["pln_fish_35_02"] = "BİR TELEVİZYON HABER EKİBİNE BENZİYOR. TELEVİZYONA ÇIKMAK İSTEMEZSİNİZ MİLLET, KAMERALARINDAN UZAK DURUN.",
["pln_fish_35_03"] = "TELEVİZYON EKİBİ. HIMM... KAMERALARINDAN UZAK DURMAYA ÇALIŞIN.",
["pln_fish_36_01"] = "ÇALIŞAN BİR ECM KARIŞTIRICI, SUNUCU ODASININ GÜVENLİK KAPISINI AÇMAYI ZORLAŞTIRIR MUHTEMELEN. AKLINIZDA OLSUN.",
["pln_fish_36_02"] = "BİR UYARI: SUNUCU ODASINDA KULLANDIKLARI GÜVENLİK SİSTEMİ YÜZÜNDEN, YAKINLARDA ÇALIŞAN BİR ECM KARIŞTIRICI VARSA KAPIYI AÇMAK ZORLAŞIR.",
["pln_fish_36_03"] = "ETKİN BİR ECM KARIŞTIRICI SUNUCU ODASINA ERİŞMEYİ ZORLAŞTIRIR. O YÜZDEN DİKKATLİ KULLANIN.",
["pln_fish_37_01"] = "MUHTEMELEN SUNUCU ODASI BURASI. YERİNİ AKLINIZDA TUTUN.",
["pln_fish_37_02"] = "ORASI SUNUCU ODASI OLABİLİR. PARAYI BULDUKTAN SONRAYA BIRAKSANIZ İYİ OLUR. YERİNİ AKLINIZDA TUTUN.",
["pln_fish_37_03"] = "SUNUCU ODASI BU GALİBA. AKLINIZDA TUTUN, ÖNCE PARAYI BULMALISINIZ.",
["pln_fish_brf_01"] = "TAMAM MİLLET, BURADA NEYİN TEHLİKEDE OLDUĞUNU BİLİYORSUNUZ. MCKENDRİCK'İN SEÇİMLERİ KAZANMAK İÇİN O PARAYA İHTİYACI VAR. ÇALABİLİRSENİZ AYAĞININ ALTINDAN HALIYI ÇEKMİŞ OLURSUNUZ. EĞLENCESİNİ BOZALIM, HEVESİNİ KURSAĞINDA BIRAKALIM. O NANKÖR PİÇİN YAPTIĞINI YANINA BIRAKMAYALIM. O PARAYI ALIN. CHARON'IN VERDİĞİ DOSYADA BİR ŞEY DAHA BULDUM. YATTA BİR SUNUCU VAR. İÇİNDE YASA DIŞI YABANCI BANKA HESAPLARININ ŞİFRELERİ BULUNUYOR, BAZILARINI MCKENDRİCK DE KULLANIYOR. O SUNUCUYU ÇALARSANIZ GÜZEL PARA KALDIRIRIZ. (DURAKLAR) HA, EVET... AZ KALSIN UNUTUYORDUM... BU GECE YATTA MCKENDRİCK İÇİN BAĞIŞ GECESİ VAR. TELEVİZYON FALAN DA OLACAK. AMA PARTİ DAHA ÇOK ÜST GÜVERTEDE, O YÜZDEN SESSİZCE SIZARSANIZ KİMSE FARK ETMEDEN GİRİP ÇIKABİLİRSİNİZ.",
["pln_fish_end_01"] = "HARİKA İŞ EKİP. BU SEFER MCKENDRİCK'İ GERÇEKTEN KAZIKLADINIZ. BÜTÜN PARANIN GİTTİĞİNİ ÖĞRENİNCE SEVİNMEYECEK.",
["pln_fish_end_02"] = "MCKENDRİCK BUNU KİMİN YAPTIĞINI ÖĞRENEBİLECEK Mİ ACABA? HER HÂLÜKÂRDA BİZİMLE UĞRAŞMAMALIYDI.",
["pln_fish_end_03"] = "MCKENDRİCK'İN YENİDEN SEÇİLME HAYALLERİ DE BİTTİ. GERÇEK KRAL YAPICILARSINIZ MİLLET! THE PAYDAY GANG VERİR DE ALIR DA.",
["pln_fish_intro_01"] = "TAMAM KORSANLAR, GEMİYE ÇIKIP GANİMETİ ALIN. SESSİZ KALIN.",
["pln_fish_intro_02"] = "DİKKATLİ OLUN, MUHAFIZLAR SİZİ GÖRMESİN. BİR DE O PARAYI BULUN.",
["pln_fish_intro_03"] = "HAZİNE AVINDA BOL ŞANS MİLLET. UNUTMAYIN, SESSİZ KALIN.",
["pln_fj1_01_01"] = "DÜKKÂNA GİRİN, SİVİLLERE DİKKAT EDİN, KAMERALARA DİKKAT EDİN VE İŞİ BİTİRİN.",
["pln_fj1_01_02"] = "DÜKKÂNA GİRİN, NE YAPACAĞINIZI BİLİYORSUNUZ! ŞU MÜCEVHERLERİ ALALIM.",
["pln_fj1_02_01"] = "VİTRİNLERİ BULUN, KIRIN VE MÜCEVHERLERİ ÇANTALAYIN.",
["pln_fj1_02_02"] = "MALLARA ULAŞMAK İÇİN VİTRİNLERİ KIRIN!",
["pln_fj1_02_03"] = "CAMI KIRIP MÜCEVHERLERİ ÇANTALAYIN. DÜKKÂNIN ETRAFINDAKİ FAZLADAN EŞYALARI UNUTMAYIN.",
["pln_fj1_03_01"] = "ARADIĞIMIZ MAL BU. MİNİBÜSE GÖTÜRÜN.",
["pln_fj1_03_02"] = "ARADIĞIMIZ BU. MİNİBÜSE GÖTÜRÜN.",
["pln_fj1_03_03"] = "ARADIĞIMIZ MÜCEVHERLER BUNLAR. MİNİBÜSE GÖTÜRÜN.",
["pln_fj1_04_01"] = "HARİKA, GETİRMEYE DEVAM EDİN!",
["pln_fj1_04_02"] = "İŞTE BÖYLE. DEVAM EDİN!",
["pln_fj1_05_01"] = "ALARM ÇALDI MİLLET. POLİSLERE DİKKAT EDİN!",
["pln_fj1_05_02"] = "LANET, ALARM ÇALDI. ÇATIŞMAYA HAZIR OLUN!",
["pln_fj1_05_03"] = "KAHRETSİN, ALARM ÇALDI. SOĞUKKANLILIĞINIZI KORUYUN VE HAZIR OLUN!",
["pln_fj1_06_01"] = "MİNİBÜS GİTMEK ZORUNDA KALDI. YAKINDA BAŞKA BİR KONUMDA OLACAK.",
["pln_fj1_06_02"] = "MİNİBÜS GİTMEK ZORUNDA KALDI. GERİ GELECEK, YENİ KONUMUNU KOLLAYIN.",
["pln_fj1_07_01"] = "TAMAM MİLLET, ÇANTALARI MİNİBÜSE GÖTÜRÜN!",
["pln_fj1_07_02"] = "TAMAM, MİNİBÜS BU. ÇANTALARI GÖTÜRÜN!",
["pln_fj1_07_03"] = "MİNİBÜS GERİ GELDİ. ÇANTALARI GÖTÜRÜN!",
["pln_fj1_07_04"] = "ARAÇ GELDİ. ÇANTALARI MİNİBÜSE GÖTÜRÜN!",
["pln_fj1_08_01"] = "MİNİBÜS GELİYOR. ÇANTALARI HAZIRLAYIN!",
["pln_fj1_08_02"] = "MİNİBÜS GERİ GELİYOR. HAZIR OLUN!",
["pln_fj1_08_03"] = "MİNİBÜSÜMÜZ DÖNÜYOR. HAZIR OLUN, YAKLAŞIYOR!",
["pln_fj1_09_01"] = "GEREKEN HER ŞEY TAMAM AMA DAHA FAZLASI İÇİN KALABİLİRSİNİZ.",
["pln_fj1_09_02"] = "GEREKEN BÜTÜN ÇANTALAR TAMAM AMA NE YAPACAĞINIZI BİLİYORSUNUZ. DAHA FAZLASINI İSTİYORSANIZ KALIP ALIN!",
["pln_fj1_09_03"] = "İHTİYACIMIZ OLAN MİKTAR BU. HAVANIZDAYSANIZ KALIP DAHA FAZLASINI ALABİLİRSİNİZ!",
["pln_fj1_10_01"] = "O KASAYI AÇIN, İÇİNDE İYİ BİR ŞEY VARDIR MUHTEMELEN.",
["pln_fj1_10_02"] = "OO, O KASA'DA BİZE EK GANİMET VAR GİBİ. AÇIN!",
["pln_fj1_11_01"] = "KASA AÇILDI. BAKALIM İÇİNDE NE VAR!",
["pln_fj1_11_02"] = "KASA AÇILDI. İÇİNDE NE VAR BAKIN!",
["pln_fj1_11_03"] = "KASA AÇILDI. BAKALIM NE VARMIŞ!",
["pln_fj1_12_01"] = "UNUTMAYIN, ÜÇ ÇANTA LAZIM!",
["pln_fj1_12_02"] = "MİLLET, ÜÇ ÇANTA, BİZE BU LAZIM.",
["pln_fj1_12_03"] = "BU İŞTE YANIMIZA ÜÇ ÇANTA ALMALIYIZ.",
