["pln_fj1_13_03"] = "BU İŞ İÇİN YANIMIZA ALTI ÇANTA ALMAMIZ GEREK.",
["pln_fj1_14_01"] = "UNUTMAYIN, SEKİZ ÇANTA LAZIM!",
["pln_fj1_14_02"] = "MİLLET, SEKİZ ÇANTA, İHTİYACIMIZ OLAN BU.",
["pln_fj1_14_03"] = "BU İŞ İÇİN YANIMIZA SEKİZ ÇANTA ALMAMIZ GEREK.",
["pln_fj1_15_01"] = "ARKAYA BAKIN!",
["pln_fj1_15_02"] = "İÇERİ BAŞKA GİRİŞ YOLLARI ARAYIN.",
["pln_fj1_brf_01_01"] = "SİVİLLERİ YERDE TUTUN, KAMERALARA DİKKAT EDİN. MEKÂNI KEŞFEDİN VE ALARMI ÇALDIRMADAN YAPMANIN EN İYİ YOLUNU BULUN.",
["pln_fj1_brf_01_02"] = "ARA SOKAKLARI KOLLAYIN, SİVİLLERİ YERDE TUTUN VE HIZLI ÇALIŞIN. BİRAZ MÜCEVHER ALALIM!",
["pln_fj1_brf_01_03"] = "MEKÂNI KEŞFEDİP SERT VURUN. MÜCEVHERLERİ ALIN, SİVİLLERİ KONTROL ALTINDA TUTUN. ZENGİN OLALIM!",
["pln_fj1_cbf_01_01"] = "ŞEHİR MERKEZİNDE BİR KUYUMCU VAR, OLDUKÇA KOLAY BİR HEDEF. AMA ALARM ÇALARSA POLİSLERİN GELMESİNE HAZIRLIKLI OLUN.",
["pln_fj1_cbf_01_02"] = "ŞEHİR MERKEZİNDEKİ YENİ KUYUMCU MÜCEVHER DOLU. BİZİM OLABİLİRLER. ZİYARET ETMEK İSTER MİSİNİZ?",
["pln_fj1_cbf_01_03"] = "ŞEHİR MERKEZİNDEKİ BİR KUYUMCU YENİ MÜCEVHER STOKLADI. O MÜCEVHERLER BİZİM OLABİLİR. VAR MISINIZ?",
["pln_fj1_cnc_01_01"] = "ZİYARET ETMEMİZ GEREKEN BİR KUYUMCU DAHA. VAR MISINIZ?",
["pln_fj1_cnc_01_02"] = "ŞEHİR MERKEZİNDE YENİ SEVKİYAT ALMIŞ BİR KUYUMCU VAR. VURUP KAÇMAYA VAR MISINIZ?",
["pln_fj1_cnc_01_03"] = "ŞEHİR MERKEZİNDEKİ BİR KUYUMCU ZİYARETİ HAK EDİYOR. SİZE GÖRE Mİ?",
["pln_fj1_end_01_01"] = "GERÇEK PROFESYONELLER, BEYLER! NEYE UĞRADIKLARINI BİLE BİLMİYORLAR!",
["pln_fj1_end_01_02"] = "PROFESYONELLER BÖYLE YAPAR! MUHTEŞEM İŞ BEYLER!",
["pln_fj1_end_02_01"] = "ORTALIK KARIŞTI AMA İŞİ BİTİRDİNİZ. İYİ İŞ!",
["pln_fj1_end_02_02"] = "ORTALIK KARIŞTI AMA BAZEN KARIŞIR. SONUNDA SİZ KAZANDINIZ. ÖNEMLİ OLAN BU. HARİKA İŞ!",
["pln_fj1_intro_01_01"] = "TAMAM, HAZIR OLUN! GEREKEN SAYIDA ÇANTAYI GETİRİN, GÜVENLİ EVDE BULUŞALIM.",
["pln_fj1_intro_01_02"] = "TAMAM, KUYUMCU ORASI. GEREKEN MİKTARI TOPLAYIN, HER ŞEYE HAZIR OLUN!",
["pln_fj1_intro_01_03"] = "GELDİK. GİRİP GEREKEN MİKTARI GETİRİN. SESSİZ GİRİP GÜMBÜR GÜMBÜR ÇIKACAĞIZ!",
["pln_flt_01_01"] = "TAMAM EKİP, İLERİDE CHAVEZ'İN EVİ VAR.",
