["pln_flt_04_02"] = "UYUŞTURUCU ALIŞVERİŞİNİ TAMAMLAMAYA GELMİŞ GİBİ DAVRANMALISINIZ.",
["pln_flt_04_03"] = "İÇERİ GİRİP ALIŞVERİŞİ BAŞLATIN.",
