["pln_flt_11_02"] = "HEY, BÜYÜK BİR DİŞ FIRÇASI BU... ALABİLİR MİYİM?",
["pln_flt_11_03"] = "O DA NE? DEV BİR DİŞ FIRÇASI MI? ÖYLE BİR ŞEY ÇOK İŞİME YARAR ASLINDA.",
["pln_flt_12_01"] = "LANET OLSUN, KAPI KİLİTLİ. BURASI CHAVEZ'İN MEKÂNI, ANAHTARI ONDADIR. BİNANIN ÜST KATLARINDA ONU BULMAYA ÇALIŞIN.",
["pln_flt_12_02"] = "ANAHTARSIZ O KAPIYI GEÇEMEYİZ... CHAVEZ'İ BULMA VAKTİ. PATRON O, ANAHTAR ONDA OLMALI.",
["pln_flt_12_03"] = "TAMAM, KAPI KİLİTLİ. ANAHTAR LAZIM OLACAK. BENCE CHAVEZ'İ BULMAK ANAHTARI BULMAK DEMEK. BİNADA CHAVEZ'İ ARAYIN.",
