["pln_flt_15_03"] = "O KAPIDAN GEÇMEK İÇİN CHAVEZ'İN ANAHTARI HÂLÂ LAZIM. BULUN ONU.",
["pln_flt_16_01"] = "TAMAM, ÖNCE İLK İŞ: TESTERELERİ KURUN.",
["pln_flt_16_02"] = "BU BEBEĞİ KESİP ÇIKARMA VAKTİ. TESTERELERİ YERLEŞTİRİN.",
