["pln_flt_17_01"] = "TESTERELERİ PANİK ODASININ ÇEVRESİNE KURUN. İKİSİ İKİNCİ KATTA, İKİSİ DÖRDÜNCÜ KATTA.",
["pln_flt_17_02"] = "DAİRE TESTERELERİ KURUN. İKİSİ GÜVENLİ ODANIN YANLARINA, İKİSİ ALTINDAKİ ZEMİNE.",
["pln_flt_17_03"] = "PLANIMIZIN İŞLEMESİ İÇİN TESTERELERİ KULLANMALISINIZ. İKİ TANE İKİNCİ KATA, İKİ TANE DÖRDÜNCÜ KATA. HADİ BAŞLAYIN.",
["pln_flt_18_01"] = "O TESTERELER ÇALIŞIR KALSIN. BİRİ SIKIŞIRSA HEMEN DÜZELTİN. SONSUZA KADAR KALAMAYIZ.",
["pln_flt_18_02"] = "TESTERELER DURMADAN ÇALIŞMALI. YANİ BİRİ SIKIŞIRSA DİYE GÖZÜNÜZÜ AÇIK TUTUN.",
["pln_flt_18_03"] = "TESTERELERDEN BİRİ SIKIŞIRSA FALAN DİYE GÖZÜNÜZÜ AÇIK TUTUN. BUNU ÇABUK BİTİRMELİYİZ.",
