["pln_flt_19_03"] = "TESTERELER HÂLÂ ÇALIŞIYOR MU?",
["pln_flt_20_01"] = "TESTERELER İŞİNİ YAPTI, MÜKEMMEL.",
["pln_flt_20_02"] = "TESTERELER BİTİRDİ. İYİ İŞ.",
["pln_flt_20_03"] = "SONUNDA TESTERELER İŞİNİ BİTİRDİ.",
["pln_flt_21_01"] = "TAMAM EKİP, BEKLEDİĞİMİZ GİBİ POLİSLER GELDİ. BİNAYI BASMADAN SOKAK SEVİYESİNDE İNDİRMEK DAHA KOLAY.",
["pln_flt_21_02"] = "POLİS BURADA. FIRSAT BULURLARSA BİNAYA DALACAKLAR, BELKİ ÖNCE DURDURURSUNUZ.",
["pln_flt_21_03"] = "POLİSLER GELİYOR. AŞAĞI İNİP ANA GİRİŞTE KARŞILARINA ÇIKMANIZI ÖNERİRİM. BÖYLECE BİNAYA DOLUŞMADAN ONLARI DURDURABİLİRSİNİZ.",
["pln_flt_22_01"] = "TAMAM, PLANIMIZIN SONRAKİ ADIMI: BILE'IN GETİRECEĞİ C4. BEKLEYİN, ONU BAĞLAYAYIM. 'BILE, ORADA MISIN? C4 LAZIM. NE KADAR SÜRER?'",
["pln_flt_22_02"] = "İYİ İŞ EKİP. ŞİMDİ BILE'DAN PATLAYICI ALMAMIZ GEREKİYOR. BİRAZ ZAMAN VERİN. 'BILE, VAKİT GELDİ. C4'Ü NE KADAR SÜREDE BIRAKABİLİRSİN?'",
["pln_flt_22_03"] = "İŞTE BU MİLLET, BAŞARIYORUZ. BİR SANİYE. \"HEY BILE, C4 ZAMANI GELDİ. NE KADAR ÇABUK GELİRSİN?\"",
["pln_flt_23_01"] = "DUYDUNUZ MU MİLLET? BILE BİRKAÇ DAKİKAYA C4'Ü ÇATIYA BIRAKACAK.",
["pln_flt_23_02"] = "ADAMI DUYDUNUZ. BILE C4'Ü BİRKAÇ DAKİKA İÇİNDE ÇATIYA BIRAKACAK.",
["pln_flt_23_03"] = "BILE C4'Ü BİNANIN ÇATISINA BIRAKACAK. HEMEN ALIN.",
["pln_flt_24_01"] = "AFERİN MİLLET. KESKİN NİŞANCILAR GİDİNCE BILE YÜKÜ BIRAKABİLİR.",
["pln_flt_24_02"] = "KESKİN NİŞANCILAR TAMAM, EKİP. ARTIK BILE'IN C4'Ü BIRAKMASINA HİÇBİR ŞEY ENGEL DEĞİL.",
["pln_flt_24_03"] = "İYİ GECELER KESKİN NİŞANCILAR! İYİ İŞ MİLLET. ŞİMDİ C4'Ü ALMA VAKTİ.",
["pln_flt_25_01"] = "LANET OLSUN ALE... BILE! ÇATIYI NASIL ISKALARSIN? EKİP, O C4 HÂLÂ LAZIM, GİDİP ALMANIZ GEREKECEK. UNUTMAYIN, PATLAYICILARI PANİK ODASININ ÜSTÜNDEKİ KATLARIN ETRAFINA İSTİYORUZ.",
["pln_flt_25_02"] = "HADİ AMA BILE, NE OLUYOR LAN? KUSURA BAKMAYIN MİLLET, C4'Ü YİNE ALIP PANİK ODASININ ÜSTÜNDEKİ KATLARIN ETRAFINA YERLEŞTİRMELİSİNİZ.",
["pln_flt_25_03"] = "CİDDEN Mİ BILE? ALEX'TEN BEKLERDİM AMA SENDEN DEĞİL... NEYSE EKİP, GİDİP C4'Ü ALIN VE PANİK ODASININ HEMEN ÜSTÜNDEKİ KATLARA YERLEŞTİRİN.",
["pln_flt_26_01"] = "C4'Ü ALIN, SONRA GÜVENLİ ODANIN HEMEN ÜSTÜNDEKİ ZEMİNE YERLEŞTİRİN.",
["pln_flt_26_02"] = "TAMAM, GİDİP C4'Ü ALIN, SONRA TAM PANİK ODASININ ÜSTÜNE YERLEŞTİRİN.",
["pln_flt_26_03"] = "C4'Ü ALIP PANİK ODASININ ÜSTÜNDEKİ KATLARIN ZEMİNLERİNE YERLEŞTİRME VAKTİ.",
["pln_flt_27_01"] = "İYİ İŞ AMA DÖRDÜNCÜ KATA BİRAZ DAHA GEREKİYOR.",
["pln_flt_27_02"] = "TAMAMDIR, EKİP. SADECE DÖRDÜNCÜ KAT KALDI.",
["pln_flt_27_03"] = "DÖRDÜNCÜ KATA HÂLÂ DAHA FAZLA C4 GEREKİYOR EKİP.",
["pln_flt_28_01"] = "İŞTE BÖYLE MİLLET AMA BEŞİNCİ KATA VE ÇATIYA HÂLÂ DAHA FAZLA C4 YERLEŞTİRMELİYİZ.",
["pln_flt_28_02"] = "HARİKA. ŞİMDİ BEŞİNCİ KATA BİRAZ DAHA, SONRA ÇATIYA DA BİRAZ GEREKİYOR.",
