["pln_flt_30_02"] = "MÜKEMMEL EKİP. ŞİMDİ DÖRDÜNCÜ KATA VE ÇATIYA BİRAZ DAHA YERLEŞTİRİN.",
["pln_flt_30_03"] = "DÖRDÜNCÜ KATA VE ÇATIYA DAHA FAZLA C4 LAZIM.",
["pln_flt_31_01"] = "AZ KALDI MİLLET. ÇATIYA BİRAZ DAHA KOYDUK MU TAMAMIZ.",
["pln_flt_31_02"] = "SON C4'Ü ÇATIYA YERLEŞTİRİN, GİTMEYE HAZIR OLURUZ.",
["pln_flt_31_03"] = "İŞTE BU EKİP, ARTIK SADECE ÇATI KALDI.",
