["pln_flt_36_01"] = "TAMAM, İŞTE BU! ŞİMDİ GERİ ÇEKİLİN, BURASI PATLAMAK ÜZERE!",
["pln_flt_36_02"] = "MÜKEMMEL! ŞİMDİ GERİ ÇEKİLİN, ORTALIK PATLAMAK ÜZERE.",
