["pln_flt_41_01"] = "BILE, YÜKÜ ALMAYA GELMEYE HAZIR MISIN?",
["pln_flt_41_02"] = "BILE! DÖNÜP YÜKÜ ALMA VAKTİ GELDİ. NE KADAR ÇABUK DÖNEBİLİRSİN?",
["pln_flt_41_03"] = "BILE, SIRA SENDE! NE ZAMANA GELİRSİN?",
["pln_flt_42_01"] = "BİNA İSVİÇRE PEYNİRİ GİBİ DELİK DEŞİK OLUYOR! DAHA İYİ BİR TAKTİK KONUM ALMAK İÇİN BİRKAÇ KAT YUKARI ÇIKMANIZI ÖNERİRİM.",
["pln_flt_42_02"] = "TAMAM EKİP, GELİYORLAR! SAVUNMAK İÇİN İYİ BİR MEVZİ BULUN! NEREDEYSE BİTTİ!",
["pln_flt_42_03"] = "POLİSLER ÜST KATLARDAN GELİYOR. YUKARI ÇIKIP SAVUNACAK DAR BİR GEÇİT BULMALISINIZ!",
["pln_flt_43_01"] = "TAMAM, ÇEKME VİNCİ SABİTLENDİ. ŞU PAKETİ BURADAN ÇEKELİM!",
["pln_flt_43_02"] = "İŞTE BU. BU BEBEĞİ BURADAN KALDIRMAYA HAZIRIM.",
["pln_flt_43_03"] = "MIKNATIS YERİNDE. BURADAN ÇEKİP ÇIKARMA VAKTİ.",
["pln_flt_44_01"] = "ŞU ODANIN GİDİŞİNE BAKIN! BAŞARDIK BE!",
["pln_flt_44_02"] = "ŞUNA BAKAR MISINIZ!? BAŞARDIK, EKİP. BAŞARDIK.",
["pln_flt_44_03"] = "HAVALANDIK!",
["pln_flt_45_01"] = "MÜKEMMEL İŞ, EKİP! KESİNLİKLE İNANILMAZ. AMA ŞİMDİ BİNA ÇÖKMEDEN ÇIKMANIZ GEREK.",
["pln_flt_45_02"] = "İYİ İŞ! ŞİMDİ BİNA BAŞIMIZA YIKILMADAN ÇIKMA VAKTİ. HADİ!",
["pln_flt_45_03"] = "HARİKA İŞ ÇIKARDINIZ! ŞİMDİ ÇABUCAK DEFOLUP GİDİN ORADAN. O BİNA DAHA FAZLA AYAKTA KALMAYACAK.",
["pln_flt_46_01"] = "HERKES KANALİZASYONA İNSİN!",
["pln_flt_46_02"] = "BODRUMA İNİN MİLLET!",
["pln_flt_46_03"] = "ARKA SOKAKTAKİ BODRUM KAPISINA İNİN!",
["pln_flt_47_01"] = "HERKES KANALİZASYONA İNSİN!",
["pln_flt_47_02"] = "BODRUMA İNİN MİLLET!",
["pln_flt_47_03"] = "ARKA SOKAKTAKİ BODRUM KAPISINA GİDİN!",
["pln_flt_48_01"] = "TAMAM, ARTIK GERİ DÖNÜŞ NOKTASINI GEÇTİNİZ... KOŞUN! KOŞUN! ARKANIZA BAKMAYIN!",
["pln_flt_48_02"] = "KOŞUN! SADECE KOŞUN!",
["pln_flt_48_03"] = "ÇIKIN ORADAN! KOŞUN!",
["pln_flt_49_01"] = "ACELE EDİN! ACELE EDİN! SOLA!",
["pln_flt_49_02"] = "GİDİN! GİDİN! GİDİN! KOŞUN SADECE!",
["pln_flt_49_03"] = "DAHA HIZLI, MİLLET!",
["pln_flt_50_01"] = "BİZİM AZ ÖNCE YAPTIĞIMIZI KİM YAPABİLİR? HİÇ KİMSE! DEDİĞİM GİBİ, BU İŞ TARİHE GEÇECEK.",
["pln_flt_50_02"] = "BU İNSANLARI KONUŞTURMAYACAKSA NE KONUŞTURUR BİLMEM. İNANILMAZDI EKİP. BUNDAN DA GÜZEL BİR ÖDEME ALACAĞIZ.",
["pln_flt_50_03"] = "İNSANLARIN İMKÂNSIZ DİYECEĞİ BİR ŞEYİ YAPTIK. YAPAMAYACAĞIMIZ HİÇBİR ŞEY YOK EKİP. EN İYİLERİN EN İYİSİYİZ.",
["pln_flt_brf_01"] = "TOPLU KONUTLARIN İÇ TARAFLARINDA GÜÇLENDİRİLMİŞ BİR BİNA VAR. O BİNANIN İÇİNDE DE ZEMİNE CIVATALANMIŞ BİR PANİK ODASI. PANİK ODASI NAKİT DOLU. BİNAYA GİRMEK KOLAY AMA PANİK ODASINA NASIL GİRECEKSİNİZ? GİREMEZSENİZ PARAYLA NASIL ÇIKACAKSINIZ? BASİT, BÜTÜN ODAYI ÇALIN. HADİ YAPALIM.",
["pln_flt_cbf_01"] = "İYİ PARA KAZANMAK İÇİN BAZEN İŞİ AŞIRIYA GÖTÜRMEK GEREKİR. BU SEFER TAM OLARAK ONU YAPIYORUZ. BİNAYA GİRİN, GÜVENLİ ODAYI BULUN, SONRA HELİKOPTERLE BÜTÜN LANET ODAYI ÇALIN.",
["pln_flt_cnc_01"] = "CHAVEZ'İN PARA DOLU BİR PANİK ODASI VAR, BİZ DE ODANIN TAMAMINI ÇALACAĞIZ. EVET, DOĞRU DUYDUNUZ.",
["pln_flt_cnc_02"] = "CHAVEZ'İN EVİNE GİREN SIRADAN UYUŞTURUCU SATICILARI GİBİ DAVRANACAĞIZ. AMA ORAYA VARINCA ONLARI KAZIKLAYIP PARAYLA DOLU GİZLİ PANİK ODASINA YÖNELECEĞİZ.",
["pln_flt_cnc_03"] = "CHAVEZ BASİT BİR UYUŞTURUCU ALIŞVERİŞİ İSTEDİĞİMİZİ SANIYOR AMA ASLINDA PARAYLA DOLU GİZLİ PANİK ODASININ PEŞİNDEYİZ.",
["pln_flt_intro_01"] = "BUNU BAŞARIRSAK BÜTÜN SUÇ DÜNYASI SONSUZA KADAR BU İŞİ KONUŞACAK. HANIMLAR VE BEYLER, TARİH BÖYLE YAZILIR.",
["pln_flt_intro_02"] = "EFSANE OLMAYA HAZIR MISINIZ?",
["pln_flt_intro_03"] = "BU İŞ İÇİN ATEŞLİYİM EKİP. CHAVEZ NEYE UĞRADIĞINI ANLAMAYACAK.",
["pln_fost_brf_01_01"] = "TAMAM, DC'YE ALIŞMAK İÇİN KOLAY BİR İŞ BU.",
["pln_fost_brf_01_02"] = "BAŞLANGIÇTA SİZİ FAZLA ZORLAMAYACAĞIZ. VLAD SADECE BİR MESAJ VERMENİZİ İSTİYOR.",
["pln_fost_brf_02_01"] = "BU KÜÇÜK ALIŞVERİŞ SIRASINDAKİ DÜKKÂNLARI YAĞMALAYIN.",
["pln_fost_brf_02_02"] = "BURADAKİ DÜKKÂNLARI SOYUN. VLAD BİR NAKİT HEDEFİ VERDİ. FAZLASI SİZİN.",
["pln_fost_brf_03_01"] = "TOPLAYIN... EN AZ 15 BİN, SONRA ŞOFÖRÜ SİZİ ALMAYA GÖNDERİRİM.",
["pln_fost_brf_03_02"] = "ANLAŞTIĞIMIZ MİKTARDA NAKDİ TOPLAYIN, ŞOFÖRÜ GÖNDEREYİM. FAZLASI DA BONUS OLUR.",
["pln_fost_brf_03_03"] = "TAMAM, ASGARİ MİKTARDA NAKİT TOPLAMAMIZ GEREKİYOR. O MİKTARA ULAŞINCA SİZE BİR ARABA YOLLARIM. KALIP DAHA FAZLASINI ALMAK İSTERSENİZ DE BUYURUN.",
["pln_fost_brf_04_01"] = "KULAĞA İYİ GELİYOR MU? HADİ GİDELİM!",
["pln_fost_brf_04_02"] = "TAMAM, ŞU İŞİ YAPALIM.",
["pln_fost_brf_05_01"] = "ANLADINIZ MI? TAMAM. VLAD PARASINI İSTİYOR. GİDİP ALIN.",
["pln_fost_brf_05_02"] = "VLAD'İN PARASINI ALMA VAKTİ.",
["pln_fost_cam_01_01"] = "KAMERALARI VAR, DEVRE DIŞI BIRAKIN.",
["pln_fost_cam_02_01"] = "KAMERALARI VAR GİBİ GÖRÜNÜYOR... ALARMLARA DİKKAT EDİN.",
["pln_fost_cam_03_01"] = "KAMERALAR MI? BİR DE MUHAFIZLAR MI? VLAD BUNDAN HİÇ BAHSETMEDİ!",
["pln_fost_cam_03_02"] = "HER ZAMANKİ GİBİ VLAD FAZLA BİLGİ VERMEMİŞ. KAMERALAR VE GÜVENLİKÇİLER... SİKTİR.",
["pln_fost_cs_01_01"] = "BOKUNG... SONUNDA İYİ BİR PORSELEN DÜKKÂNI!",
["pln_fost_en_01_01"] = "GÜZEL, İYİ PARA.",
["pln_fost_en_01_02"] = "HARİKA, ŞU PARAYI İYİ DEĞERLENDİRELİM.",
["pln_fost_en_01_03"] = "BİZE DAHA FAZLA PARA.",
["pln_fost_en_02_01"] = "TAMAM, ON BEŞ BİN OLDU! ŞOFÖRÜ SİZİ ALMAYA GÖNDERECEĞİM.",
["pln_fost_en_03_01"] = "TAMAM, ANLAŞTIĞIMIZ ASGARİ MİKTAR BU. ŞOFÖRÜ ÇAĞIRIYORUM.",
["pln_fost_en_03_02"] = "İHTİYACIMIZ OLAN ŞEY BU. ŞOFÖRÜ ARIYORUM.",
["pln_fost_en_03_03"] = "YETERİNCE ALDINIZ. ADAMIMIZI YOLA ÇIKARACAĞIM.",
["pln_fost_en_03_04"] = "VLAD'İN MUTLU OLMASI İÇİN YETERLİ.",
["pln_fost_msk_01_01"] = "BAŞLAMAYA HAZIR OLDUĞUNUZDA MASKELERİ TAKIN.",
["pln_fost_msk_02_01"] = "İŞE BAŞLAMAYA HAZIR OLUNCA MASKELERİNİZİ TAKIN!",
["pln_fost_msk_02_02"] = "NE ZAMAN BAŞLAMAK İSTERSENİZ MASKELERİ TAKIN.",
["pln_fost_ne_01_01"] = "TAMAM, BİRAZ AZ.",
["pln_fost_ne_01_02"] = "TAMAM, ARAMAYA DEVAM EDİN.",
["pln_fost_sfe_01_01"] = "VAY, BUNUN İÇİ DEĞERLİ EŞYALARLA DOLU OLMALI! VLAD'IN BU İŞLETMELERİN PARASINI NEDEN İSTEDİĞİNİ ANLAYABİLİYORUM...",
["pln_fost_sfe_01_02"] = "BÜYÜK KASAYMIŞ, AÇABİLİYOR MUSUNUZ BAKIN!",
["pln_fost_sfe_01_03"] = "ŞUNU AÇIN.",
["pln_fost_sfe_01_04"] = "GÜZEL BOYUT. BAKALIM İÇİNDE BİR ŞEY VAR MI.",
["pln_fost_sfe_02_01"] = "BUM! ALTIN DAMARINI BULDUNUZ!",
["pln_fost_sfe_02_02"] = "BAM, İŞ ŞİMDİ CİDDİYE BİNDİ.",
["pln_fost_vh_01_01"] = "MİNİBÜS GELDİ. BİTTİYSENİZ GİDİN. BİTMEDİYSENİZ İŞİNİZ BİTENE KADAR BEKLER.",
["pln_fost_vh_01_02"] = "MİNİBÜS GELDİ. HAZIR OLUNCA ÇIKIN. BEKLEYECEK.",
["pln_fourstores_stage1_brief_01"] = "BAKIN, VLAD'IN ÇATLAK OLDUĞUNU BİLİYORUM. AMA ÇOK BAĞLANTISI VAR. İLERİDE BİZİ BÜYÜK İŞLERE GÖTÜREBİLECEĞİ KONUSUNDA İÇİMDEN İYİ BİR HİS GEÇİYOR. ",
["pln_fourstores_stage1_brief_01b"] = "BU İYİ BİR BAŞLANGIÇ... ORTALIK KIZIŞANA KADAR SOĞUKKANLI KALIN YETER...",
["pln_fourstores_stage1_end_a_01"] = "İYİ İŞ MİLLET. HEM SESSİZ KALDINIZ HEM MESAJI VERDİNİZ. PARALARI GİTTİ. VLAD DA ONUN EKİBİNDEN OLDUĞUNUZU ONLARA MUTLAKA SÖYLEYECEK.",
["pln_fourstores_stage1_end_a_02"] = "İYİ İŞ MİLLET. SİNSİ, MESAJ ALINDI. GANİMET GİTTİ, VLAD DE KORKULAN ADAMLAR LİSTESİNDE KESİNLİKLE YÜKSELECEK.",
["pln_fourstores_stage1_end_a_03"] = "ORTALIKTA TEK BİR POLİS YOK. TAM KONTROL SİZDEYDİ. ŞİMDİ VLAD'I ARAYIP MÜJDEYİ VERECEĞİM.",
["pln_fourstores_stage1_end_b_01"] = "PARA GÜVENE ALINDI, POLİSLER NELER YAPABİLDİĞİMİZİN TADINA BAKTI. VLAD DE BUNU MUTLAKA KENDİ LEHİNE KULLANIR. GÜZEL.",
["pln_fourstores_stage1_end_b_02"] = "VLAD'IN İTİBARI YÜKSELECEK. SİZ DE BU İŞTEN GÜZEL BİR PARA ALACAKSINIZ.",
["pln_fourstores_stage1_end_b_03"] = "BİRAZ AŞIRI OLDU AMA AŞKTA VE SAVAŞTA HER ŞEY MUBAH HERHÂLDE. VLAD İÇİN DAHA ÇOK SAVAŞTA.",
["pln_fourstores_stage1_end_b_04"] = "PARAMIZI ALMAK İÇİN VLAD'A GİDELİM. EKİBİNİZİ O UFAK ARBEDE İÇİNDEN ÇIKARDINIZ, İYİ İŞ.",
["pln_fourstores_stage1_end_b_05"] = "TAMAM, PARA GÜVENDE. VLAD VOTKALARI ALIR KESİN, POLİSLERE DE BİRAZ GEREKECEK...",
["pln_fourstores_stage1_end_b_06"] = "KÜÇÜK BİR VURGUN İÇİN BAŞIMIZA ÇOK POLİS TOPLADIK AMA VLAD'I SEVİNDİRMEYE DEĞER. UZUN VADEDE KARŞILIĞINI ALIRIZ.",
["pln_fourstores_stage1_intro_a_01"] = "TAMAM, VLAD'IN ESKİ MAHALLESİNE YAKLAŞIYORUZ. İÇERİ GİRİP VLAD'IN PARASINI ALIN. BU İNSANLARA ÇILGIN VLAD'DAN KİMSENİN KAÇAMAYACAĞINI GÖSTERİN. POLİS TEPENİZE BİNMEDEN SIVIŞIN.",
["pln_fourstores_stage1_intro_a_02"] = "YAZAR KASALARA, VİTRİNLERE, DENK GELEN KASALARA YÖNELİN. VLAD'I MEMNUN EDECEK KADAR PARA ALIP ÇIKIN. OYALANMAYIN. KOLAY BİR İŞ. ",
["pln_fourstores_stage1_intro_a_03"] = "VLAD DÖRT DÜKKÂNI VURUP NAKİT VE DİĞER IVIR ZIVIRLARI ALMAMIZI İSTİYOR. ONA NASIL HIZLI VE TEMİZ ÇALIŞTIĞIMIZI GÖSTERİN. KOLAYCA GİRİP ÇIKIN. ",
["pln_framing_stage1_01_any_01"] = "TAMAM MİLLET, İÇERİ GİRİP ESERLERİ BULUN. KIRMIZI ÇIKARTMALI TABLOLARI İSTİYORUZ. MUHAFIZLARA VE KAMERALARA DİKKAT EDİN.",
["pln_framing_stage1_01_any_02"] = "TAMAM, DURUM ŞU: ÜSTÜNDE KIRMIZI ETİKET OLAN TABLOLARI ARIYORUZ. GÜVENLİK EPEY SIKI OLACAK, KAMERALAR VE MUHAFIZLAR VAR.",
["pln_framing_stage1_01_any_03"] = "HAZIR MISINIZ? TAMAM, DİNLEYİN: ÜZERİNDE KIRMIZI ÇIKARTMA OLAN TABLOLARI ARIYORSUNUZ. BURADA GÜVENLİK ALIŞILMADIK DERECEDE SIKI. BİR SÜRÜ KAMERA, HATTA GÜVENLİK ODASI BİLE VAR. O YÜZDEN İYİ KEŞİF YAPIN.",
["pln_framing_stage1_02_any_01"] = "TAMAM, İÇERİDESİNİZ. KIRMIZI ETİKETLİ TABLOLARI BULUN, EN AZ DÖRT İSTİYORUZ.",
["pln_framing_stage1_02_any_02"] = "PEKÂLÂ... TAMAM, EN AZ DÖRT TABLO LAZIM. UNUTMAYIN, KIRMIZI ETİKETLİLERDEN.",
["pln_framing_stage1_02_any_03"] = "TAMAM, İÇERİDESİNİZ, GÜZEL. ŞİMDİ EN AZ DÖRT TABLO LAZIM. İYİ OLANLARIN ÜZERİNDE KIRMIZI ETİKET VAR; SANATSEVERİMİZ ONLARI SATIN ALMAK İSTİYOR.",
["pln_framing_stage1_02_any_04"] = "AFERİN MİLLET. ŞİMDİ KIRMIZI ÇIKARTMALI TABLOLARI ARIYORSUNUZ. DEMOKRATIN İSTEDİKLERİ ONLAR. EN AZ DÖRT TANE ALIN. ",
["pln_framing_stage1_03_any_01"] = "KAHRETSİN! ALARM ÇALDI!",
["pln_framing_stage1_04_any_01"] = "DİNLEYİN, GÖZETİM ODASINDAKİ BİLGİSAYARA ERİŞİM VERİRSENİZ AÇARIM.",
["pln_framing_stage1_04_any_02"] = "TAMAM, ARTIK OYALANAMAYIZ. GÖZETLEME ODASINDAKİ BİLGİSAYARA ERİŞMEMİ SAĞLAYIN YETER, UZAKTAN HALLEDERİM.",
["pln_framing_stage1_04_any_03"] = "HENÜZ YETERİNCE TABLOMUZ YOK! BİRİ BENİ GÖZETLEME ODASINDAKİ BİLGİSAYARA ÇABUK BAĞLAYABİLİR Mİ? BEN AÇARIM, O GÜZEL KAFALARINIZI YORMAYIN.",
["pln_framing_stage1_05_any_01"] = "TAMAM, İSTERSENİZ GİTMEYE YETECEK KADAR ALDIK. AMA DAHA FAZLASINI İSTİYORSAK GÖZETİM ODASINA ERİŞİM SAĞLAYIN DA AĞLARINDA NE VAR GÖREYİM.",
["pln_framing_stage1_05_any_02"] = "TAMAM EKİP, ARTIK DEFOLUP GİTMEYE YETECEK KADAR ALDINIZ. DAHA FAZLASINI İSTİYORSANIZ GÖZETİM ODASINA ERİŞİMİM GEREKİYOR. İÇERİ GİRİNCE GERİSİNİ HALLEDERİM.",
["pln_framing_stage1_06_any_01"] = "KAHRETSİN! HER ŞEY TEKRAR AÇILSIN İSTİYORSANIZ GÜVENLİK ODASINA GİRMELİSİNİZ.",
["pln_framing_stage1_06_any_02"] = "HER ŞEY KİLİTLENDİ. DÜZELTMEMİ İSTİYORSANIZ GÖZETİM ODASINA GİRMEM GEREK.",
["pln_framing_stage1_06_any_03"] = "KİLİT ALTINDA KALDIK... AÇMAMI İSTİYORSANIZ GÖZETİM ODASINI ÇABUCAK AÇMALISINIZ.",
["pln_framing_stage1_07_any_01"] = "DIŞARIDA BEKLEYEMEYİZ; O BİNAYA OLABİLDİĞİNCE HIZLI GİRİN. ÇATIYI DENEYİN.",
["pln_framing_stage1_07_any_02"] = "BEKLEYECEK VAKTİMİZ YOK. İÇERİ GİRMENİN YOLUNU BULAMIYOR MUSUNUZ? ÇATI NASIL?",
["pln_framing_stage1_08_any_01"] = "ETRAFA BAKIN, BİR GİRİŞ YOLU OLMALI. DEĞERLİ VAKİT KAYBEDİYORUZ.",
["pln_framing_stage1_08_any_02"] = "YUKARIDAN GİDEN YOLLARA BAKTINIZ MI? ORALARDA İÇERİ ERİŞİM OLMALI.",
["pln_framing_stage1_08_any_03"] = "ÇATIYA BAKIN, İÇERİ GİRECEK BİR YOL BULUN. YARATICI OLUN, VAKTİMİZ YOK.",
["pln_framing_stage1_09_any_01"] = "HARİKA, EN AZ 3 TANE DAHA GEREK. BUNU MİNİBÜSE GÖTÜRÜN. GALERİNİN YANINDAKİ OTOPARKTA.",
["pln_framing_stage1_09_any_02"] = "GÜZEL, ŞİMDİ BUNUN GİBİ EN AZ 3 TANE DAHA LAZIM. MİNİBÜSE GÖTÜRMELİSİNİZ. GALERİNİN YANINDAKİ OTOPARKTA.",
["pln_framing_stage1_09_any_03"] = "TAMAM, BU BİR BAŞLANGIÇ. BUNUN GİBİ ÜÇ TANE DAHA LAZIM. ALIN! GALERİNİN YANINDAKİ OTOPARKTA DURAN MİNİBÜSE GÖTÜRÜN, İŞİ BİTİRELİM.",
["pln_framing_stage1_10_any_01"] = "YARISI TAMAM, 2 TANE DAHA LAZIM.",
["pln_framing_stage1_10_any_02"] = "GEREKEN TABLOLARIN YARISI TAMAM. GİTMEDEN ÖNCE KALANINI DA ALMANIZ GEREK.",
["pln_framing_stage1_10_any_03"] = "TABLO KOLEKSİYONUNU YARILADIK. KALANI DA ALIN, KURTULALIM.",
["pln_framing_stage1_11_any_01"] = "DÖRT OLDU, ARTIK GİDEBİLİRİZ. KALAN TABLOLARI ALMAK İSTİYORSANIZ SİZE KALMIŞ.",
["pln_framing_stage1_11_any_02"] = "DÖRT TANE ALDIK, GEREKEN DE DÖRT. DAHA FAZLASINI İSTİYORSANIZ KARAR SİZİN.",
["pln_framing_stage1_12_any_01"] = "İŞTE BU, KAPILAR TAMAM. TABLOLAR ÜZERİNDE HÂLÂ ÇALIŞIYORUM.",
["pln_framing_stage1_12_any_02"] = "İŞTE BÖYLE, BALO ELBİSESİ GİBİ SIYRILDI. TABLOLARLA HÂLÂ UĞRAŞIYORUM.",
["pln_framing_stage1_13_any_01"] = "EVET! SİSTEM KIRILDI, ARTIK HER ŞEYİN KİLİDİ AÇILMIŞ OLMALI.",
["pln_framing_stage1_13_any_02"] = "TAMAM, TAMAM, GÜVENLİK SİSTEMİNİ HACKLEDİM. BÜTÜN KİLİTLER AÇILDI.",
["pln_framing_stage1_14_any_01"] = "GÜZEL, O ADAM DEVREDEN ÇIKINCA KAMERA DA KALMADI.",
["pln_framing_stage1_14_any_02"] = "HARİKA, KAMERA ALARMI DA BÖYLECE BİTTİ.",
["pln_framing_stage1_15_any_01"] = "SWAT MÜDAHALE EKİPLERİ SERT GELİYOR. MEVZİ ALIN.",
["pln_framing_stage1_15_any_02"] = "SWAT BİRİMLERİ BİNAYA GİRİYOR, HAZIR OLUN!",
["pln_framing_stage1_15_any_03"] = "SWAT'LAR OLAY YERİNDE... BAŞLIYORUZ.",
["pln_framing_stage1_16_any_01"] = "DUVARDA DELİK AÇTILAR! ONLARI GERİ PÜSKÜRTÜN!",
["pln_framing_stage1_16_any_02"] = "SWAT EKİPLERİ AZ ÖNCE DUVARI YARDI!",
["pln_framing_stage1_16_any_03"] = "DUVARI KIRIP GİRİYORLAR!",
["pln_framing_stage1_16_any_04"] = "DUVARI PATLATIYORLAR!",
["pln_framing_stage1_17_any_01"] = "BAĞLANIYOR... BİR DAKİKA SÜREBİLİR.",
["pln_framing_stage1_brief_01"] = "SENATÖR SANAT ESERİ TOPLAMAYA BAYILIYOR, ÖZELLİKLE DE ANA AKIM DIŞINDAKİ SANATA. NEYSE Kİ CAPİTOL ART GALLERY BU HAFTA BİR SERGİYE EV SAHİPLİĞİ YAPIYOR.",
["pln_framing_stage1_brief_01b"] = "İŞARETLİ TABLOLARI SENATÖRÜN DAİRESİNE GÖTÜRMENİZ GEREK. İÇLERİNE KAMERA YERLEŞTİRİLECEK. İÇERİDE GÖZÜMÜZ OLMASI İŞİNİZİ KOLAYLAŞTIRACAK, GÜVENİN BANA.",
["pln_framing_stage1_end_a_01"] = "TEKRAR HOŞ GELDİNİZ EKİP. ŞİMDİ TABLOLARA KAMERALARI YERLEŞTİRİP SENATÖRÜN ADAMLARIYLA TAKAS EDECEĞİZ VE BU SİLAH TÜCCARI HER KİMSE ONU GÖRECEĞİZ.",
["pln_framing_stage1_end_a_01b"] = "SENATÖRÜN ADAMLARIYLA BAĞLANTIYA GEÇİP TABLOLARI BİZDEN ALMAYA İKNA EDECEĞİM.",
["pln_framing_stage1_end_a_02"] = "İYİ İŞ EKİP. MİKRO KAMERALAR TABLOLARA YERLEŞTİRİLDİĞİNE GÖRE, ARTIK BUNLARI SENATÖRÜN ADAMLARINA VERMEMİZ YETER. GÖRÜŞMEYİ HEMEN AYARLIYORUM.",
["pln_framing_stage1_end_b_01"] = "MÜKEMMEL İŞ. BU TABLOLAR SENATÖRÜN DAİRESİNE YERLEŞİNCE İÇERİYİ BOL BOL GÖREBİLECEĞİZ. TRUVA ATI GİBİ AMA BİR SÜRÜ.",
["pln_framing_stage1_end_b_01b"] = "SENATÖRÜN ADAMLARIYLA TAKASI AYARLAYIP İŞİ İLERLETECEĞİM.",
["pln_framing_stage1_end_b_02"] = "MEKÂNI SİLİP SÜPÜRDÜNÜZ. ARTIK SENATÖRÜN DAİRESİNİ EKSİKSİZ GÖRECEĞİZ. GÖZETİM EKİPMANINI TABLOLARA YERLEŞTİRİP TAKASI AYARLAYACAĞIM.",
["pln_framing_stage1_end_b_02b"] = "SONRA SADECE İÇERİ GİRİP ALTINLARI ALMAMIZ GEREKİYOR.",
["pln_framing_stage1_intro_a_01"] = "GALERİYE VARMAK ÜZERESİNİZ. KAMERALARDAN, GÜVENLİKÇİLERDEN VE HAREKET ALGILAYICILARDAN KAÇINIP İÇERİ SÜZÜLÜN. BOMBA TEHDİDİ YÜZÜNDEN GÜVENLİK SIKI.",
["pln_framing_stage1_intro_a_01b"] = "NEYSE, SATILDI DİYE İŞARETLENEN TABLOLARI BULUP ALIN. GARANTİ OLSUN DİYE EN AZ DÖRT TANE LAZIM.",
["pln_framing_stage1_intro_a_02"] = "GALERİ BU. ÜZERİNDE KIRMIZI ‘SATILDI’ ÇIKARTMASI OLAN TABLOLARI ARIYORSUNUZ. İŞİN OLMASI İÇİN EN AZ DÖRT TANE LAZIM. BURASI KAPALI VE KİLİTLİ. GİRİŞ YOLU BULUN. HADİ.",
["pln_framing_stage1_intro_a_03"] = "TAMAM, GALERİ İLERİDE. HAREKET ALGILAYICILARA, KAMERALARA VE GÜVENLİKÇİLERE DİKKAT EDİN. GİRİP KIRMIZI SATILDI ETİKETİ OLAN TABLOLARDAN DÖRT TANE GETİRİN. ZAMAN DARALIYOR MİLLET.",
["pln_framing_stage1_intro_a_04"] = "GÜVENLİK SİSTEMLERİYLE MUHAFIZLARDAN UZAK DURURSANIZ KOLAY OLACAK. EH, BELKİ O KADAR KOLAY DEĞİL. KIRMIZI SATILDI ETİKETLİ TABLOLARI ALIP ÇIKIN. EN AZ DÖRT LAZIM.",
["pln_framing_stage2_01_any_01"] = "TAMAM MİLLET, TELEFONU AÇIN. ŞU TAKASI ARADAN ÇIKARALIM.",
["pln_framing_stage2_01_any_02"] = "TELEFONA GİDİN, TELEFON ÇALIYOR. BAĞLANTIYI ORADAN KURUN.",
["pln_framing_stage2_01_any_03"] = "TELEFON ÇALIYOR. AÇIP TAKASI BAŞLATMA VAKTİ.",
["pln_framing_stage2_02_any_01"] = "BİRİ TELEFONA CEVAP VERSİN...",
["pln_framing_stage2_02_any_02"] = "BİRİ CEVAP VERECEK Mİ? SİZ CEVAP VERMEDEN TAKAS BAŞLAYAMAZ...",
["pln_framing_stage2_03_any_01"] = "BAYAĞI GERGİNLER. TABLOLARI MASAYA KOYUN, TUHAF ŞEYLERE KARŞI İKİ GÖZÜNÜZ DE AÇIK OLSUN.",
["pln_framing_stage2_03_any_02"] = "HOŞUMA GİTMEDİ... BİR AN ÖNCE BİTİRELİM, TABLOLARI MASAYA KOYUN.",
["pln_framing_stage2_03_any_03"] = "BU İŞTE BİR TUHAFLIK VAR AMA BİLMİYORUM. TABLOLARI MASAYA KOYUN, ÖRÜMCEK HİSLERİNİZİ AÇIK TUTUN.",
["pln_framing_stage2_05_any_01"] = "HEPSİ TAMAM, ARAMALARINI BEKLEYİN.",
["pln_framing_stage2_05_any_02"] = "TAMAM, ŞİMDİ UMALIM DA SİZİ ÇABUCAK ARASINLAR.",
["pln_framing_stage2_05_any_03"] = "PEKÂLÂ, SADECE SİZİ GERİ ARAMALARI GEREK. NE KADAR HIZLI, O KADAR İYİ.",
["pln_framing_stage2_06_any_01"] = "İŞTE, TELEFONA CEVAP VERİN.",
["pln_framing_stage2_06_any_02"] = "BİNGO. CEVAP VERİN.",
["pln_framing_stage2_06_any_03"] = "TAMAM, ARAYAN ONLAR.",
["pln_framing_stage2_07_any_01"] = "TAMAM MİLLET, HERKES TRENE.",
["pln_framing_stage2_07_any_02"] = "HERKESİ TRENE BİNDİRİN.",
["pln_framing_stage2_09_any_01"] = "TAMAM, UNUTMAYIN: HER TABLO İÇİN BİR ÇANTA PARA.",
["pln_framing_stage2_09_any_02"] = "ŞİMDİ BEKLİYORUZ. UNUTMAYIN, HELİKOPTERE ATTIĞIMIZ HER TABLOYA BİR ÇANTA NAKİT ALIYORUZ. SABIRLI VE ŞANSLI OLMAMIZ YETER. ",
["pln_framing_stage2_10_any_01"] = "TAMAM, GÜZEL. O BİNANIN ÖBÜR TARAFINDA SİZİ BEKLEYEN BİR MİNİBÜS VAR. İÇİNDEN GEÇİN, ARACI YÜKLEYİN, BUGÜNLÜK İŞİMİZ BİTSİN.",
["pln_framing_stage2_10_any_02"] = "BURADA İŞİMİZ BİTTİ. BİNANIN ÖBÜR TARAFINDA MİNİBÜS BEKLİYOR. GEÇİN, ARABAYI YÜKLEYİN, İŞ BİTSİN.",
["pln_framing_stage2_12_any_01"] = "GÜZEL, GÜZEL. BU, DEMOKRAT'I VURDUĞUMUZDA İŞİMİZİ KOLAYLAŞTIRACAK...",
["pln_framing_stage2_12_any_02"] = "DEMOKRAT'IN EVİNİ SOYMAYA GİTTİĞİMİZDE BU İŞİMİZİ KESİNLİKLE KOLAYLAŞTIRACAK.",
["pln_framing_stage2_13_any_01"] = "SWAT! FAZLA KOLAY OLDUĞUNU BİLİYORDUM!",
["pln_framing_stage2_13_any_02"] = "LANET OLSUN! SWAT PUSUSU. FARK ETMEDİM!",
["pln_framing_stage2_13_any_03"] = "PARAYI ALIP HEMEN ÇIKIN!",
["pln_framing_stage2_16_any_01"] = "KAPILAR, KAPILARI KAPATTILAR! BAŞKA BİR ÇIKIŞ OLMALI!",
["pln_framing_stage2_17_any_01"] = "O KAPIYI ANCAK BİR ECM KARIŞTIRICI AÇABİLİR... YOKSA ETRAFINDAN DOLAŞACAK BAŞKA BİR YOL BULMALISINIZ.",
["pln_framing_stage2_17_any_02"] = "LANET OLSUN, KİMSEDE ECM KARIŞTIRICI VAR MI? O KAPIYI AÇACAK NEREDEYSE TEK ŞEY BU. YOKSA BAŞKA BİR YOL GEREKİYOR.",
["pln_framing_stage2_18_any_01"] = "O TÜNELLER SİZİ DEPOYA GÖTÜRECEK.",
["pln_framing_stage2_18_any_02"] = "SANIRIM O TÜNELLER SİZİ DEPOYA ÇIKARIR MİLLET.",
["pln_framing_stage2_18_any_03"] = "İYİ HAMLE... KESİN DEPOYA ÇIKAR.",
["pln_framing_stage2_19_any_01"] = "SİZİ ZEKİ PİÇLER, O TÜNELLERİ KULLANIP ETRAFLARINDAN DOLAŞACAKSINIZ.",
["pln_framing_stage2_19_any_02"] = "TÜNELLERİ BÖYLE KULLANMANIZ ÇOK AKILLICA. ÇOK PROFESYONELCE.",
["pln_framing_stage2_19_any_03"] = "TÜNELLERİ KULLANMAK ÇOK İYİ HAMLEYDİ; ONLARI HAZIRLIKSIZ YAKALAYACAĞIZ.",
["pln_framing_stage2_20_any_01"] = "İŞÇİLERE GÖRÜNMEYİN, YOKSA BÜTÜN ANLAŞMAYI MAHVEDEBİLİRLER.",
["pln_framing_stage2_20_any_02"] = "TEDBİR İÇİN İŞÇİLERİN YANINDA DİKKAT ÇEKMEYİN.",
["pln_framing_stage2_20_any_03"] = "HÂLÂ POLİSLERİN GELMESİNİ İSTEMİYORSANIZ ŞU İŞÇİLERİN YANINDA DİKKATLİ OLSANIZ İYİ OLUR.",
["pln_framing_stage2_20_any_04"] = "HEY, İŞÇİ OLABİLİRLER AMA APTAL VE KÖR DEĞİLLER. GÖZE BATMAYIN.",
["pln_framing_stage2_brief_01"] = "TAMAM, KAMERALAR TABLOLARA YERLEŞTİRİLDİ. HAZIRIZ. SENATÖRÜN ADAMLARI GERGİN AMA BİZİMLE ANLAŞMAYA HAZIR. HADİ TAKAS YAPALIM. SANATA KARŞILIK PARA.",
["pln_framing_stage2_brief_01b"] = "BULUŞMA YERİNİ AYARLADIM. TERK EDİLMİŞ BİR DEMİRYOLU SAHASINDA BULUŞACAKSINIZ. BOL ŞANS.",
["pln_framing_stage2_brief_02"] = "TAMAM, DEMİRYOLU SAHASINDA YERİNİZİ ALDINIZ. GÖZÜNÜZ AÇIK OLSUN. TAKIM ELBİSELİLERİ KOLLAYIN. YAKINLARDA ÇALIŞAN ARAÇ GÖREMİYORUM AMA BU PEK BİR ŞEY İFADE ETMEZ. TRENİN VAGONUNA GİDİP BAĞLANTIYI BEKLEYİN.",
["pln_framing_stage2_brief_02b"] = "TABLOLARI ALDIĞIMIZDAN EMİN OLUN.",
["pln_framing_stage2_end_a_01"] = "SENATÖRÜN ADAMI AZ ÖNCE TABLOLARI ALDIKLARINI SÖYLEDİ. TAKASTAN ÇOK MEMNUNLAR. SİZİN İYİ İŞİNİZ SAYESİNDE ŞİMDİ TAM İSTEDİĞİMİZ YERDELER. UMARIM O PARADAN SİZ DE BİRAZ ALMIŞSINIZDIR.",
["pln_framing_stage2_end_a_01b"] = "ALTINIMIZI ALDIĞIMIZDAN EMİN OLALIM. BU BİZİM DE KAZANCIMIZ.",
["pln_framing_stage2_end_a_02"] = "PARAYI ALAMADINIZ AMA ÖNEMLİ KISIM TAMAM. ESERLER TESLİM EDİLDİ, SENATÖR TABLOLARINA HUZUR İÇİNDE BAKABİLİR... BİR SÜRELİĞİNE.",
["pln_framing_stage2_end_a_02b"] = "ŞİMDİ İŞİ BİTİRİP ONUN MEKÂNINI İNDİRME SIRASI BİZDE. GÜVENLİ EVDE GÖRÜŞÜRÜZ.",
["pln_framing_stage2_end_b_01"] = "SENATÖRÜN ADAMLARI ÇOK MİNNETTAR. PATRON DA TABLOLARI ASIYOR. HERİF ONU SİLİP SÜPÜRECEĞİMİZDEN HABERSİZ. NEYSE. BU ARADA PARAYI ALIRKEN İYİ İŞ ÇIKARDINIZ.",
["pln_framing_stage2_end_b_01b"] = "BUNU ÖDEME GÜNÜNE KADAR TUTACAĞIM. SENATÖRÜN DAİRESİNDEKİ ALTINLA BİRLİKTE GÜVENLİ EVİNİZİN KASA DAİRESİNİ GÜZEL DOLDURUR. HARİKA İŞ.",
["pln_framing_stage2_intro_a_01"] = "TAMAM, YER BURASI. TRENE GİDİP BAĞLANTINIZI BULUN. SİZİNLE ORADA BULUŞACAKLARINI SÖYLEDİLER. ŞİMDİLİK HER ŞEY İYİ GÖRÜNÜYOR. TABLOLARI TAKAS EDİP ÇABUCAK ÇIKIN. İŞİ AKSATMAYIN.",
["pln_framing_stage3_01_any_01"] = "PLAN ŞU: İÇERİ GİRİP SÖYLEYECEĞİM EŞYALARI BANA GETİRİN. HEPSİNİ ALINCA ÇATIDAKİ İSTASYONUMUZA BAĞLAYACAĞIZ.",
["pln_framing_stage3_02_any_01"] = "TELEFONU, TABLETİ, DİZÜSTÜ BİLGİSAYARI VE İKİ HARİCÎ SABİT DİSKİ LAZIM.",
["pln_framing_stage3_03_any_01"] = "TABLOLARDAKİ GİZLİ KAMERALARA ÇATIDAKİ DİZÜSTÜ BİLGİSAYARDAN ERİŞEBİLİRSİNİZ.",
["pln_framing_stage3_04_any_01"] = "UMARIM BİR SÜRÜ KAMERA ALMIŞSINIZDIR. BÜTÜN CİHAZLARI BULMAMIZI KOLAYLAŞTIRIR.",
["pln_framing_stage3_05_any_01"] = "HARİKA, DİZÜSTÜNÜ BULDUNUZ.",
["pln_framing_stage3_06_any_01"] = "BU ONUN TELEFONU. GÜZEL.",
["pln_framing_stage3_07_any_01"] = "TABLET BİLGİSAYAR BU. MÜKEMMEL.",
["pln_framing_stage3_08_any_01"] = "HARİCÎ SABİT DİSK BU. GÜZEL.",
["pln_framing_stage3_09_any_01"] = "HARİCÎ SABİT DİSKLERDEN BİRİ BU.",
["pln_framing_stage3_10_any_01"] = "İKİNCİ HARİCİ SABİT DİSK BU.",
["pln_framing_stage3_11_any_01"] = "BİR TANE DAHA, ARAMAYA DEVAM.",
["pln_framing_stage3_12_any_01"] = "İKİ TANE DAHA, ARAMAYA DEVAM EDİN.",
["pln_framing_stage3_13_any_01"] = "HEPSİ TAMAM.",
["pln_framing_stage3_14_any_01"] = "HARİKA! ŞİMDİ ONLARI ÇATIDAKİ İSTASYONA GÖTÜRÜP BAĞLAYIN.",
["pln_framing_stage3_15_any_01"] = "CİHAZLARI ÇATIDAKİ İSTASYONA BAĞLAYIN.",
["pln_framing_stage3_16_any_01"] = "TAMAM, ERİŞİM SAĞLADIM. BİR SANİYE BEKLEYİN...",
["pln_framing_stage3_17_any_01"] = "TAMAM! İŞİMİZ TAMAM. SANIRIM GEREKEN HER ŞEYİ ALDIM. ARTIK MASAÜSTÜ BİLGİSAYARINA ERİŞEBİLİRSİNİZ.",
["pln_framing_stage3_18_any_01"] = "OFİSİNDE BULUNUYOR.",
["pln_framing_stage3_19_any_01"] = "GÜZEL, TAMAM, ARTIK KASA DAİRESİ'Nİ AÇABİLİRSİNİZ. İÇERİDEKİ KAMERANIN GÖRÜNTÜSÜNÜ DE AÇTIM.",
["pln_framing_stage3_20_any_01"] = "KÜÇÜK BİR SORUN VAR YALNIZ... KASA DAİRESİNİN TAM OLARAK NEREDE OLDUĞUNU BİLMİYORUM.",
["pln_framing_stage3_21_any_01"] = "YANİ ONU SİZİN BULMANIZ GEREKİYOR. KAYNAKLARA GÖRE... BİR KİTAPLIKLA BAĞLANTILI. BİLİYORUM, KLİŞE İŞİ SİYASETÇİLERE BIRAKACAKSIN.",
["pln_framing_stage3_22_any_01"] = "KİTAPLIKLARI ARAYIN. YERLERİNİ OYNATIP BİR ŞEY BULABİLİYOR MUSUNUZ, BAKIN.",
["pln_framing_stage3_23_any_01"] = "İŞTE BÖYLE. ŞİMDİ ADAMA KUMPASI KURALIM. ÇATIYA ÇIKIN, ADAMIMIZ KOKAİNİ SİZE ATACAK.",
["pln_framing_stage3_24_any_01"] = "KOKAİNİ KASA DAİRESİNE İNDİRİN VE DIŞARIDAKİ ÖN ODAYA YERLEŞTİRİN.",
["pln_framing_stage3_25_any_01"] = "İŞTE BÖYLE, İYİ İŞ. KAÇIŞ SİZİ BEKLİYOR. KALIP KASA DAİRESİNİ BOŞALTMAK İSTEMİYORSANIZ TABİİ. HER DURUMDA ARAÇ BEKLİYOR.",
["pln_framing_stage3_26_any_01"] = "AFERİN, ÇIKTIK BURADAN.",
["pln_framing_stage3_27_any_01"] = "DAHA FAZLASINI ALMAK İSTİYORSANIZ MASAÜSTÜ BİLGİSAYARINI KULLANIN, KASA DAİRESİNİ AÇMASI LAZIM.",
["pln_framing_stage3_28_any_01"] = "TAMAM, KASA DAİRESİ AÇILDI AMA O LAZERLERE DİKKAT EDİN, DOĞRUDAN ALARMA BAĞLILAR.",
["pln_framing_stage3_29_any_01"] = "ONLARI KAPATMAMIZ GEREKİYOR.",
["pln_framing_stage3_30_any_01"] = "BİLGİSAYARINI TEKRAR KULLANIN. DİKKATLİ OLUN, SADECE KISA SÜRE KAPANIYORLAR.",
["pln_framing_stage3_31_any_01"] = "AÇILDIKLARINI KAMERADAN GÖRÜN, SONRA TEKRAR KAPATIN.",
["pln_framing_stage3_32_any_01"] = "LANET ALARM ÇALDI! B PLANINA GEÇME VAKTİ MİLLET.",
["pln_framing_stage3_33_any_01"] = "SUNUCU ODASINI BULUP İÇERİ GİRİN.",
["pln_framing_stage3_34_any_01"] = "İÇERİ GİRMEK İÇİN ANAHTAR KARTLARINI BULMAYA ÇALIŞIN, YOKSA KAPILARI MATKAPLA AÇMAMIZ GEREKECEK.",
["pln_framing_stage3_35_any_01"] = "HARİKA, SUNUCU ODASI BU. İÇERİDEKİ BİLGİSAYARI AÇIN, BÜTÜN DOSYALARI YÜKLEMELİYİZ.",
["pln_framing_stage3_36_any_01"] = "BİRAZ SÜRECEK, YÜKLENECEK VERİ ÇOK, BAĞLANTI DAR.",
["pln_framing_stage3_37_any_01"] = "UMARIM ŞİMDİ HİÇBİR ŞEY FARK ETMEZLER. ÇÜNKÜ O KADAR ŞANSLIYIZ YA.",
["pln_framing_stage3_39_any_01"] = "ELEKTRİĞİN KESİLMEDİĞİNDEN EMİN OLUN.",
["pln_framing_stage3_40_any_01"] = "ELEKTRİĞİ KESTİLER! GERİ GETİRİN!",
["pln_framing_stage3_41_any_01"] = "ELEKTRİĞİ YENİDEN AÇIN!",
["pln_framing_stage3_42_any_01"] = "ELEKTRİĞİ AÇMAK İÇİN BİR ŞALTER ARAYIN.",
["pln_framing_stage3_43_any_01"] = "TAMAM, BÜTÜN DOSYALAR YÜKLENDİ. İŞE YARAMALI.",
["pln_framing_stage3_44_any_01"] = "HELİKOPTERİMİZ GELİYOR, HABER HELİKOPTERLERİNİN ARASINA KARIŞACAK.",
["pln_framing_stage3_45_any_01"] = "KAÇMAK İÇİN HELİKOPTERE GİDİN!",
["pln_framing_stage3_46_any_01"] = "ELEKTRİĞİ KESMEYE ÇALIŞACAKLAR! İZİN VERMEYİN!",
["pln_framing_stage3_46_any_02"] = "BAŞARMAK İSTİYORSANIZ POLİSİ SİGORTA ŞALTERLERİNDEN UZAK TUTUN!",
["pln_framing_stage3_46_any_03"] = "ELEKTRİĞİ KESMELERİNE İZİN VEREMEZSİNİZ, HER ŞEYİ YAVAŞLATIR!",
["pln_framing_stage3_47_any_01"] = "NE YAPARSANIZ YAPIN, O OROSPU ÇOCUKLARININ ELEKTRİĞİ KESMESİNE İZİN VERMEYİN!",
["pln_framing_stage3_47_any_02"] = "ONLARI SİGORTA ŞALTERİNDEN UZAK TUTUN, DUYDUNUZ MU?",
["pln_framing_stage3_48_any_01"] = "SİZ YÜKLERKEN BEN BU GÖRÜNTÜYÜ BÜTÜN MEDYA KURULUŞLARINA CANLI GÖNDERECEĞİM. BAYILACAKLAR.",
["pln_framing_stage3_48_any_02"] = "TAMAM, İŞLERİ BİRAZ DAHA İLGİNÇ KILMAK İÇİN BİZ YÜKLERKEN BU GÖRÜNTÜYÜ BÜTÜN BÜYÜK MEDYA KURULUŞLARINA CANLI VERİYORUM. BOL BOL HABER OLACAĞIZ.",
["pln_framing_stage3_50_any_01"] = "YAKINDA HER YER HABER HELİKOPTERLERİYLE DOLACAK. BİZİM KAÇIŞ HELİKOPTERİ Mİ? ARALARINA KARIŞIP GİDECEK.",
["pln_framing_stage3_50_any_02"] = "BÜTÜN BASIN HELİKOPTERLERİYLE GELDİĞİNDE, KİMSE BİZİM KAÇIŞ HELİKOPTERİMİZE DÖNÜP BAKMAYACAK BİLE. ",
["pln_framing_stage3_50_any_03"] = "BAIN'İN UFAK BİR PLANI VAR. BENCE BÜTÜN O MEDYA HELİKOPTERLERİ KAÇIŞ HELİKOPTERİMİZ İÇİN UYGUN BİR PERDE, SİZCE DE ÖYLE DEĞİL Mİ?",
["pln_framing_stage3_51_any_01"] = "TAMAM, NEREDEYSE BİTTİ!",
["pln_framing_stage3_51_any_02"] = "İLERLİYOR!",
["pln_framing_stage3_51_any_03"] = "AZ KALDI! AZ KALDI, AZ KALDI...",
["pln_framing_stage3_51_any_04"] = "BU YÜKLEME YETERİNCE HIZLI GİTMİYOR, LANET OLSUN!",
["pln_framing_stage3_51_any_05"] = "YAKINDA BİTECEK, UMARIM.",
["pln_framing_stage3_51_any_06"] = "YÜKLENİYOR... NEREDEYSE TAMAM.",
["pln_framing_stage3_51_any_07"] = "TANRIM... ARABELLEĞE Mİ ALIYOR? HIZLANSANA! NEDEN GOOGLE FİBER KULLANMIYORLAR... LANET AMERİKAN İNTERNETİ.",
["pln_framing_stage3_52_any_01"] = "ALTINI ÇATIYA ÇIKARIP HALATTAKİ ÇANTAYA KOYUN. EVE GÖTÜRÜYORUZ!",
["pln_framing_stage3_52_any_02"] = "O ALTINI ÇATIYA ÇIKARIP ÇELİK HALATTAKİ ÇANTAYA KOYUN. GÖTÜRÜYORUZ. ",
["pln_framing_stage3_53_any_01"] = "HAZIR OLDUĞUNUZDA ÇATIYA ÇIKIN. SONRA ÇELİK HALATLA SİZİ ÇIKARACAĞIZ.",
["pln_framing_stage3_53_any_02"] = "HAZIR OLDUĞUNUZDA ÇATIYA ÇIKIN, SİZİ HALATLA ÇIKARACAĞIZ.",
["pln_framing_stage3_brief_01"] = "BURASI SENATÖRÜN DAİRESİ. GÜZEL MAHALLE AMA GÜVENLİĞİ YÜKSEK. TABLOLARI ÇOKTAN ASMIŞ, YANİ KAMERALARIMIZ AÇIK VE GÖRÜNTÜ İLETİYOR.",
["pln_framing_stage3_brief_01b"] = "GÖRÜNTÜYE BİNANIN ÇATISINDAN BAĞLANABİLİRSİNİZ. KUSURA BAKMAYIN, DAHA İYİSİNİ YAPAMADIK. GİZLİ KASA DAİRESİNE GİRİN, ALTINI ALIN, KUMPASI TAMAMLAMAK İÇİN BİRAZ KOKAİN BIRAKIN.",
["pln_framing_stage3_brief_01c"] = "AMA KASA DAİRESİNE YALNIZCA PAROLAYLA ERİŞEBİLİRİZ. BANA ELEKTRONİK CİHAZLARINDAN BİRKAÇINI BULUN, GERİSİNİ BEN HALLEDERİM. İYİ ŞANSLAR.",
["pln_framing_stage3_brief_02"] = "TAMAM. TARAMA EKİPMANLARI ÇATIDA HAZIR. GİZLİCE GİRİN; CEP TELEFONUNU, DİZÜSTÜ BİLGİSAYARINI, SABİT DİSKLERİNİ VE TABLETİNİ ALIN. TEKNOLOJİK NE VARSA. SONRA ÇATIYA GETİRİN.",
["pln_framing_stage3_brief_02b"] = "İYİCE ARAYIN, GÜVENLİKÇİLERE KARŞI GÖZÜNÜZ AÇIK OLSUN. ",
["pln_framing_stage3_end_a_01"] = "UYUŞTURUCU YERLEŞTİRİLDİ, SENATÖRE KUMPAS KURULDU. KÖTÜLER 1, SİYASETÇİLER 0. AFERİN, ÇOK PÜRÜZSÜZ BİR OPERASYONDU. THE ELEPHANT BU SONUCA BAYILACAK.",
["pln_framing_stage3_end_b_01"] = "ALTINI ALAMADIK AMA BAŞARILI KUMPAS İŞİNİN PARASINI YİNE DE ALACAĞIZ. AFERİN MİLLET.",
["pln_framing_stage3_end_c_01"] = "D.C.'DE BİR SKANDALA BASININ ÜŞÜŞECEĞİNE HER ZAMAN GÜVENEBİLİRSİNİZ. HERKES SİLAH ANLAŞMASINI KONUŞUYOR. THE ELEPHANT VE PARTİSİ ÇOK MEMNUN. MÜTHİŞ BİR B PLANIYDI MİLLET.",
["pln_framing_stage3_intro_01"] = "BURASI MUHAFIZ KAYNIYOR. ADAMA AİT, ÇİVİLİ OLMAYAN HER TEKNOLOJİK ŞEYİ ALMALISINIZ: CEP TELEFONLARI, DİZÜSTÜ BİLGİSAYARLAR, SABİT DİSKLER. İÇERİ SÜZÜLÜP KASA DAİRESİNİ BULUN.",
["pln_framing_stage3_intro_01b"] = "CİHAZLARLA ÇATIYA ÇIKIN, BAM, ALTIN DEĞERİNDEYİZ. GERÇEK ANLAMDA.",
["pln_fri_01_01"] = "LANET OLSUN, ŞU MEKÂNA BAKIN. ADAMIN TARZI VAR. SESSİZCE YA DA GÜMBÜR GÜMBÜR YAPABİLİRSİNİZ, SEÇİM SİZİN.",
["pln_fri_01_02"] = "NE EV AMA! SOSA'LARIN PARA KAZANDIĞI BELLİ. BURAYI VURALIM. SESSİZ YA DA GÜRÜLTÜLÜ; BUTCHER, HERİFİ ÖLDÜRDÜĞÜNÜZ SÜRECE NASIL YAPTIĞINIZI UMURSAMIYOR.",
["pln_fri_01_03"] = "TAMAM MİLLET. GİRELİM. SESSİZ YA DA GÜRÜLTÜLÜ, BU HERİFİ İSTEDİĞİNİZ GİBİ ÖLDÜREBİLİRSİNİZ.",
["pln_fri_02_01"] = "TAMAM, İLK ADIM GÜVENLİK ŞEFİNİ BULMAK. EVİN ERİŞİM KODLARININ OLDUĞU USB BELLEK ONDA. HEP YEŞİL CEKET GİYER.",
["pln_fri_02_02"] = "GÜVENLİK ŞEFİNİ BULALIM. GİRİŞ İÇİN GEREKEN ONDA OLMALI: GÜVENLİK KODLARINI İÇEREN USB BELLEK. YEŞİL CEKET GİYİYOR OLACAK.",
["pln_fri_02_03"] = "SOSA'NIN GÜVENLİK ŞEFİNİ BULUN. GÜVENLİK KODLARININ OLDUĞU USB BELLEK ONDA OLACAK. ALIŞKANLIKLARINA BAĞLI BİRİ, HEP YEŞİL CEKET GİYER.",
["pln_fri_03_01"] = "GÜVENLİK ŞEFİNDEKİ USB BELLEK LAZIM.",
["pln_fri_03_02"] = "USB BELLEĞİ ALMALIYIZ. GÜVENLİK ŞEFİNDE OLMALI.",
["pln_fri_03_03"] = "O USB BELLEK GÜVENLİK ŞEFİNDE OLACAK.",
["pln_fri_04_01"] = "UNUTMAYIN MİLLET, GÜVENLİK ŞEFİNİ ARIYORSUNUZ. USB BELLEĞİ LAZIM.",
["pln_fri_04_02"] = "GÜVENLİK ŞEFİNİ BULUP USB BELLEĞİNİ ALIN.",
["pln_fri_04_03"] = "GÜVENLİK ŞEFİNDEN USB BELLEĞİ ALIN.",
["pln_fri_05_01"] = "HARİKA, ŞİMDİ USB BELLEĞİ BİLGİSAYARA TAKIN. BİR DİZÜSTÜ BİLGİSAYAR ARAYIN; EVİN YAKININDA OLMALI.",
["pln_fri_05_02"] = "EVİN YAKININDA BİR YERDE DİZÜSTÜ BİLGİSAYAR OLMALI. USB BELLEĞİ ONA TAKIN.",
["pln_fri_05_03"] = "BİR DİZÜSTÜ BİLGİSAYAR BULUP USB'Yİ TAKIN. YAKINLARDA OLMALI.",
["pln_fri_06_01"] = "DİZÜSTÜNÜ BULAMIYOR MUSUNUZ? EVİN ETRAFINA BAKIN. BELKİ GARAJ?",
["pln_fri_06_02"] = "DİZÜSTÜ BİLGİSAYAR İÇİN ALET KULÜBESİNE BAKTINIZ MI?",
["pln_fri_06_03"] = "DİZÜSTÜ EVİN YAKININDA OLMALI. BELKİ KÜÇÜK BİNALARDAN BİRİNDEDİR?",
["pln_fri_07_01"] = "TAMAM, ŞİMDİ GÜVENLİK SİSTEMİNİ KIRMAYA ÇALIŞIYORUM...",
["pln_fri_07_02"] = "TAMAM, ŞİMDİ SİSTEME GİRİYORUM...",
["pln_fri_07_03"] = "GÜVENLİK SİSTEMİNE SIZMAYA ÇALIŞIRKEN BEKLEYİN...",
["pln_fri_08_01"] = "NE... MİLLET, BİLGİSAYARI KORUYUN!",
["pln_fri_08_02"] = "BİLGİSAYARDAKİ İŞLEMİ KESTİLER. ONU KORUMALISINIZ MİLLET!",
["pln_fri_08_03"] = "BİLGİSAYARIN İŞLEMİ KESİLDİ. DAHA İYİ SAVUNMANIZ GEREKİYOR!",
["pln_fri_09_01"] = "DURUN... NE... EK GÜVENLİK ENGELLERİ VAR. DEVRE DIŞI BIRAKMANIZ GEREK. BİR GÜVENLİK PANOSU BULUP SİSTEMİN KABLOLARINI YENİDEN BAĞLAYIN.",
["pln_fri_09_02"] = "BEKLEYİN... HIMM... BU SİSTEM DÜŞÜNDÜĞÜMDEN DAHA GELİŞMİŞ. BİR YERLERDE GÜVENLİK PANOSU OLMALI; BULUP KABLOLARINI YENİDEN BAĞLAMALISINIZ.",
["pln_fri_09_03"] = "BİR DAKİKA... AA... BURADA EK GÜVENLİK ENGELLERİ VAR. BİR GÜVENLİK PANOSU BULUP KABLOLARINI YENİDEN BAĞLAMALISINIZ.",
["pln_fri_10_01"] = "NE... BİR TANE DAHA MI? MİLLET, BAŞKA ŞALTER KUTUSU VAR. ONUN DA BAĞLANTILARINI DEĞİŞTİRİN.",
["pln_fri_10_02"] = "BİLMELİYDİM... BİR ŞALTER KUTUSU DAHA VAR. ONUN DA KABLOLARINI DEĞİŞTİRMELİSİNİZ.",
["pln_fri_10_03"] = "HMM... BİR ŞALTER KUTUSU DAHA VAR GALİBA. BULUP DİĞERİ GİBİ KABLOLARINI DEĞİŞTİRİN.",
["pln_fri_11_01"] = "HARİKA, BU YETERLİ OLMALI. ŞİMDİ BİLGİSAYARI YENİDEN BAŞLATMAYI DENEYİN.",
["pln_fri_11_02"] = "TAMAM, BU YETERLİ OLMALI. ŞİMDİ BİLGİSAYARI TEKRAR BAŞLATIN.",
["pln_fri_11_03"] = "TAMAM, ELEKTRİK PANOLARI DÜZELTİLDİ. BİLGİSAYARI YENİDEN BAŞLATABİLİRSİNİZ.",
["pln_fri_12_01"] = "TAMAM, BİLGİSAYAR YENİDEN DÜZGÜNCE ÇALIŞIYOR, SİSTEME SIZIYOR.",
["pln_fri_12_02"] = "GÜZEL. BİLGİSAYAR YENİDEN KESİNTİSİZ ÇALIŞIYOR.",
["pln_fri_12_03"] = "HER ŞEY YOLUNDA, İLERLİYORUZ. BİLGİSAYAR ÜZERİNDEN SİSTEME GİRİYORUM.",
["pln_fri_13_01"] = "BEKLENENDEN ZORDU AMA TAMAM! ARTIK EVE GİREBİLİRSİNİZ.",
["pln_fri_13_02"] = "TAMAM, BİTTİ! ZORDU AMA EVDEKİ BAZI KEPENKLERİ AÇMAYI BAŞARDIM.",
["pln_fri_13_03"] = "AÇIL SUSAM AÇIL! EVİN KEPENKLERİNDEN BAZILARINI AÇTIRDIM.",
["pln_fri_14_01"] = "İÇERİ GİRELİM MİLLET!",
["pln_fri_14_02"] = "KALEYİ YARDIK! İÇERİ GİRİN!",
["pln_fri_14_03"] = "HADİ MİLLET! HEMEN İÇERİ GİRİN!",
["pln_fri_15_01"] = "PATRONUN OFİSİNE GİRECEKSEK EVİN KALANINI AÇMALIYIZ. DÜĞME GİBİ BİR ŞEY ARAYIN.",
["pln_fri_15_02"] = "EVİN KALANINI AÇMAMIZ GEREK. BİR YERDE ŞALTER OLMALI.",
["pln_fri_15_03"] = "EVİN KALANINI AÇAN BİR ŞALTER FALAN OLMALI. BULMAYA ÇALIŞIN.",
["pln_fri_16_01"] = "TAMAM MİLLET, İŞE YARADI! EV AÇILDI!",
["pln_fri_16_02"] = "HARİKA! İÇERİDEYİZ!",
["pln_fri_16_03"] = "HARİKA MİLLET! KİMSE SİZİ DIŞARIDA TUTAMAZ!",
["pln_fri_17_01"] = "DURUN... LOBİYE YA DA SOSA'NIN OFİSİNE GİREMİYORUZ. AYRI BİR SİSTEMDE OLMALI.",
["pln_fri_17_02"] = "HEY MİLLET... EE... SOSA'NIN OFİSİNE BU ŞEKİLDE GİREMİYORUZ GALİBA. AYRI BİR SİSTEMDE.",
["pln_fri_17_03"] = "HMM... SOSA'NIN OFİSİ AYRI BİR GÜVENLİK SİSTEMİYLE KİLİTLİ GİBİ... BEKLEYİN...",
["pln_fri_18_01"] = "YENİ BİR PLAN LAZIM... BU ADAM İYİCE YUVASINA SİNMİŞ... HIMM...",
["pln_fri_18_02"] = "DÜŞÜNÜYORUM. NASIL GİRECEĞİMİZİ BİLMİYORUM...",
["pln_fri_18_03"] = "TAMAM, BAKALIM... HIMM... BUNUN İÇİN BİR PLAN LAZIM...",
["pln_fri_19_01"] = "GİRMEMİZ GEREK. MATKAP YETMEZ.",
["pln_fri_19_02"] = "HMM, PATLAYICILAR OLMAZ, ÇOK TEHLİKELİ... BİR BAKAYIM...",
["pln_fri_19_03"] = "NASIL... ŞEY... BİR ŞEY DÜŞÜNMELİYİM... NASIL GİRERİZ...",
["pln_fri_20_01"] = "ŞEY... TAMAM, EŞYALARI PARÇALA. ANLADIM.",
["pln_fri_20_02"] = "HMM... HAKLI MİLLET. EŞYALARINI BİRAZ DAĞITIP ONU KIŞKIRTABİLECEK MİYİZ GÖRELİM.",
["pln_fri_20_03"] = "TAMAM, EŞYALARI PARÇALAYIN. NEYE GİRİŞELİM...",
["pln_fri_21_01"] = "TAMAM, BURALARDA BİR SÜRÜ PAHALI SANAT ESERİ VAR. SERVET DEĞERİNDEDİR. BİR YERE YIĞIP YAKACAĞIZ, ONU DIŞARI ÇEKER.",
["pln_fri_21_02"] = "ERNESTO SOSA'NIN TABLO TOPLAMAYI SEVDİĞİ BELLİ. HEPSİNİ YAKACAĞIZ, BU ONU KIZDIRIR. BİR YERE YIĞIN.",
["pln_fri_21_03"] = "TABLOLARINI YAKALIM. ÖNCE BİR YERE YIĞIN.",
["pln_fri_22_01"] = "HARİKA, ORAYA YIĞIN.",
["pln_fri_22_02"] = "BURASI DA GAYET İYİ BİR YER. YIĞIN ONLARI.",
["pln_fri_22_03"] = "PAHA BİÇİLMEZ ESERLERİ YAKMAK İÇİN HARİKA BİR YER.",
["pln_fri_23_01"] = "YIĞMAYA DEVAM EDİN. GÜZEL BİR ATEŞ HAZIRLAYIN.",
["pln_fri_23_02"] = "BİRAZ DAHA TABLO EKLEYİN. BİRKAÇ TANE DAHA.",
["pln_fri_23_03"] = "HARİKA! BİRKAÇ TANE DAHA EKLEYİN, ADAM GİBİ ALEV İSTİYORUZ.",
["pln_fri_24_01"] = "YETER. ŞİMDİ ÜZERİNE BENZİN BİDONU KOYUP VURUN, TUTUŞSUN!",
["pln_fri_24_02"] = "TAMAM! ŞİMDİ BİR BENZİN BİDONU BULUP HER ŞEYİ TUTUŞTURMAK İÇİN VURUN. BİRAZ SANAT YAKALIM!",
["pln_fri_24_03"] = "TAMAM! ŞİMDİ GİDİP BENZİN BİDONU BULUN. TABLOLARI YAKMAK İÇİN ONA ATEŞ EDİN.",
["pln_fri_25_01"] = "MİLLET, TABLOLARIN ÜSTÜNE BİR BENZİN BİDONU KOYUP ATEŞ EDİN.",
["pln_fri_25_02"] = "UNUTMAYIN, TABLOLARI ATEŞE VERMEK İÇİN BENZİN BİDONU LAZIM. BİDONA ATEŞ EDİN.",
["pln_fri_25_03"] = "TABLOLARIN ÜSTÜNE BİR BENZİN BİDONU KOYUN, MİLLET. SONRA VURUN.",
["pln_fri_26_01"] = "TAMAM, BAKALIM BUNA NASIL TEPKİ VERECEK.",
["pln_fri_26_02"] = "HEPSİ YANIP KÜL OLUYOR. BU, DİKKATİNİ ÇEKER.",
["pln_fri_26_03"] = "ŞİMDİ TEPKİSİNİ BEKLEYİN YETER.",
["pln_fri_27_01"] = "HEY BILE, ORADA MISIN? ALINIP BIRAKILMASI GEREKEN BİRKAÇ ARABA VAR!",
["pln_fri_27_02"] = "BILE? UÇUP BURAYA GELMENİ VE BENİM İÇİN BİRKAÇ ARABAYI TAŞIMANI İSTİYORUM.",
["pln_fri_27_03"] = "BILE? SANA HAVADAN TAŞIMA İŞİ VAR. ALIP BIRAKMA İŞİ DİYEBİLİRİZ.",
["pln_fri_28_01"] = "SADECE GÜVENLİKÇİLER DEĞİL, TARETLER DE VAR! BU ADAM GÜVENLİĞİ CİDDİYE ALIYOR!",
["pln_fri_28_02"] = "TARETLERİ DE VAR! DİKKAT EDİN!",
["pln_fri_28_03"] = "O TARETLERE DİKKAT EDİN MİLLET!",
["pln_fri_29_01"] = "TAMAM, BURADAYKEN BİRAZ GANİMET ALALIM. ERNESTO'NUN OFİSİNDE ZEMİNE GÖMÜLÜ BİR KASA VAR. GİRDİĞİNİZ ARABA YOLUNUN YAKININDA ÇEKME VİNÇLERİ VAR; ALIN VE BAĞLAYIN.",
["pln_fri_29_02"] = "ADAMIN İŞİ İYİ. BURAYI YAĞMALAYALIM. ZEMİNDEKİ KASASINA YÖNELECEĞİZ. ARAZİNİN GİRİŞİNE YAKIN ÇEKME VİNÇLERİ SAKLI. ALIP BAĞLAYIN.",
["pln_fri_29_03"] = "TAMAM MİLLET, ŞİMDİ ERNESTO'NUN ZEMİN KASASINI SOYACAĞIZ. EMİNİM HARİKA ŞEYLERLE DOLUDUR. ARAZİYE GİRDİĞİNİZ YERİN YAKININDA SAKLI VİNÇLER VAR. GİDİP ALIN VE BAĞLAYIN.",
["pln_fri_30_01"] = "BURADAN GANİMETSİZ GİTMİYORUZ. ERNESTO'NUN EŞYALARINI TUTTUĞU BİR ZEMİN KASASI VAR. AZ ÖNCE ALDIĞINIZ ÇEKME VİNÇLERİNİ KULLANIN, ZEMİNE BAĞLAYIN.",
["pln_fri_30_02"] = "TAMAM, ERNESTO'NUN EVİNİ YAĞMALAMA VAKTİ. OFİSİNDE BİR ZEMİN KASASI VAR. O ÇEKME VİNÇLERİNİ ZEMİNE BAĞLAYIP KALDIRALIM.",
["pln_fri_30_03"] = "TAMAM, PARA VAKTİ, MİLLET. ERNESTO'NUN ZEMİN KASASINI YAĞMALAYACAĞIZ. O VİNÇLERİ ZEMİNE BAĞLAYIN.",
["pln_fri_31_01"] = "O ÇEKME VİNÇLERİNİ ŞİMDİ BAĞLAYIN!",
["pln_fri_31_02"] = "HADİ, ŞU ÇEKME VİNÇLERİNİ BAĞLAYIN!",
["pln_fri_31_03"] = "ÇEKME VİNÇLERİNİ ZEMİNE SABİTLEYİN!",
["pln_fri_32_01"] = "BU BİRAZ SÜRECEK. HÜNERLERİNİ GÖSTERİRKEN ÇEKME VİNÇLERİNİ KORUYUN.",
["pln_fri_32_02"] = "ŞİMDİ VİNÇLERİN ÇALIŞMASINI BEKLEYİN. MÜDAHALE EDİLMEDİĞİNDEN EMİN OLUN.",
["pln_fri_32_03"] = "TAMAM! ŞİMDİ ÇALIŞIRLARKEN VİNÇLERİ KORUYUN YETER.",
["pln_fri_33_01"] = "NE? VİNÇ DURMUŞ, YENİDEN ÇALIŞTIRIN!",
["pln_fri_33_02"] = "ÇEKME VİNCİ SIKIŞMIŞ GİBİ. TEKRAR ÇALIŞTIRIN!",
["pln_fri_33_03"] = "O ÇEKME VİNCİ DURDU. TAMİR EDEBİLİYOR MUSUNUZ BAKIN!",
["pln_fri_34_01"] = "BURADA VAKİT KAYBEDİYORUZ! O ÇEKME VİNCİNİ TEKRAR ÇALIŞTIRIN!",
["pln_fri_34_02"] = "O ÇEKME VİNCİNİ TEKRAR ÇALIŞTIRMAYI UNUTMAYIN!",
["pln_fri_34_03"] = "HADİ MİLLET! O VİNCİ YENİDEN ÇALIŞTIRMAYI UNUTMAYIN!",
["pln_fri_35_01"] = "TAMAM, ŞİMDİ ONLARI KORUYUN.",
["pln_fri_35_02"] = "HARİKA. ŞİMDİ ONLARI KORUYUN.",
["pln_fri_35_03"] = "HARİKA, TAMİR ETTİNİZ. ŞİMDİ ONLARI KORUYUN.",
["pln_fri_36_01"] = "BİTTİ. ŞU GANİMETE BAKIN! ŞİMDİ KAÇMADAN ÖNCE ALABİLDİĞİNİZ KADAR ALIN!",
["pln_fri_36_02"] = "HARİKA MİLLET! ŞUNA BAKIN! KAÇMADAN ÖNCE ALABİLDİĞİNİZ HER ŞEYİ ALIN.",
