["pln_fri_37_01"] = "GÜZEL MİKTARDA ZİYNET ALDINIZ. AMA DAHA KAPMAK İSTERSENİZ ALABİLİRSİNİZ.",
["pln_fri_37_02"] = "HARİKA. AMA BİRAZ DAHA ALMAK İSTERSENİZ ALIN!",
["pln_fri_37_03"] = "HARİKA MİLLET! ŞİMDİ DAHA FAZLA GANİMET ALABİLİR YA DA KAÇABİLİRSİNİZ. SEÇİM SİZİN.",
["pln_fri_38_01"] = "TAMAM, HER ŞEYİ SİLİP SÜPÜRDÜNÜZ! BURADAN GİTME VAKTİ.",
["pln_fri_38_02"] = "HEPSİ BU, SON KURUŞUNA KADAR! ŞİMDİ EVE GİTME VAKTİ!",
