["pln_fri_48b_01"] = "KAPATTINIZ! ALARM BU!",
["pln_fri_49_01"] = "HEY PATRON, BURADA SANA MÜHÜRLÜ BİR MEKTUP VAR. SADECE SENİN GÖRMEN İÇİNMİŞ.",
["pln_fri_49_02"] = "HEY PATRON, SANA BİR PAKET VAR. BOLİVYA'DAKİ MERKEZDEN.",
["pln_fri_49_03"] = "SANA GÖSTERECEK BİR ŞEYİM VAR PATRON. KENDİ GÖZLERİNLE GÖRMEK İSTEYECEKSİN.",
["pln_fri_49_04"] = "HEY PATRON, MEKSİKA'DAKİ ADAMLAR SANA TEKİLA GÖNDERDİ. İSTER MİSİN?",
["pln_fri_49_05"] = "HEY PATRON. BURADA BİR KADIN VAR, SANA ÖNEMLİ BİR BİLGİSİ OLDUĞUNU SÖYLÜYOR.",
["pln_fri_49_06"] = "YENİ SİLAHLAR GELDİ PATRON. GÖRMEK İSTER MİSİN?",
["pln_fri_49_07"] = "PATRON, BU KOKAİNDE BİR TUHAFLIK VAR. GÖRMELİSİN.",
["pln_fri_50_01"] = "KASAYI AÇAN BİR DÜĞME FALAN OLMALI. ETRAFA BAKIN.",
["pln_fri_50_02"] = "KASA MUHTEMELEN BİR YERDEKİ DÜĞME YA DA ŞALTERLE AÇILIYOR. ONU BULMANIZ GEREK.",
["pln_fri_50_03"] = "BİR YERDE KASAYI AÇAN BİR MEKANİZMA YA DA DÜĞME OLMALI. BULABİLİR MİSİNİZ, BAKIN.",
["pln_fri_51_01"] = "İYİ İŞ, GÜZEL VE SESSİZ. YAPABİLİRSENİZ HER ŞEYİ GÜVENE ALIN AMA BU İŞE DEĞMESİ İÇİN EN AZ BİRKAÇ ÇANTA LAZIM.",
["pln_fri_51_02"] = "GÜZEL. ALABİLDİĞİNİZ KADAR GANİMET ALIN AMA EN AZ BİRKAÇ ÇANTA OLSUN.",
["pln_fri_51_03"] = "HARİKA. ŞİMDİ MALLARI ALIN. ALABİLDİĞİNİZ KADAR, AMA EN AZ BİRKAÇ ÇANTA.",
["pln_fri_52_01"] = "ÇANTALARI TAŞIMAK İÇİN BİR ÇELİK HALAT KURABİLİRSİNİZ.",
["pln_fri_52_02"] = "ÇANTALARI DAHA HIZLI TAŞIMAK İSTERSENİZ ÇELİK HALAT KURABİLİRSİNİZ.",
["pln_fri_52_03"] = "İSTERSENİZ ÇELİK HALAT KURUN. ÇANTALARI TAŞIMAK İÇİN HARİKA OLUR.",
["pln_fri_53_01"] = "HADİ MİLLET, O ÇANTALARI TAŞIYIN!",
["pln_fri_53_02"] = "O ÇANTALARI DIŞARI ÇIKARIN MİLLET!",
["pln_fri_53_03"] = "ÇANTALARI ÇIKARMAYI UNUTMAYIN!",
["pln_fri_54_01"] = "HEY MİLLET, DAHA FAZLA SOSA SERSERİSİ MALİKANEYE GELİYOR! HER AN BURADA OLABİLİRLER. UMARIM ORTALIKTA CESET BIRAKMAMIŞSINIZDIR.",
["pln_fri_54_02"] = "GÜVENLİĞİ TAKVİYE ETMEK İÇİN MALİKANEYE BAŞKA BİR SOSA SERSERİ GRUBUNUN GELDİĞİ HABERİNİ ALDIM. ALAN TEMİZ OLSA İYİ OLUR, YOKSA GELİR GELMEZ SİZİ FARK EDERLER.",
["pln_fri_54_03"] = "SOSA'LAR GÜVENLİĞİ GÜÇLENDİRMEK İÇİN DAHA FAZLA ADAM YOLLUYORDU. GÖRÜNÜŞE GÖRE ŞİMDİ GELMEK ÜZERELER! ORTALIKTA AÇIKTA CESET BIRAKMAYIN, YOKSA BURADA OLDUĞUNUZU ANLARLAR.",
["pln_fri_55_01"] = "MİLLET, DİKKATLİ OLUN. İÇERİDEKİ MUHAFIZLAR MUHTEMELEN ÇAĞRI CİHAZI TAŞIYOR.",
["pln_fri_55_02"] = "İÇERİDEKİ MUHAFIZLARDA MUHTEMELEN ÇAĞRI CİHAZI VARDIR. DİKKATLİ OLUN.",
["pln_fri_55_03"] = "DİNLEYİN, EVDEKİ MUHAFIZLARDA MUHTEMELEN ÇAĞRI CİHAZI VAR. DİKKATLİ OLUN.",
["pln_fri_56_01"] = "MİLLET, İYİ DİNLEYİN. ARAMAYI BAŞLATTIĞINIZDA KAPATAMAZSINIZ. BÜYÜK İHTİMALLE ALARM VERİR, SONUÇTA PARANOYAK BİRİ.",
["pln_fri_56_02"] = "ERNESTO HEP PARANOYAKTIR. O YÜZDEN ARAMAYI BAŞLATINCA BİTİRSENİZ İYİ OLUR. ÇAĞRI CİHAZINA CEVAP VERİYORMUŞ GİBİ DAVRANIN.",
["pln_fri_56_03"] = "ARAMAYI YAPARKEN KAPATIRSANIZ ALARMI ÇALACAĞINI GARANTİ EDERİM. BAŞLAMADAN ÖNCE ORTALIĞIN TEMİZ OLDUĞUNDAN EMİN OLUN.",
["pln_fri_brf_01"] = "ERNESTO SOSA, SOSA CARTEL'İN MİAMİ'DEKİ YEREL PATRONU. THE BUTCHER ONUN ÖLMESİNİ İSTİYOR. BUNA BAYILACAKSINIZ: MİAMİ BEACH'TE TONY MONTANA'NIN ESKİ MALİKÂNESİNDE YAŞIYOR. EVET, BİLDİNİZ. SCARFACE, 80'LERİN EFSANEVİ UYUŞTURUCU BARONU. NEYSE, MALİKÂNEYİ BASIP İÇERİ GİRMENİN YOLUNU BULMALI VE ERNESTO SOSA'YI ÖLDÜRMELİSİNİZ. KOLAY OLMAYACAK, ORASI KALE GİBİ. AMA YAPABİLİRSİNİZ. HA EVET, AZ KALSIN UNUTUYORDUM. O EVDE BOL PARA VE BAŞKA GANİMETLER OLMALI. ÇALIN. ELLERİNDE AVUÇLARINDA NE VARSA ALIN. AMA HER ŞEYDEN ÖNEMLİSİ, ERNESTO SOSA'YI ÖLDÜRÜN.",
["pln_fri_intro_01"] = "TAMAM EKİP, YOLA KOYULALIM. THE BUTCHER BU İŞTE CİDDİ... UNUTMAYIN, ERNESTO SOSA'YI ÖLDÜRÜP GANİMETİ ÇALMANIZ GEREK.",
["pln_fri_intro_02"] = "HADİ MİLLET. THE BUTCHER BU HERİFİ ÖLÜ İSTİYOR AMA EVİN ZENGİNLİKLE DOLU OLDUĞUNU DA UNUTMAYIN.",
["pln_fri_intro_03"] = "MİAMİ BEACH'TE BU GÜZEL EVE SAHİP OLDUĞU İÇİN ERNESTO SOSA ŞANSLI DİYEBİLİRSİNİZ. AMA ŞANSI DEĞİŞMEK ÜZERE...",
["pln_fs1_01_any_01"] = "O ÇİTİ KESİP HANGARLARA İNİN. MENDOZA'LAR İÇERİDE.",
["pln_fs1_01_any_02"] = "MENDOZA'LAR AŞAĞIDA. ÇİTİ KESİP O SİLAHLARI ALIN.",
["pln_fs1_02_any_01"] = "BÜTÜN GECE VAKTİMİZ YOK ÇOCUKLAR, ACELE EDİN.",
["pln_fs1_02_any_02"] = "HADİ, BİRAZ HIZLANALIM.",
["pln_fs1_03_any_01"] = "DOĞRU HANGAR BURASI. SİLAHLARI ÇANTALAYIP MİNİBÜSE GERİ GÖTÜRMEYE HAZIRLANIN.",
["pln_fs1_04_any_01"] = "CESET SAYISINA BAKILIRSA PEŞİNDE OLDUĞUMUZ MALZEME BU.",
["pln_fs1_04_any_02"] = "TAM YERİNE GELMİŞİZ GALİBA. ARADIĞIMIZ SİLAHLAR BUNLAR.",
["pln_fs1_05_any_01"] = "O KONTROL KULESİNE GÖZ KULAK OLUN MİLLET, YUKARIDA HAREKET GÖRDÜM SANKİ.",
["pln_fs1_05_any_02"] = "KONTROL KULESİNDE HAREKET VAR, O PENCERELERİ GÖZLEYİN.",
["pln_fs1_06_any_01"] = "ELİNİZİ ÇABUK TUTSANIZ İYİ OLUR ÇOCUKLAR. NE KADAR OYALANIRSANIZ O KADAR ÇOK POLİS GELİR!",
["pln_fs1_06_any_02"] = "ÇABUK ÇABUK. FEDERALLER HER AN BURADA OLABİLİR.",
["pln_fs1_07_any_01"] = "İYİ BAŞLANGIÇ, ŞİMDİ KALANINI ALIN!",
["pln_fs1_08_any_01"] = "AZ KALDI. BİRKAÇ ÇANTA DAHA, YETERLİ OLMALI.",
["pln_fs1_09_any_01"] = "HECTOR İÇİN SONUNCU TAMAM, İYİ İŞ. DAHA FAZLASINI ALMAK YA DA ÇEKİLMEK SİZE KALMIŞ ÇOCUKLAR.",
["pln_fs1_09_any_02"] = "HECTOR İÇİN GEREKEN BU. KALANINI ALMAK İSTİYORSANIZ KARAR SİZİN!",
["pln_fs1_10_any_01"] = "BURADA BİR ŞEY KALMADI. MİNİBÜSE DÖNÜN.",
["pln_fs1_10_any_02"] = "TAMAM, O HANGARI TAMAMEN BOŞALTTINIZ. BURADAN ÇIKMA VAKTİ.",
["pln_fs1_11_any_01"] = "AFERİN MİLLET.",
["pln_fs1_11_any_02"] = "İYİ İŞ ÇOCUKLAR.",
["pln_fs1_12_any_01"] = "İYİ DÜŞÜNDÜNÜZ! SİLAHLARI YOK ETMEK İÇİN O ATEŞİ KULLANIN.",
["pln_fs1_12_any_02"] = "O SİLAHLAR GİTTİ! ATEŞ YANMAYA DEVAM ETSİN.",
["pln_fs1_13_any_01"] = "SİLAHLARI YOK ETMENİN YA DA MİNİBÜSE TAŞIMANIN BİR YOLUNU BULUN.",
["pln_fs1_13_any_02"] = "SİLAHLARI YOK EDİN YA DA MİNİBÜSE TAŞIYIN. MİNİBÜSE GÖTÜRMEK BİZE DAHA ÇOK PARA KAZANDIRIR.",
["pln_fs1_14_any_01"] = "BU MENDOZA'LARIN UÇAĞI, AZ ÖNCE KALKTI. SİLAHLAR ARTIK HANGARDA OLMALI.",
["pln_fs1_14_any_02"] = "ŞU UÇAK MENDOZA'NIN SİLAHLARINI İNDİRMİŞ OLMALI. ACELE EDİN MİLLET!",
