["pln_glc_12_01"] = "BU GENSEC'İN ZIRHLI PARA NAKİL ARAÇLARINDAN BİRİ Mİ? AÇARSANIZ BU İŞTEN FAZLADAN PARA ÇIKARABİLİRİZ.",
