["pln_glc_12_03"] = "ŞUNA BAKIN! GENSEC'İN ZIRHLI PARA NAKİL ARACI! BU İŞTEN EVE BİRAZ NAKİT GÖTÜRMEK İSTİYORSANIZ SOYABİLİRSİNİZ!",
