["pln_glc_brf_01"] = "PLAN BASİT: KARANLIKTAN YARARLANIP GREEN BRIDGE'DEN GEÇEN KONVOYU VURACAĞIZ. HATTA KÖPRÜYÜ PATLAYICILARLA HAVAYA UÇURACAĞIZ! BÜTÜN TRAFİĞİ DURDURUR, SİZCE DE ÖYLE DEĞİL Mİ? MAHKÛMU ALACAĞIZ, BİR FULTON HAVA KANCASINA BAĞLAYIP SIRRA KADEM BASTIRACAĞIZ.",
["pln_glc_cbf_01"] = "TAMAM, KENTO HAKKINDA BİLDİKLERİNİ ALABİLMEMİZ İÇİN ŞU KAZUO DENEN ADAMI HAPİSTEN ÇIKARMA VAKTİ. BAŞKA TESİSE KONVOYLA NAKLEDİLMESİ İÇİN BİRAZ, ŞEY... SORUN ÇIKARDIM. KONVOYA PUSU KURUP MAHKÛMU KURTARACAĞIZ. SESSİZ OLMAYACAK, MİLLET. MAHKÛM KAMYONLARINI DURDURMAK İÇİN AŞIRI ÖNLEMLER GEREKECEK. BİR DE EVET, KAZUO ONU KURTARACAĞIMIZI BİLMİYOR. BÜYÜK SÜRPRİZ YAŞAYACAK!",
["pln_glc_cnc_01"] = "LONG ISLAND PRİSON'DA KENTO'NUN NEREDE OLDUĞUNU BİLEBİLECEK BİR ADAM VAR. ONU ÇIKARALIM.",
["pln_glc_cnc_02"] = "BUGÜN GREEN BRIDGE'DE HAVAİ FİŞEK GÖSTERİSİ YAPACAĞIZ.",
["pln_glc_cnc_03"] = "GREEN BRIDGE'DE BİR MAHKÛM NAKİL ARACINI VURACAĞIZ MİLLET.",
["pln_glc_end_01"] = "HARİKA İŞ MİLLET! ÖDÜLÜ ALDINIZ!",
["pln_glc_end_02"] = "HARİKA İŞ MİLLET! ŞİMDİ BİRİNİN O KÖPRÜYÜ TAMİR ETMESİ GEREKECEK AMA BEN OLMAYACAĞIM...",
["pln_glc_end_03"] = "GERÇEK PROFESYONELLER GİBİ YAPTINIZ! ADAMINIZI ALDINIZ, O PATLAMANIN DA BÜTÜN ŞEHİRDEN DUYULDUĞUNA EMİNİM!",
["pln_glc_intro_01"] = "TAMAM, HERKES ÇÖKSÜN. PATLATIYORUM: DÖRT, ÜÇ, İKİ, SİPER...",
["pln_glc_intro_02"] = "ŞİMDİ KULAKLARINIZI KAPATIN...",
["pln_glc_intro_03"] = "HERKES HAZIR OLSUN... BAŞLIYORUZ... ATEŞLENİYOR...  ",
