["pln_hb1_26_05"] = "HOXTON BİRAZ SERSEMLEMİŞ GİBİ, MUHTEMELEN PATLAMADAN. AMA KENDİNE GELİR.",
["pln_hb1_brf_01_01"] = "THE DENTIST, HOXTON'IN YENİDEN YARGILANMASINI AYARLADI. ŞEY, SEN DEĞİL HOX, ESKİ... BAKIN, İSİMLERİ SONRA ÇÖZERİZ. DAVA KISA SÜRECEK. O SABIKAYLA SALINMAZ AMA MESELE BU DEĞİL. MESELE TAŞINACAK OLMASI, BİZ DE NAKİL SIRASINDA VURABİLİRİZ. DURUŞMADAN HEMEN SONRA ONU ALACAĞIZ. ABD ADALET SİSTEMİNE GÜZEL BİR ‘SİKTİR GİT’ MESAJI.$NL;$NL;PLAN OLABİLDİĞİNCE GÜRÜLTÜLÜ: ADLİYEDE BİR DUVARI PATLATIP HOX'U ALACAK VE ÇIKARACAĞIZ.$NL;$NL;ÇEVREDEKİ SOKAKLAR KAPATILDI. BELA BEKLİYORLAR. SİLAHLAR HAZIR OLSUN, BOL MÜHİMMAT GETİRİN.",
