["pln_hb2_07_03"] = "DELİL ODASINDA HOXTON'IN DAVASIYLA İLGİLİ DELİLLER BULABİLİRSİNİZ. ARAMAYA BAŞLAYIN.",
["pln_hb2_08_01"] = "HOXTON'IN DAVASIYLA İLGİLİ DELİL ARIYORSUNUZ. ETRAFA BAKIN. ODANIN HER YANINA KONMUŞ OLABİLİR. İŞARETLENMİŞ DE OLABİLİR.",
["pln_hb2_08_02"] = "KANITLAR BURADA BİR YERDE OLMALI. ARAYIN.",
["pln_hb2_08_03"] = "TANRIM, BUNLARI DÜZENLEMİYORLAR MI? ARAYIN. O DELİLİ BULUN. HOXTON'LA İLİŞKİLİ DELİL ARIYORSUNUZ.",
["pln_hb2_09_01"] = "HARİKA, DELİL BULDUNUZ! LABORATUVARDA ANALİZ EDİN. BAKALIM ÜZERİNDE HAİNİN DNA'SINDAN İZ VAR MI.",
["pln_hb2_09_02"] = "ŞİMDİ DELİLİ LABORATUVARA GÖTÜRÜN. HAİNE AİT DNA BULABİLİRSEK KİMLİĞİNİ KESİNLEŞTİREBİLİRİZ.",
