["pln_hb2_10_01"] = "TAMAM, HAİNİN KİMLİĞİ GİZLİ TUTULUYOR. AMA TAMAMEN BOŞA GİTMEDİ, DNA ÖRNEĞİNİ ALDIK! İYİ İŞ. ŞİMDİ HOXTON'A DÖNÜN.",
["pln_hb2_10_02"] = "KAHRETSİN, SİSTEMLERİ DNA'NIN KİME AİT OLDUĞUNU GÖSTERMEDİ. YİNE DE HAİNİN DNA ÖRNEĞİ BİZDE. İŞİMİZE YARAYACAĞINA EMİNİM. ŞİMDİ HOXTON'A DÖNÜN.",
["pln_hb2_10_03"] = "DNA'NIN KİME AİT OLDUĞUNU KESİNLEŞTİREMEDİK AMA NUMUNEYİ ALDIK, BUNUN YARDIMI OLUR. ŞİMDİ HOXTON'A DÖNÜN.",
