["pln_hb2_11_02"] = "LANET OLSUN. EŞLEŞME YOK. ARAMAYA DEVAM!",
["pln_hb2_11_03"] = "AH, LANET OLSUN... BOŞ ÇIKTI. ARAMAYA VE TARAMAYA DEVAM EDİN.",
["pln_hb2_12_01"] = "HOXTON'I SAVUNMAYA DEVAM EDİN! İŞLER ZORLAŞIYORSA GÜVENLİK ENGELLERİNİ AŞMAK İÇİN KARTLARI KULLANIN.",
["pln_hb2_12_02"] = "HOXTON'I SAVUNUN. KARTLARINIZ VARSA GİRİŞLERİ KAPATABİLİRSİNİZ.",
["pln_hb2_12_03"] = "KARTLARINIZ VARSA BARİYERLERİ KAPATABİLİRSİNİZ. BU ONLARI BİR SÜRE HOXTON'DAN UZAK TUTAR.",
["pln_hb2_13_01"] = "BURASI SIMSIKI KAPATILMIŞ AMA ANAHTAR KARTLARIYLA FARKLI ALANLARA ERİŞEBİLİRSİNİZ. AKILLICA SEÇİN; MUHTEMELEN ÇOK KART BULAMAYACAKSINIZ.",
["pln_hb2_13_02"] = "BURADA ANAHTAR KARTLARI ALTIN DEĞERİNDE. ALANLARI AÇMAK YA DA KAPATMAK İÇİN KULLANABİLİRSİNİZ. DİKKATLİ KULLANIN!",
["pln_hb2_13_03"] = "ANAHTAR KARTLARI ÇOK İŞİNİZE YARAYABİLİR. BULUN AMA DİKKATLİ KULLANIN.",
["pln_hb2_14_01"] = "CEPHANELİK! KİLİTLİ AMA BİR ANAHTAR KARTI'YLA İÇERİ GİREBİLİRSİNİZ. ORADA BOL BOL MÜHİMMAT OLMALI.",
