["pln_hb2_14_03"] = "ANAHTAR KARTI CEPHANELİĞE SOKAR. EMİNİM İÇERİDE BOL MÜHİMMAT VARDIR.",
["pln_hb2_15_01"] = "DOKTOR ÇANTALARINIZ AZALDIYSA REVİRİ AÇMAYI DÜŞÜNMELİSİNİZ.",
