["pln_hb2_15_03"] = "BİRAZ TOPARLANMANIZ GEREKİYORSA ANAHTAR KARTI HARCAYIP REVİRE ERİŞİN.",
["pln_hb2_16_01"] = "BAM! DERT EDECEK BİR KANAT DAHA AZALDI.",
["pln_hb2_16_02"] = "O YOLDAN İÇERİ GİREMEYECEKLER!",
