["pln_hb3_05_01"] = "İÇERİDESİNİZ. SIRADA MALİKÂNEYE GİRMEK VAR. AMA DİKKAT, BÜTÜN KAPILAR VE PENCERELER ALARMA BAĞLI.",
["pln_hb3_05_02"] = "TAMAM. ŞİMDİ MALİKÂNEYE. BOŞUNA GÜVENLİ EV DEMİYORLAR. BÜTÜN KAPI VE PENCERELERDE ALARM BEKLEYİN.",
["pln_hb3_05_03"] = "ŞİMDİ MALİKANEYE GİRMELİYİZ. KOLAY OLMAYACAK. KAPI VE PENCERELERDE ALARM OLDUĞUNU VARSAYIN. BUNA BİR ÇÖZÜM BULMALIYIZ.",
["pln_hb3_06_01"] = "KAPI YA DA PENCERE AÇILINCA ALARM SAYACI BAŞLAR. ÇALMADAN ÖNCE KAPATMAK İÇİN SINIRLI SÜRENİZ OLACAK.",
["pln_hb3_06_02"] = "KAPI YA DA PENCERE AÇINCA ALARMIN SAYACI BAŞLAYACAK. HER ŞEY BOKA SARMADAN KAPATMAK İÇİN SADECE BİRKAÇ SANİYENİZ OLACAK.",
["pln_hb3_06_03"] = "BİR KAPI YA DA PENCERE AÇAR AÇMAZ ALARM SAYACI BAŞLAYACAK. ALARMI DEVRE DIŞI BIRAKMANIZ İÇİN BİRKAÇ SANİYENİZ OLACAK.",
["pln_hb3_07_01"] = "PENCERELERDEN İÇERİ BAKIP ALARM KUTUSUNU BULMAYA ÇALIŞIN. İÇERİ GİRİNCE KAPATMAK İÇİN SINIRLI SÜRENİZ OLACAK, HAZIRLIKLI OLMAK EN İYİSİ.",
["pln_hb3_07_02"] = "PENCERELERDEN BAKIN. ALARM KUTUSUNU BULABİLİYOR MUSUNUZ? GİRİNCE ÇOK ÇABUK ÇALACAK, HAZIR OLUN.",
["pln_hb3_07_03"] = "GİRMEDEN ÖNCE İÇERİ BAKIN. ALARM KUTUSUNU BULUN. KAPI YA DA PENCERE AÇINCA BAŞLAYACAK, HEMEN KAPATMALISINIZ.",
