["pln_hb3_42_01"] = "MİLLET, DURUN... O... HECTOR MI!? NE... OLUYOR LAN? NEDEN... ANLAMIYORUM. DURUN... WATCHDOGS İŞİ, POLİS BU YÜZDEN BİZİ BEKLİYORMUŞ. PUSUYMUŞ. O OROSPU ÇOCUĞU.",
["pln_hb3_42_02"] = "HECTOR MI!? NE OLUYOR LAN!? FİRESTARTER İŞİNDE HEP BİR TUHAFLIK VAR DEMİŞTİM. MENDOZA'LAR BELKİ DE KÖTÜ TARAF DEĞİLDİ. YANİ EVET, ONLAR DA ÇÜRÜKTÜ AMA BU LANET MUHBİR ÇOK DAHA BETERDİ.",
["pln_hb3_42_03"] = "SIÇAN HECTOR MIYMIŞ!? DÜNYADA ÇOK APTAL SUÇLU OLDUĞUNU SÖYLERDİ. BİZİ KAZIKLAYABİLECEĞİNİ SANDIĞINA GÖRE ONLARDAN BİRİ DE KENDİSİYMİŞ.",
["pln_hb3_42_04"] = "FEDERALLERLE ÇALIŞAN HECTOR MIYMUŞ!? O OROSPU ÇOCUĞU BİZİ ENAYİ YERİNE KOYABİLECEĞİNİ SANDI. SONUNDA EZİLEN O OLDU, PİS KOLOMBİYALI SIÇAN.",
["pln_hb3_42_05"] = "KÖSTEBEK HECTOR MIYMUŞ!? BİZİ ORTADAN KALDIRABİLECEĞİNİ SANAN AŞAĞILIK HERİF. YENİDEN GÜÇ KAZANMASINA YARDIM ETTİK, O DA BİZİ KAZIKLAMAYA KALKTI. PİS SIÇAN.",
["pln_hb3_42_06"] = "MUHBİR HECTOR! FBI, MENDOZA'LARIN GİZLİ BANKASI HAKKINDA HER ŞEYİ BU YÜZDEN BİLİYORDU. BU LANET YOBAZ ONLARA BİLGİ VERİYORMUŞ!",
["pln_hb3_42_07"] = "HAİN HECTOR'MIŞ! RATS İŞİNDE BİZE TUZAK KURMAYA ÇALIŞTI. POLİS METAMFETAMİN LABORATUVARINI O YÜZDEN O KADAR ÇABUK BULMUŞ. BAŞTAN BERİ O SİKİK SIÇANMIŞ.",
["pln_hb3_43_01"] = "TAMAM, İŞE ODAKLANIN. EVİN HER YANINA DAĞILMIŞ DELİLLER VAR. ONLARI HALLETMELİYİZ. FBI'IN İZİMİZİ KAYBETTİĞİNDEN EMİN OLMALIYIZ!",
["pln_hb3_43_02"] = "TAMAM, AKLINIZI İŞE VERİN. EVDE HÂLÂ BAŞIMIZA BELA OLABİLECEK BİR SÜRÜ DELİL VAR. HALLEDİN.",
["pln_hb3_43_03"] = "KEMİKLERİNE SONRA İŞERİZ. ŞU AN EVİN HER YANINA DAĞILMIŞ DELİLLERİ HALLETMELİYİZ.",
["pln_hb3_44_01"] = "MİLLET, PANİK ODASINI SESSİZCE AÇMAK İÇİN ŞEF CANLI LAZIMDI! TAMAM. ARTIK GÜRÜLTÜLÜ YOLDAN YAPMAMIZ GEREKECEK.",
["pln_hb3_44_02"] = "O ŞEF CANLIYKEN İŞE YARARDI. AMA HEP BİR YEDEK VARDIR. *GÜRÜLTÜLÜ* BİR YEDEK.",
["pln_hb3_44_03"] = "O ADAMI KULLANABİLİRDİK. NEYSE. YEDEK PLANA GEÇİN.",
["pln_hb3_45_01"] = "KAHRETSİN, RETİNA TARAYICISI YÜZÜNDEN PATRON BİZE CANLI LAZIMDI. ŞİMDİ GÜRÜLTÜLÜ YAPMAK ZORUNDAYIZ.",
["pln_hb3_45_02"] = "O ADAM BİZİ RETİNA TARAYICISINDAN GEÇİREBİLİRDİ AMA ARTIK GEÇİREMEZ. NEYSE. YEDEK PLANIN VAKTİ.",
["pln_hb3_45_03"] = "O ADAMI RETİNA TARAYICISINDA KULLANABİLİRDİK. NEYSE. B PLANININ VAKTİ GELDİ.",
["pln_hb3_46_01"] = "TAMAM, BURASI FAZLA KIZIŞIYOR. MİNİBÜS GİDİYOR. SİZE HELİKOPTER AYARLAYACAĞIM. SAKİN OLUN.",
["pln_hb3_46_02"] = "MİNİBÜS ŞOFÖRÜ KAÇTI. BOŞ VERİN ONU. TAMAM, SİZE HELİKOPTER BULUYORUM. HAYATTA KALIN.",
["pln_hb3_46_03"] = "MİNİBÜS ŞOFÖRÜ İÇİN ORTALIK FAZLA KIZIŞTI, SIVIŞIYOR. MERAK ETMEYİN, SİZİN İÇİN YAKITI DOLU BİR HELİKOPTER HAZIR.",
["pln_hb3_47_01"] = "TAMAM, BURADAN DEFOLMA VAKTİ. GİDİN!",
["pln_hb3_47_02"] = "GİTME VAKTİ, EKİP! ACELE EDİN!",
["pln_hb3_47_03"] = "İŞİNİZ BİTTİ, AYRILMA VAKTİ GELDİ. HADİ KIMILDAYIN!",
["pln_hb3_48_01"] = "HELİKOPTER GELDİ!",
["pln_hb3_48_02"] = "ARACINIZ BURADA.",
["pln_hb3_48_03"] = "KAÇIŞ ARACINIZ ORADA.",
["pln_hb3_49_01"] = "SİKTİR, YAKINDAKİ EVLERDE HAZIR BEKLEYEN FBI EKİPLERİ VAR. YOLA ÇIKTILAR.",
["pln_hb3_49_02"] = "SIÇTIK, FBI'IN GÜVENLİ EVİN YANINDAKİ EVLERDE HAZIR EKİPLERİ VAR. SİZE GELİYORLAR!",
["pln_hb3_49_03"] = "HAZIR FBI EKİPLERİ YOLDA! O PİÇLER YAKINDAKİ EVLERDE BEKLİYORMUŞ!",
["pln_hb3_50_01"] = "MİLLET, MÜMKÜNSE EVİN İÇİNDE KALSANIZ İYİ OLUR. FBI KESKİN NİŞANCILARI ÇOK TEHLİKELİ ATIŞ HATLARI KURUYOR.",
["pln_hb3_50_02"] = "EKİP, KENDİNİZİ KUŞATILMIŞ SAYIN. ETRAFINIZI SARDILAR, KESKİN NİŞANCILAR KURUYORLAR. YERİNİZDE OLSAM İÇERİDE KALIRDIM!",
["pln_hb3_50_03"] = "LANET OLSUN, KESKİN NİŞANCILAR ÇEVREYE YERLEŞİYOR. DİKKAT EDİN, SADECE GEREKİRSE DIŞARI ÇIKIN!",
["pln_hb3_51_01"] = "GÜVENLİ ODANIN DIŞ KAPISINI HALLETTİĞİNİZ İÇİN TERMAL KARGI DAHA KISA SÜREDE İŞİNİ BİTİRİR. EN AZINDAN BU VAR!",
["pln_hb3_51_02"] = "PANİK ODASININ DIŞ KAPISINI AÇMAYI BAŞARDINIZ. TERMAL MIZRAĞIN İŞİ O KADAR UZUN SÜRMEZ!",
["pln_hb3_51_03"] = "YİNE DE PANİK ODASINI KISMEN AÇTINIZ. DEMEK Kİ TERMAL MIZRAĞIN İŞİ DAHA KISA SÜRECEK!",
["pln_hb3_52_01"] = "FBI MÜDÜRÜNE YAKINSINIZ. PARMAĞINIZI TETİKTEN ÇEKİN, CANLI LAZIM OLABİLİR.",
["pln_hb3_52_02"] = "HIMM, DELİL PANOSUNUN ORADAKİ FBI ŞEFİ OLMALI. HAYATTA TUTUN, İŞE YARAYABİLİR.",
["pln_hb3_52_03"] = "FBI ŞEFİ KONUMUNUZA YAKIN GÖRÜNÜYOR. ÖLDÜRMEYİN, İŞİMİZE YARAYABİLİR.",
["pln_hb3_53_01"] = "ÇIKARDIĞINIZ BÜTÜN DELİLLER İÇİN ŞAHSEN ÖDÜL VERECEĞİM. CRIME.NET'İN GÜVENLİĞİ SÖZ KONUSU.",
["pln_hb3_53_02"] = "GÜVENLİ EVDEN ÇIKARDIĞINIZ HER DELİL İÇİN BULMA ÜCRETİ VAR. CRIME.NET'İ VE BAĞLANTILARINI KORUMALIYIM.",
["pln_hb3_53_03"] = "GÜVENE ALDIĞINIZ HER DELİL ÇANTASI İÇİN ÖDEME YAPACAĞIM. CRIME.NET KORUNMALI.",
["pln_hb3_54_01"] = "İÇERİDE GÖZETİM DRONLARI VE CASUS KAMERALAR YERLEŞTİREN BİR ADAMIM VAR. KAMERA ERİŞİMİ ÇATIDA.",
["pln_hb3_54_02"] = "İÇERİDEKİ BAĞLANTIMIZ GİZLİ KAMERALAR VE GÖZETLEME DRONLARI KURDU. ÇATIDAKİ CİHAZDAN ERİŞEBİLİRSİNİZ.",
["pln_hb3_54_03"] = "FBI'DAKİ BİR BAĞLANTIM MEKÂNA CASUS KAMERALAR DÖŞEDİ, DIŞARIYA DA GÖZETİM DRONLARI YERLEŞTİRDİ. ÇATIDAKİ CİHAZLA ONLARI KONTROL EDEBİLİRSİNİZ.",
["pln_hb3_55_01"] = "LANET! ZAMAN KİLİDİ TAKILDI. ECM KARIŞTIRICILARINIZ ETKİ EDİYOR OLMALI! DEVAM ETMESİNİ BEKLEYİN.",
["pln_hb3_55_02"] = "SİKTİR, ZAMAN KİLİDİ DURAKLADI. ONU ÇILDIRTAN ECM KARIŞTIRICINIZ OLMALI! O KARIŞTIRICILARI KALDIRSANIZ İYİ OLUR.",
["pln_hb3_55_03"] = "NE?! ZAMAN KİLİDİ DURDU. HMM, ECM KARIŞTIRICINIZ ONU BOZUYOR OLABİLİR. O KARIŞTIRICILARI BİR SÜRE KULLANMASANIZ İYİ OLUR.",
["pln_hb3_56_01"] = "SIÇTIK, FBI ŞEFİ OLAY YERİNDEN KAÇTI. RETİNA TARAYICISINI YAKIN ZAMANDA KULLANAMAYACAĞIZ. B PLANINA GEÇME VAKTİ.",
["pln_hb3_56_02"] = "NE?!! FBI ŞEFİNİ ELİNİZDEN Mİ KAÇIRDINIZ? OLAY YERİNDEN GİTMİŞ! GERİ DE GELMEYECEK. B PLANINA GEÇMEK GEREK.",
["pln_hb3_56_03"] = "MİLLET, FBI MÜDÜRÜ OLAY YERİNDEN KAÇTI. RETİNA TARAYICISINI GEÇMEK İÇİN YARDIMI GEREKİYORDU. KAHRETSİN. B PLANININ VAKTİ GELDİ.",
["pln_hb3_57_01"] = "LANET OLSUN! ALARMIN SÜRESİ DOLDU. ROKET BİLİMİ DEĞİL, MİLLET!",
["pln_hb3_57_02"] = "MİLLET! ALARM KUTUSUNU HALLETMEDİNİZ.",
["pln_hb3_57_03"] = "AZ ÖNCE BAHSETTİĞİM ALARMI UNUTTUNUZ MU?! DEVRE DIŞI BIRAKMANIZ GEREKİYORDU!",
["pln_hb3_58_01"] = "MİLLET, ALARM GERİ SAYIYOR. ONU HALLETMENİZ ŞART!",
["pln_hb3_58_02"] = "ALARM ETKİNLEŞTİ, GERİ SAYIYOR. 0'A VARMADAN HALLEDİN!",
["pln_hb3_58_03"] = "ALARMI KAPATIN! GERİ SAYIYOR, 0'A ULAŞINCA İŞLER FENA KARIŞACAK.",
["pln_hb3_59_01"] = "BENCE BU KADAR DELİL ALEYHİMİZDEKİ DAVAYI BİTİRİR AMA DAHA FAZLASINI ALMANIZA İTİRAZ ETMEM.",
["pln_hb3_59_02"] = "TAMAM, KIÇIMIZI KURTARMAYA YETECEK KADAR KANIT ÇALDIK HERHÂLDE AMA DAHA FAZLASINI HER ZAMAN ALABİLİRSİNİZ!",
["pln_hb3_59_03"] = "ÇALDIĞIMIZ ONCA DELİLDEN SONRA ALEYHİMİZDEKİ DAVAYI TOPARLAMALARI ZOR AMA DAHA FAZLASINI ÇALMAKTA SERBESTSİNİZ.",
["pln_hb3_brf_01_01"] = "PEKÂLÂ. SONUNDA SIÇANIN PEŞİNE DÜŞÜYORUZ. HOX'U YAKAN MUHBİR HEPİMİZİ YAKMAK İSTİYOR. ONU İNDİRME VAKTİ. ŞU AN ŞEHİR DIŞINDAKİ BİR FBI GÜVENLİ EVİNE SIĞINDIĞINI BİLİYORUZ. BU EVLER GENELDE AYNI DÜZENDE YAPILIR. GÜZEL BÜYÜK EVLER, BAHÇE, 24 SAAT GÜVENLİK VE BÜYÜK İHTİMALLE İÇERİDE BİR PANİK ODASI. VERGİLERİNİZ NEREYE GİDİYOR, GÖRDÜNÜZ MÜ? PLAN BASİT: GİRİN, MUHBİRİMİZİ BULUN VE BİTİRİN. BAHSE GİRERİM BİZE KARŞI KANIT DA VARDIR, ONLARI DA TEMİZLEMEK İYİ OLUR.",
["pln_hd1_01_01"] = "PEKÂLÂ. İLK HEDEF İÇERİ GİRMEK. ÖN KAPI TAM İLERİDE AMA BELKİ BİRAZ KURNAZLIK EDİP BAŞKA GİRİŞLER ARARSINIZ.",
["pln_hd1_01_02"] = "İLK İŞ İÇERİ GİRMEK. ANA KAPI TAM ORADA. AMA BAŞKA YOLLAR DA OLABİLİR.",
["pln_hd1_01_03"] = "İLK İŞ İÇERİ GİRMEK. ÖN KAPI EN BARİZ YOL AMA BELKİ DAHA AZ DİKKAT ÇEKEN BİR ŞEY BULABİLİRSİNİZ.",
["pln_hd1_02_01"] = "TAMAM. SESSİZCE YAPACAKSAK ALARM SİSTEMLERİNİN BAZILARINI KAPATMALIYIZ. ETRAFA BAKIN. MÜZEYİ ARAYIN. GÜVENLİĞE ELEKTRİK VEREN SİGORTA KUTULARINI BULUN. SİSTEMLERİNİ KIRABİLİRSEK ALARMLARI TETİKLEMEDEN BURAYI KAPATABİLİRİZ.",
["pln_hd1_02_02"] = "TAMAM, GÜVENLİĞİ KAPATMAYI DENEYELİM. SİSTEME GÜÇ VEREN DEVRE KUTULARINI BULMALISINIZ. ONLARA BAĞLANIN. ALARMI TETİKLEMEDEN SİSTEMLERİNİ KIRIP GÜCÜ KESEBİLİRİM.",
["pln_hd1_02_03"] = "GÜVENLİĞİ KAPATABİLİR MİYİZ BAKALIM. ZAYIF NOKTALARI ETRAFA DAĞILMIŞ DEVRE KUTULARI. SİSTEMLERİNİ KIRARSAK ALARMI TETİKLEMEDEN ELEKTRİĞİ KESEBİLİRİZ.",
["pln_hd1_03_01"] = "ALARM SİSTEMLERİ DEVRE DIŞI. GİRİN İÇERİ!",
["pln_hd1_03_02"] = "LAZERLER KAPANDI! İLERLEYİN, SIRADA NE VAR BAKALIM.",
["pln_hd1_03_03"] = "SON KUTU BU. ELEKTRİĞİ KESİYORUM. TAMAM! LAZERLER KAPANDI! İLERLEYİN!",
["pln_hd1_04_01"] = "SONRAKİ ADIM... İKİ ZAMAN KİLİDİ. HER BİRİNİ GEÇMEK İÇİN ANAHTAR KARTI GEREKİYOR. MUHAFIZLARDA OLMAZ AMA SİVİL ARAŞTIRMACILARDA MUHTEMELEN VARDIR. BULUP, BİLİRSİNİZ, İKNA EDİN. ANAHTAR KARTLARINI ÇOK GEÇMEDEN VERİRLER.",
["pln_hd1_04_02"] = "HMM, BİRKAÇ ZAMAN KİLİDİ. TAMAM, GEÇMEK İÇİN ANAHTAR KARTLARI GEREKECEK. BU KİRALIK GÜVENLİKLERDE OLMAZ AMA SİVİL ARAŞTIRMACILARDA OLDUĞUNA EMİNİM. KARTLARI VERMELERİNİ SAĞLAYIN.",
["pln_hd1_04_03"] = "İKİ ZAMAN KİLİDİ... HIMM. TAMAM, AŞMAK İÇİN ANAHTAR KARTLARI LAZIM. BURADAKİ GÜVENLİĞİN SEVİYESİ BUNLARI TAŞIMAK İÇİN ÇOK DÜŞÜK, O YÜZDEN SİVİL ARAŞTIRMACILARA ODAKLANIN. BİRKAÇINDA ANAHTAR KARTI OLDUĞUNA OLDUKÇA EMİNİM.",
["pln_hd1_05_01"] = "LANET! ZAMAN KİLİTLERİ TAMAMEN KİLİTLENDİ. ANAHTAR KARTLARI ARTIK BİR BOKA YARAMAZ. GÜVENLİK PANELLERİNE KABA KUVVET UYGULAMA VAKTİ!",
["pln_hd1_05_02"] = "AH SİKTİR! ZAMAN KİLİDİ DEVREDE. ANAHTAR KARTLARINI UNUTUN. O PANELLERİ ZORLAYIN.",
["pln_hd1_05_03"] = "LANET! ZAMAN KİLİTLERİ DEVREYE GİRDİ. TAMAM. ANAHTAR KARTLARINI UNUTUN. ZORLA GİRECEĞİZ.",
["pln_hd1_06_01"] = "TAMAM, ZAMAN KİLİTLERİ TARİH OLDU. ŞİMDİ AŞAĞI İNİP O SON KAPIYI AÇIN!",
["pln_hd1_06_02"] = "ZAMAN KİLİTLERİ TAMAM. SON KAPIYI GEÇİN YETER!",
["pln_hd1_06_03"] = "ZAMAN KİLİTLERİ TAMAM. AZ KALDI MİLLET! SON KAPIYI AÇIN!",
["pln_hd1_07_01"] = "TAMAM, DEVRE KUTUSUNDAKİ IŞIKLAR KAROLARA KARŞILIK GELİYOR. GEÇERKEN ONLARI REHBER ALIN. KİMSE YANLIŞ KAROYA BASAMAZ, YOKSA İŞ ÇOK DAHA FAZLA KARIŞIR!",
["pln_hd1_07_02"] = "ŞİMDİ ŞU IŞIKLARI GÖRÜYOR MUSUNUZ? KARŞIYA GEÇECEĞİNİZ YOL BU. YOLDAN AYRILMAYIN! YANLIŞ KAROYA BASARSANIZ İŞLER ÇABUCAK KARIŞIR.",
["pln_hd1_07_03"] = "IŞIKLAR ODADA İZLEYECEĞİNİZ YOLU GÖSTERİYOR. GÖRÜYOR MUSUNUZ? HER IŞIK BİR KAROYA KARŞILIK GELİYOR. DOĞRU KAROLARDAN AYRILMAYIN!",
["pln_hd1_08_01"] = "BAŞARDINIZ! TAM ORADA! ELMASI ALIN!",
["pln_hd1_08_02"] = "GEÇTİNİZ. ŞUNA BAKIN. ÇOK GÜZEL. ŞİMDİ ALIN.",
["pln_hd1_08_03"] = "KARŞIYA GEÇTİNİZ! ŞİMDİ O TAŞI ALIN!",
["pln_hd1_09_01"] = "O TAŞIN NE KADAR ETTİĞİNİ BİLİYOR MUSUNUZ?",
["pln_hd1_09_02"] = "ALDINIZ. THE DIAMOND'I. O LANET DİAMOND'I.",
["pln_hd1_09_03"] = "DİAMOND'I GERÇEKTEN ALDIĞIMIZA İNANAMIYORUM.",
["pln_hd1_10_01"] = "SIÇTIK, ALARM! GÜVENLİK ODASINI BULMANIZ GEREK. BURASI KİLİTLİYKEN HİÇBİR ŞEY YAPAMAYIZ!",
["pln_hd1_10_02"] = "TAMAM, POLİS YOLDA. BU VURGUN PİNK PANTHER'DAN ÇOK RESERVOIR DOGS'A DÖNDÜ. GÜVENLİK ODASINA GİDİN.",
["pln_hd1_10_03"] = "LANET! POLİSLER ELLERİNDEKİ HERKESİ GÖNDERİYOR. BUNU KANLI ELMASA ÇEVİRME VAKTİ. GÜVENLİĞİ BULUN!",
["pln_hd1_11_01"] = "NE... THE DIAMOND'I ZEMİNE İNDİRDİLER. TAMAM, GEÇMENİN YOLUNU AÇMALIYIZ! ORAYA BİR MATKAP KURUN.",
["pln_hd1_11_02"] = "HEY, DİAMOND NEREDE? ZEMİNİN İÇİNE İNDİRMİŞLER! BUNU BEKLEMİYORDUM. KABA KUVVET GEREKİYOR; MATKAPLA DELİN!",
["pln_hd1_11_03"] = "KAHRETSİN! DİAMOND'I ZEMİNİN İÇİNE İNDİRDİLER! İNCE İŞLERE VAKİT YOK. TEK ÇARE VAR, ORAYA MATKAP KURUN! ",
["pln_hd1_12_01"] = "İÇERİDESİNİZ AMA ALARM GERİ SAYIYOR. İŞİMİZE DÖNEBİLMEMİZ İÇİN GÜVENLİK KİLİDİNİ DEVRE DIŞI BIRAKIN!",
["pln_hd1_12_02"] = "İÇERİDESİNİZ AMA ALARM TETİKLENDİ. ÇALMADAN DURDURUN, BU İŞİ YOLUNDA TUTALIM.",
["pln_hd1_12_03"] = "İÇERİDESİNİZ AMA ALARM GERİ SAYIYOR. GÜVENLİK KİLİDİNİ BULUP ALARM ÇALMADAN KAPATIN. SESSİZ KALMAYA ÇALIŞALIM.",
["pln_hd1_13_01"] = "GÜVENLİK ODASININ BAĞLI OLDUĞU SİGORTA KUTUSUNU MUTLAKA SAVUNUN. POLİSLERİN MÜDAHALESİNİ ENGELLEYİN!",
["pln_hd1_13_02"] = "POLİSLERİ SİGORTA KUTUSUNDAN UZAK TUTUN. KAPATMALARINA İZİN VERMEYİN.",
