["pln_hd1_17_01"] = "HELİKOPTERİ ÇAĞIRIRSANIZ İŞ GÜRÜLTÜYE DÖNER. HAZIR OLMADAN YAPMAYIN.",
["pln_hd1_17_02"] = "HELİKOPTER HAZIR BEKLİYOR. İSTEDİĞİNİZ ZAMAN ÇAĞIRIN AMA UYARAYIM, GÖRÜNÜR GÖRÜNMEZ ORTALIK GÜRÜLTÜYE DÖNECEK. ANINIZI SEÇİN.",
["pln_hd1_17_03"] = "SİZİ ÇIKARMAK İÇİN BEKLEYEN BİR HELİKOPTER VAR. AMA ÇAĞIRIR ÇAĞIRMAZ ORTALIK HIZLA KARIŞACAK. O YÜZDEN DOĞRU ANI SEÇİN.",
["pln_hd1_18_01"] = "ŞU AÇIK PENCEREYİ GÖRÜYOR MUSUNUZ? ORTALIK SESSİZ KALDIĞI SÜRECE GANİMETİ ORADAN DIŞARI ATIP GÜVENE ALABİLİRSİNİZ. BİR TANIDIK BİZİM İÇİN TOPLAR.",
["pln_hd1_18_02"] = "ŞU AÇIK PENCEREYİ GÖRÜYOR MUSUNUZ? GÜRÜLTÜ ÇIKMADIYSA GANİMETİ ORADAN GÜVENE ALABİLİRSİNİZ. TOPLAMAK İÇİN BAĞLANTIMIZ HAZIR.",
["pln_hd1_18_03"] = "ŞURADAKİ AÇIK PENCEREDEN GANİMETİ GÜVENE ALABİLİRSİNİZ. GÜVENDİĞİM BİR ADAM ALMAYA HAZIR AMA SADECE ORTALIK SESSİZSE.",
["pln_hd1_19_01"] = "ORAYA BİR ÇELİK HALAT KURDUM. HERHANGİ BİR GANİMET ÇANTASINI BAĞLAYIP GÜZELCE, SESSİZCE DIŞARI GÖNDEREBİLİRSİNİZ. İYİ DEĞERLENDİRİN.",
["pln_hd1_19_02"] = "GANİMETİ GÜZEL VE SESSİZCE ÇIKARABİLECEĞİNİZ BİR HALATIMIZ VAR. KULLANDIĞINIZDAN EMİN OLUN.",
["pln_hd1_19_03"] = "ORAYA ÇELİK HALAT KURULDU. GANİMETİ SESSİZCE, GİZLİCE ÇIKARMAK İÇİN. İÇERİDE ONA BAĞLAYABİLECEĞİNİZ BİR SÜRÜ DEĞERLİ ŞEY VAR.",
["pln_hd1_20_01"] = "LANET! ÇELİK HALAT ARTIK İŞE YARAMAZ. ONUNLA GANİMET GÖNDERMEYİ UNUTUN!",
["pln_hd1_20_02"] = "ÇELİK HALATIN BAŞINDAKİ ADAMIMIZ KAÇMAK ZORUNDA KALDI. ARTIK ONUNLA GANİMET ÇIKARMAYI UNUTUN. ",
["pln_hd1_20_03"] = "SİKTİR! TAMAM, ÇELİK HALATI KULLANMAYI UNUTUN. POLİSLER GELİNCE ADAMIMIZ KAÇMAK ZORUNDA KALDI.",
["pln_hd1_21_01"] = "KAMERA OPERATÖRÜ DEVRE DIŞI. ARTIK O KAMERALARI DERT ETMENİZE GEREK YOK!",
