["pln_hd1_21_03"] = "GÖZETİM KÖR OLDU. KAMERALAR DEVRE DIŞI. İŞLERİ KOLAYLAŞTIRIR.",
["pln_hd1_22_01"] = "VİTRİNLERİN ALARMLA BAĞLANTISI KESİLDİ. FAZLADAN HATIRA ALMAK İSTERSENİZ ŞİMDİ TAM ZAMANI.",
["pln_hd1_22_02"] = "VİTRİNLERİN ALARMLARI KAPANDI. EKSTRA GÜZELLİKLER KAPMAK İSTERSENİZ TAM SIRASI. BU ESERLERİ HER ZAMAN SATARIZ.",
["pln_hd1_22_03"] = "VİTRİN ALARMLARI ARTIK KAPALI. DR. JONES'A DÖNÜŞÜN BEYLER, BİRAZ ANTİKA ALIN. BUNLARI SATACAK BİRİNİ TANIYORUM. BANA GÜVENİN.",
["pln_hd1_23_01"] = "DİNLEYİN, OLUŞTURDUĞUNUZ HER YOL SINIRLI SÜRE KALACAK. YOLU YENİDEN OLUŞTURABİLİRSİNİZ, YETER Kİ KAROLARDAN BİRİNİN ÜSTÜNDE DURMAYIN.",
["pln_hd1_23_02"] = "YOL, ÖNCEDEN BELİRLENMİŞ SÜRE DOLUNCA SIFIRLANACAK. HER ZAMAN YENİSİNİ OLUŞTURABİLİRSİNİZ. YETER Kİ SIFIRLANIRKEN ÜSTÜNDE DURMAYIN,",
["pln_hd1_23_03"] = "O GÜVENLİ YOL SONSUZA KADAR KALMAYACAK EKİP. ELİNİZDEN GELDİĞİNCE YARARLANIN. YİNE DE TEKRAR OLUŞTURABİLİRSİNİZ.",
["pln_hd1_24_01"] = "İŞTE ORADA. AMA DİKKATLİ BASIN! O ZEMİN KAROLARI BASINCA DUYARLI. ÜSTLERİNE BASMAYIN! GÜVENLİ BİR GEÇİŞ YOLU OLUŞTURMANIZ GEREK! ŞURADAKİ DEVRE KUTUSUNU KULLANIN.",
["pln_hd1_24_02"] = "AH! İŞTE ORADA AMA BİRAZ BEKLEYİN. O KAROLAR BASINCA DUYARLI; BASMAYIN. ŞU DEVRE KUTUSUYLA KARŞIYA GÜVENLİ BİR YOL OLUŞTURABİLİRSİNİZ.",
["pln_hd1_24_03"] = "ŞUNA BAKIN. DURUN! O YER KAROLARI. BASINCA DUYARLILAR, ÜSTLERİNE BASMAYIN. KAPININ YANINDAKİ DEVRE KUTUSUNUN SİSTEMİNİ KIRIN, GÜVENLİ BİR GEÇİŞ YOLU AÇAR.",
["pln_hd1_25_01"] = "ŞURAYA BAKAR MISINIZ? ALIŞILMIŞ KASA DAİRELERİNDEN DEĞİL, HA?",
["pln_hd1_25_02"] = "BURAYI BİR FİLMDE GÖRDÜĞÜME EMİNİM. UMARIM DUVARLARDAN ZEHİRLİ OK ÇIKMAZ.",
["pln_hd1_25_03"] = "ÇOCUKKEN BURAYA GELMEYE BAYILIRDIM. KENDİMİ MACERACI GİBİ HİSSETTİRİRDİ, BİLİRSİNİZ.",
["pln_hd1_26_01"] = "BİR ANAHTAR KARTI ALIP ZAMAN KİLİTLERİNDE OKUTUN. KART İÇİN SİVİLLERİ KONTROL EDİN.",
["pln_hd1_26_02"] = "ANAHTAR KARTLARI SİVİLLERDE OLACAK. BİRİNİ ALIP ZAMAN KİLİTLERİNDE OKUTUN.",
["pln_hd1_26_03"] = "ZAMAN KİLİTLERİ ANAHTAR KARTLARIYLA KALDIRILABİLİR. KARTLAR SİVİLLERDE. BUNUN NEREYE VARDIĞINI ANLADINIZ MI?",
["pln_hd1_27_01"] = "BAŞARDINIZ! THE DIAMOND! BİR DE SİKTİĞİMİN PAYDAY GANG'İ. KENDİNİZİ TARİHE YAZDINIZ BEYLER.",
["pln_hd1_27_02"] = "İSMİNİZİ TARİHE KAZIDINIZ MİLLET. SOYGUNCULAR NESİLLER BOYU BU HİKÂYEYİ ANLATACAK.",
["pln_hd1_27_03"] = "DİAMOND'I ÇALAN EKİP. MÜKEMMELSİNİZ EKİP!",
["pln_hd1_28_01"] = "ŞU MEKÂNA BAKIN. KEŞKE KOSKOCA BİR BİNAYI ÇALABİLSEK.",
["pln_hd1_28_02"] = "GÜZEL BİR BİNA. HUZURLU. ÖYLE KALMASINI SAĞLAMAYA ÇALIŞIN.",
["pln_hd1_28_03"] = "MÜZEDE GECE BEKÇİLİĞİNİN HARİKA BİR İŞ OLACAĞINI DÜŞÜNMÜŞÜMDÜR HEP. AMA İŞTE, ŞU HIRSIZLIK MESELESİ VAR YA...",
["pln_hd1_29_01"] = "GELDİK, GÖRDÜK... BİR SÜRÜ ESKİ ROMA IVIR ZIVIRI SOYDUK.",
["pln_hd1_29_02"] = "BUNLARIN CAESAR'LAR ZAMANINDAN KALDIĞINI DÜŞÜNMEK İNANILMAZ.",
["pln_hd1_29_03"] = "DİKKATİNİZİ DAĞITMAYIN MİLLET. GÖZÜNÜZÜ AÇIK TUTUN... OO, BİR DAKİKA, O BİRİNCİ TRİUMVİRLİK DÖNEMİNDEN Mİ?!",
["pln_hd1_30_01"] = "GENGHİS KHAN. KORE'DEN BULGARİSTAN'A BİR İMPARATORLUK KURDU. BÜYÜK SAVAŞÇI. EKİPTE OLMASINI İSTERDİM. ",
["pln_hd1_30_02"] = "MOĞOLLAR BÜYÜK SAVAŞÇILARDI. ONLARI SAVAŞIRKEN GÖRMEYİ İSTERDİM.",
["pln_hd1_30_03"] = "SÖYLENENE GÖRE DİAMOND'I GENGHİS BULMUŞ. ONA BAYAĞI YARAMIŞ.",
["pln_hd1_31_01"] = "VAY, ŞUNLARA BAKIN. GERÇEK OLAMAZ... DEĞİL Mİ?",
