["pln_hd1_31_03"] = "ÇOCUKKEN BU ODAYI ÇOK SEVERDİM AMA ŞİMDİ... İÇİME SIKINTI VERİYOR.",
["pln_hd1_32_01"] = "BURASI 60'LARDAN BERİ DEKORE EDİLMEMİŞ GİBİ GÖRÜNÜYOR.",
