["pln_hd1_32_03"] = "KÜRATÖRÜN BODRUMDAKİ OFİSİ GİBİ GÖRÜNÜYOR.",
["pln_hd1_33_01"] = "ETRAFTA BİR SÜRÜ PAHALI ŞEY VAR. AMA VİTRİNLERDE ALARM VAR MI BAKIN, GERÇEK PARÇALAR ONLARDA OLACAK. ",
["pln_hd1_33_02"] = "BU VİTRİNLERDE GÜZEL GANİMET VAR. AMA UCUZ, SAHTE IVIR ZIVIR DA VAR. ALARMLARI ARAYIN. İYİ PARÇALARI ÖYLE BULURSUNUZ.",
["pln_hd1_33_03"] = "O VİTRİNLERDE GÜZEL ŞEYLER VAR. SAHTELERİ DE VAR. ÇALACAKSANIZ GERÇEKLERİNİ ÇALIN. ALARMI OLAN VİTRİNLERİ ARAYIN. SİZİN GİBİ AKILLI BİR EKİP ÇÖZER EMİNİM.",
["pln_hd1_34_01"] = "SOKAKLAR POLİS KAYNIYOR! O YOLDAN ÇIKAMAYIZ. BİR İŞARET FİŞEĞİ YAKIN, BEN DE HELİKOPTER GETİREYİM.",
["pln_hd1_34_02"] = "GÖRÜNÜŞE GÖRE BÜTÜN POLİSLER SİZE GELİYOR! ARABAYLA ÇIKAMAZSINIZ. BİR İŞARET FİŞEĞİ YAKIN, SİZİ HAVADAN ALALIM.",
["pln_hd1_34_03"] = "KAHRETSİN! POLİSLER ALIŞVERİŞ MERKEZİNİ KAPATTI. SİZİ HAVADAN ÇIKARACAĞIZ. HELİKOPTER İÇİN BİR İŞARET FİŞEĞİ YAKIN.",
