["pln_hd1_36_02"] = "TAM YÜK OLDU. DAYANIN. HELİKOPTER GERİ GELECEK.",
["pln_hd1_36_03"] = "GÜZEL, TAM YÜK OLDU. BEKLEYİN EKİP, BILE GERİ GELECEK.",
