["pln_hlp_04_01"] = "SEÇENEĞİMİZ YOK BENCE. O ÇARKI ÇEVİRMELİYİZ!",
["pln_hlp_04_02"] = "O ÇARKTAKİ ÖDÜLLER HOŞUMA GİTMEDİ AMA SANIRIM YİNE DE ÇEVİRMELİYİZ.",
["pln_hlp_04_03"] = "ÇEVİRİN, BAKALIM NE OLACAK.",
