["pln_hlp_05_02"] = "ÇARK KESKİN NİŞANCIDA DURDU. NE ANLAMA GELDİĞİNDEN EMİN DEĞİLİM...",
["pln_hlp_05_03"] = "PEKİİİ, ÇARK KESKİN NİŞANCIDA DURDU... ",
