["pln_hlp_23_02"] = "HAPİSHANENİN İÇİNE DOĞRU İLERLEYİN.",
["pln_hlp_23_03"] = "HARİKA, DEVAM EDELİM.",
["pln_hlp_24_01"] = "SANIRIM BAŞKA ÇARK ÇEVİRMELİYİZ. BULUN.",
["pln_hlp_24_02"] = "BURALARDA BİR YERDE BAŞKA BİR ÇARK OLMALI.",
["pln_hlp_24_03"] = "O ÇARKLARI DÖNDÜRMEYE DEVAM EDİN, SIRADAKİNİ BULUN.",
["pln_hlp_25_01"] = "O ANAHTAR KARTI'NI PANELE TAKIP ŞALTERİ İNDİRİN. BAKALIM NE OLACAK.",
["pln_hlp_25_02"] = "BAKALIM... ANAHTAR KARTI'NI PANELE TAKIP ŞALTERİ ÇALIŞTIRIN. UMARIM BÜYÜK BİR SÜRPRİZ BEKLEMİYORDUR...",
["pln_hlp_25_03"] = "ANAHTAR KARTI İÇİN BİR YUVA VAR. BENCE TAKIP NE OLACAĞINA BAKALIM...",
["pln_hlp_26_01"] = "O ANAHTAR KARTINI TAKIN.",
["pln_hlp_26_02"] = "ANAHTAR KARTI ALDINIZ, DEĞİL Mİ?",
["pln_hlp_26_03"] = "O ANAHTAR KARTINI PANELE TAKIN, ÇABUK.",
["pln_hlp_26_04"] = "NEYİ BEKLİYORSUNUZ? O ANAHTAR KARTINI PANELE TAKIN.",
["pln_hlp_26_05"] = "GERÇEKTEN ÇOK UZUN SÜRÜYOR İŞİNİZ.",
["pln_hlp_27_01"] = "ŞALTERİ ÇEKİP NE OLUYOR BAKIN.",
["pln_hlp_27_02"] = "ŞALTERİ İNDİRİN YETER MİLLET.",
["pln_hlp_27_03"] = "NE BU KADAR UZUN SÜRÜYOR? ŞU ŞALTERE BASIN İŞTE.",
["pln_hlp_27_04"] = "PANELİN YANINA GİDİP ŞU LANET ŞALTERİ İNDİRİN.",
["pln_hlp_27_05"] = "NEYİ BEKLİYORSUNUZ? O ŞALTER KENDİ KENDİNE ÇEKİLMEYECEK.",
["pln_hlp_28_01"] = "GİTMEK İSTİYORSANIZ EN ÜST KATTA BİR KAÇIŞ PANELİ VAR. YETER DİYORSANIZ ONA BİR BAKIN.",
["pln_hlp_28_02"] = "SENSÖRLERİM EN ÜST KATTA BAŞKA BİR PANEL TESPİT EDİYOR. BU KADARI YETTİYSE VE ÇIKMAK İSTİYORSANIZ ORAYA GİDİN.",
["pln_hlp_28_03"] = "BURADAN AYRILMAK İSTİYORSANIZ EN ÜST KATA BAKMAYI UNUTMAYIN. AMA O KADAR ÇOK ÇANTA VAR Kİ...",
["pln_hlp_29_01"] = "GEÇEN SEFERKİ GİBİ. GANİMETİ ALIN YA DA EN ÜST KATTAN HAPİSHANEYİ TERK EDİN.",
["pln_hlp_29_02"] = "TAMAM, YİNE AYNI: ALABİLDİĞİNİZ KADAR ÇANTAYI GÜVENE ALIN YA DA BURADAN AYRILIN. KARAR VERİN!",
["pln_hlp_29_03"] = "YAPACAĞINIZI BİLİYORSUNUZ, GANİMETİ ALIN YA DA KAÇIN.",
["pln_hlp_30_01"] = "NE YAPMANIZ GEREKTİĞİNİ AÇIKLAMAMA GEREK OLMADIĞINA EMİNİM.",
["pln_hlp_30_02"] = "BU HAPİSHANEYİ BİLİYORSUNUZ, NE YAPACAĞINIZI DA BİLİYORSUNUZ.",
["pln_hlp_30_03"] = "HER ZAMANKİ İŞLEM.",
["pln_hlp_31_01"] = "ŞU SAYACI GÖRÜYOR MUSUNUZ? GANİMETİ GÜVENCEYE ALMAK İSTİYORSANIZ ACELE EDİN!",
["pln_hlp_31_02"] = "DUVARDAKİ SAYAÇ HIZLI İLERLİYOR! GANİMETİ HAVALANDIRMAYA ATIN!",
["pln_hlp_31_03"] = "DUVARDAKİ SAATİN SÜRESİ HIZLA DOLUYOR. GANİMETİ KAPIP HAVALANDIRMAYA ATIN!",
["pln_hlp_32_01"] = "DİKKAT MİLLET, SÜRE BİTİYOR! 10 SANİYE!",
["pln_hlp_32_02"] = "SÜRE DOLMAK ÜZERE!",
["pln_hlp_32_03"] = "SAYAÇTA 10 SANİYE!",
["pln_hlp_33_01"] = "DİKKAT, ÇANTALAR PATLAYACAK GİBİ GÖRÜNÜYOR!",
["pln_hlp_33_02"] = "DİKKAT, ÇANTALAR ISINIYOR!",
["pln_hlp_33_03"] = "ŞİMDİ O ÇANTALARA DİKKAT EDİN!",
["pln_hlp_34_01"] = "BİR ARAYA TOPLANIN MİLLET!",
["pln_hlp_34_02"] = "İŞİNİZ BİTTİ, HERKES TOPLANSIN!",
["pln_hlp_34_03"] = "BİRBİRİNİZDEN AYRILMAYIN EKİP.",
["pln_hlp_35_01"] = "BURASI YIKILMAYA BAŞLIYOR. ÇIKIN!",
["pln_hlp_35_02"] = "GERİ DÖNÜŞ YOK. ŞU LANET YERDEN ÇIKIN!",
["pln_hlp_35_03"] = "GERİ DÖNÜŞ YOK, BURASI KIZIŞIYOR! ÇIKIN!",
["pln_hlp_36_01"] = "TRENE BİNİYORUZ. ÇELİK HALATI TUTUP KÖPRÜYE ÇIKIN!",
["pln_hlp_36_02"] = "KÖPRÜNÜN ÜZERİNDEKİ TRENE GİDEN BİR ÇELİK HALAT VAR. GÖKYÜZÜNDEN KAYIP GİDİN!",
["pln_hlp_36_03"] = "ÇELİK HALATLA KÖPRÜYE ÇIKIN! TEK ÇIKIŞ YOLU TREN!",
["pln_hlp_37_01"] = "BEKLEYİN MİLLET, BİRAZ C4 GÖNDERECEĞİM...",
["pln_hlp_38_01"] = "DELİRDİNİZ Mİ? O ÇANTAYI BIRAKIN!",
["pln_hlp_38_02"] = "O DA NE, FAZLADAN GANİMET Mİ? BUNU YAPMAK İSTEDİĞİNİZDEN EMİN MİSİNİZ?",
["pln_hlp_38_03"] = "ŞİMDİ AÇGÖZLÜLÜK YAPMAK İSTEDİĞİNİZDEN EMİN MİSİNİZ?",
["pln_hlp_39_01"] = "KAÇIŞ ORADA! KOŞUN!",
["pln_hlp_39_02"] = "KOŞUN SOYGUNCULAR, KOŞUN!",
["pln_hlp_39_03"] = "KAÇIŞ NOKTASINA GİDİN! ÇABUK!",
["pln_hm1_01_01"] = "BU MOTELİ DAĞITMAK, HOXTON'I KURTARMAK İÇİN İLK ADIMIMIZ. İÇERİ GİRİN.",
["pln_hm1_01_02"] = "HOXTON'I GERİ İSTİYORSAK DENTİST'İN PLANINA UYMALIYIZ. İLK ADIM: MOTELİ DAĞITIN.",
["pln_hm1_02_01"] = "MAFYALAR ODALARA MEVZİLENİYOR GALİBA. İÇERİ GİRİP GÖRDÜĞÜNÜZ BÜTÜN ÇETE ÜYELERİNİ İNDİRİN. EMNİYETLERİ AÇIN.",
["pln_hm1_02_02"] = "COMMİSSAR'IN ÇOCUKLARI BURAYA HAMAM BÖCEĞİ GİBİ ÜŞÜŞMÜŞ. ODALARA YUVALANMADAN YOK EDİN.",
["pln_hm1_02_03"] = "BURASI BİR HAMAM BÖCEĞİ MOTELİ, YALNIZ BÖCEKLER RUS MAFYACILARI. FARK ETMEZ. GİRİP İNDİRİN.",
["pln_hm1_03_01"] = "GÜM! İLKİ TAMAM.",
["pln_hm1_04_01"] = "YAKLAŞIK YARISI TAMAM.",
["pln_hm1_05_01"] = "ÜÇ TANE DAHA.",
["pln_hm1_06_01"] = "BİR TANE DAHA!",
["pln_hm1_07_01"] = "HEPSİ BU KADAR OLMALI. GÜZEL İŞ!",
["pln_hm1_08_01"] = "HARİKA İŞ EKİP. MAFYACILAR YA ÖLDÜ YA KAÇIYOR. BİZ BÖYLE YAPARIZ!",
["pln_hm1_08_02"] = "MAFYACILARIN İŞİ TAMAM, EKİP. HEPSİ ÖLMEDİYSE KAÇIYORLAR. İKİSİ DE AMACIMIZA HİZMET EDER.",
["pln_hm1_09_01"] = "ŞU MOTEL ODALARI BİRAZ YIKIM İÇİN UYGUN GÖRÜNÜYOR. İÇERİ GİRİP İÇİNİZDEKİ ROCK YILDIZINI SERBEST BIRAKIN. TELEVİZYONLARI, LAMBALARI, NE BULURSANIZ KIRIN.",
["pln_hm1_09_02"] = "COMMİSSAR BU ODALARA EPEY RUBLE HARCAMIŞ GİBİ. DAĞITIN ORTALIĞI! DEĞERLİ NE VARSA ALMAYI DA UNUTMAYIN.",
["pln_hm1_10_01"] = "COMMİSSAR'IN ADAMLARINDA FENA ARABALAR VAR. BİRAZ DAHA KIZDIRSAK MI ONLARI? BENZİN İSTASYONUNA BAKIN, YAKACAK BİR ŞEY OLMALI.",
["pln_hm1_10_02"] = "BU RUSLARI CEHENNEME YOLLAYACAĞIZ. ARABALARINI DA. YAKINDA BENZİN İSTASYONU VAR. ATEŞE YARDIM EDECEK BİR ŞEY BULMAYA ÇALIŞIN.",
["pln_hm1_11_01"] = "DENTİST'E GÖRE RUSLAR BU PİRE YUVASINDAN EPEY METAMFETAMİN GEÇİRİYOR. MUHTEMELEN ODALARDAN BİRİNDE EV YAPIMI ÜRETİM VAR. ORAYI DAĞITMAK COMMİSSAR'I GERÇEKTEN KIZDIRIR.",
["pln_hm1_11_02"] = "THE DENTIST, RUSLARIN BU ÇÖPLÜKTEN BİR SÜRÜ METAMFETAMİN ÇIKARDIĞINI SÖYLÜYOR. MUHTEMELEN ÜST KATLARDAKİ ODALARDAN BİRİNDE PİŞİRİYORLAR. ORAYI DAĞITMAK COMMİSSAR'IN DİKKATİNİ ÇEKER.",
["pln_hm1_12_01"] = "TAMAMEN ÇALIŞAN BİR METAMFETAMİN LABORATUVARI! FORMÜL GÖRÜRSENİZ PİŞİRMEYE BAŞLAYIN YA DA MEKÂNI YAKIN. HAYATINIZDA BİRKAÇ METAMFETAMİN LABORATUVARI YAKMIŞSINIZDIR EMİNİM.",
["pln_hm1_12_02"] = "BİR METAMFETAMİN FABRİKASI! YAKIN ORAYI. YA DA BİR FORMÜL BULABİLİRSENİZ PİŞİRMEYE BAŞLAYIN. FAZLADAN MALI HER ZAMAN SATARIZ.",
["pln_hm1_12_03"] = "COMMİSSAR'IN METAMFETAMİN LABORATUVARI VAR! GEÇMİŞTE BİRKAÇ LABORATUVAR YAKTIĞINIZI BİLİYORUM. VAKTİNİZ OLDUĞUNU DÜŞÜNÜYOR VE BİR TARİF BULABİLİYORSANIZ BİRAZ SİHİR DE PİŞİREBİLİRSİNİZ.",
["pln_hm1_13_01"] = "HEY, O BENZİN İSTASYONU DOSTUMUZUN HESABINDA SANIRIM. DELOREAN'DA C4 VAR. GİDİP ALIN. İŞİ BÜYÜTME VAKTİ.",
["pln_hm1_13_02"] = "DELOREAN'A BİRAZ PLASTİK PATLAYICI SAKLADIM. O BENZİN İSTASYONUNU TSAR BOMBA GİBİ UÇURMAK İÇİN KULLANABİLİRSİNİZ!",
["pln_hm1_13_03"] = "DELOREAN'DA PLASTİK PATLAYICI VAR. COMMİSSAR'IN BENZİN İSTASYONUNA YERLEŞTİRİP SPUTNİK GİBİ UÇURUN!",
["pln_hm1_14_01"] = "ŞİMDİ O C4'Ü BENZİN POMPALARINA YERLEŞTİRİN. MOSKOVA'DAN GÖRECEKLERİ BİR ATEŞ YAKACAĞIZ...",
["pln_hm1_14_02"] = "O C4'Ü İSTASYONDAKİ POMPALARA YERLEŞTİRİN. SONRA GERİ ÇEKİLİN. İYİCE UZAKLAŞIN.",
["pln_hm1_15_01"] = "EVET! KEİTH MOON'UN DOĞUM GÜNÜYMÜŞ GİBİ DAVRANIN.",
["pln_hm1_15_02"] = "BİR ŞEYLER KIRMAYA DEVAM EDİN EKİP.",
["pln_hm1_15_03"] = "DEVAM EDİN, DAĞITMAYA DEVAM EDİN!",
["pln_hm1_15_04"] = "ÇOK İYİ GİDİYORSUNUZ. PARÇALAMAYA DEVAM!",
["pln_hm1_15_05"] = "ZÜCCACİYE DÜKKÂNINDAKİ BOĞA GİBİ!",
["pln_hm1_15_06"] = "HER ŞEYİ KIRIN. TELEVİZYONLAR, LAMBALAR, KIRILACAK NE VARSA!",
["pln_hm1_16_01"] = "BAZI ADAMLAR SADECE TEKERLEKLERİN YANIŞINI İZLEMEK İSTER.",
["pln_hm1_16_02"] = "UCUZ YABANCI ARABALARIN YANIŞINI GÖRMEK KADAR SEVDİĞİM BİR ŞEY YOK.",
["pln_hm1_16_03"] = "COMMİSSAR'IN ADAMLARI YANGIN SİGORTASI YAPTIRAN TİPLERE BENZEMİYOR.",
["pln_hm1_16_04"] = "O ARABALARI YAKMAYA DEVAM EDİN EKİP. COMMİSSAR KÜPLERE BİNECEK.",
["pln_hm1_16_05"] = "BÖYLE GÜZEL ARABALARIN YANIP KÜL OLMASI YAZIK. AMA COMMİSSAR'IN DİKKATİNİ ÇEKECEKSE...",
["pln_hm1_16_06"] = "GÜZEL ARABAYMIŞ. YAZIK. AMA İŞİN BİR PARÇASI.",
["pln_hm1_17_01"] = "COMMİSSAR'IN BİZİ ARAMASI İÇİN HASAR VERMELİSİNİZ. ODALARI DAĞITIN, ARABALARI YAKIN, ADAMLARINI ÖLDÜRÜN. BU DİKKATİNİ ÇEKER.",
["pln_hm1_17_02"] = "İÇERİ GİRİP MEKÂNI DAĞITIN. ODALARI MAHVEDİN, ARABALARI YAKIN; NE YAPABİLİYORSANIZ. ÇILDIRIN. COMMİSSAR KESİN BİZİ ARAYACAKTIR.",
["pln_hm1_17_03"] = "COMMİSSAR'IN BU DÖKÜNTÜYE YANGIN VE HASAR SİGORTASI YAPTIRMADIĞINA EMİNİM. O YÜZDEN COŞUN. ODALARI DAĞITIN, ARABALARI YAKIN; O HERİFİ KIZDIRIP TELEFONA GETİRMEK İÇİN NE GEREKİYORSA YAPIN.",
["pln_hm1_18_01"] = "DİKKATİNİ ÇEKTİNİZ. AMA İZİNİ BULMAK İÇİN DAHA FAZLA ZAMAN LAZIM. DC'DE BİR YERDE. ALANI DARALTIYORUM. ÇALIŞMAYA DEVAM EDİN.",
["pln_hm1_18_02"] = "LANET OLSUN, KAPATTI. ŞEHİRDE BİR YERDEYMİŞ. KIRIP DÖKMEYE DEVAM.",
["pln_hm1_18_03"] = "İZ SÜRME ÇALIŞIYOR AMA DAHA ÇOK ZAMANA İHTİYACIM VAR. ONU YENİDEN TELEFONA GETİRİN. KIRIP DÖKMEYE DEVAM EDİN.",
["pln_hm1_19_01"] = "AZ KALDI EKİP. MERKEZE YAKIN OLMALI. BELKİ... LANET, HÂLÂ ÇOK BELİRSİZ. DEVAM EDİN.",
["pln_hm1_19_02"] = "LANET OLSUN, YERİNİ NEREDEYSE BULMUŞTUM. KESİNLİKLE MERKEZİN YAKININDA. DEVAM EDİN.",
["pln_hm1_19_03"] = "YERİNİ TESPİT ETMEYE ÇOK YAKLAŞTIK. DEVAM EDİN. BİRAZ DAHA GERİ GETİRİN ONU.",
["pln_hm1_20_01"] = "BULDUM! ADAMIMIZ ŞURADA BİR YERDE, BEKLEYİN...",
["pln_hm1_20_02"] = "VE... BULDUM! RUS DOSTUMUZ BİR YERDE... BEKLEYİN...",
["pln_hm1_21_01"] = "WEST END'DE!",
