["pln_hm1_73_03"] = "LİSEDE KİMYAYA BAYILIRDIM. YANİ BİR ŞEYLERİN HAVAYA UÇMASINA BAYILIRIM DEMEK İSTİYORUM. İYİ İŞ!",
["pln_hm1_74_01"] = "O BENZİN İSTASYONUNA BİRAZ C4 KOYMAK MESAJI VERİR. İŞE KOYULUN.",
["pln_hm1_74_02"] = "O BENZİN İSTASYONUNU CEHENNEME GÖNDERMEYİ UNUTMAYIN EKİP. C4, POMPALAR... BİLİYORSUNUZ.",
["pln_hm1_74_03"] = "BENZİN İSTASYONU BU EKONOMİDE İYİ KAZANDIRIR. PATLATIN GİTSİN. POMPALARA C4.",
["pln_hm1_75_01"] = "VAY! COMMİSSAR HER NEREDEYSE BUNU DUYDU!",
["pln_hm1_75_02"] = "KAHRETSİN! BURADAN BİLE HİSSETTİM.",
["pln_hm1_75_03"] = "HAHA, GÜRÜLTÜLÜ SOYGUNA YENİ BİR ANLAM KATTINIZ.",
["pln_hm1_76_01"] = "O HALI TUHAF DURUYOR. BENCE BİR KAPAĞI ÖRTÜYOR. NEYSE, ONU SONRA DÜŞÜNÜRÜZ.",
["pln_hm1_76_02"] = "O HALI ACELEYLE ATILMIŞ GİBİ, HERHÂLDE BİR KAPAĞI GİZLİYOR. SONRA BAKARIZ.",
["pln_hm1_76_03"] = "O HALININ ORADA OLMASI GEREKTİĞİNİ SANMIYORUM. MUHTEMELEN KAPAK GİZLİYOR. ODAYI HATIRLAYIN, BURAYA DÖNECEĞİZ.",
["pln_hm1_77_01"] = "ŞİMDİ KAPAĞA BAĞLAYIN YETER.",
["pln_hm1_77_02"] = "ŞİMDİ KAPAĞA GİDİP KABLOYU BAĞLAYIN.",
["pln_hm1_78_01"] = "BU KADAR SANDIK VARSA BURALARDA BİR YERDE LEVYE DE OLMALI.",
["pln_hm1_78_02"] = "SANDIKLARI AÇMANIN BİR YOLU OLMALI. LEVYE FALAN. ",
["pln_hm1_78_03"] = "BURALARDA BİR YERDE LEVYE VARDIR HERHÂLDE.",
["pln_hm1_79_01"] = "HIMM... BURADA OLAMAZ... ORADA DA DEĞİL...",
["pln_hm1_79_02"] = "EVET! BULDUM... HAYIR, DUR. OLAMAZ. LANET OLSUN. AZ KALMIŞTI.",
["pln_hm1_79_03"] = "BU BÖLGE ŞUNUNLA EŞLEŞİYOR... HIMM, BİRAZ DAHA ZAMAN VERİN...",
["pln_hm1_79_04"] = "HADİ, HADİ... RUS HURDASI...",
["pln_hm1_79_05"] = "COMMİSSAR BU ŞEYİ VLAD'DAN ALMIŞ GALİBA. AĞIR AKSAK RUS HURDASI...",
["pln_hm1_79_06"] = "BU HURDA 70'LERDEN KALMA. ACELE EDİN...",
["pln_hm1_79_07"] = "SOVYET DÖNEMİNDEN MAKİNE. YAVAŞ. ÇOK YAVAŞ.",
["pln_hm1_79_08"] = "LANET, COMMİSSAR BU BOK PARÇASINI ANAVATANDAN MI GETİRMİŞ?",
["pln_hm1_brf_01_01"] = "THE DENTIST BİZİ KENDİNE COMMİSSAR DİYEN BİR RUS MAFYACISININ PEŞİNE GÖNDERDİ. DOĞU YAKASI'NIN HER YERİNDE SUÇ İŞLERİ VAR, HEİGHTS'TAKİ BU MOTEL DE DÂHİL. NEREDE OLDUĞUNU BİLMİYORUZ, O YÜZDEN BİRAZ BASKI UYGULAMALISINIZ. BİZE DOĞRUDAN ULAŞACAĞI BİR HAT BIRAKTIK. ORAYI ELİNİZDEN GELDİĞİNCE DAĞITIN, ARAYACAKTIR. ARAYINCA DA İZİNİ SÜREBİLİRİZ. BUNU HOXTON İÇİN YAPIYORUZ.",
["pln_hm1_end_01_01"] = "TAMAM, COMMİSSAR'IN ADRESİNİ ALDIK. ESKİ BİR APARTMAN KOMPLEKSİ. KÖHNE BİR ÇÖPLÜK. NASIL BİR GÜVENLİKLE KARŞILAŞACAĞINIZI SÖYLEMEK ZOR. HAZIRLANIN DA BİTİRELİM ŞU İŞİ.",
["pln_hm1_end_01_02"] = "TAMAM, COMMİSSAR ŞEHİR MERKEZİNDEKİ KÖHNE BİR APARTMANA SIĞINMIŞ. NEYLE KARŞILAŞACAĞIMIZI BİLMİYORUM AMA SİZİ SESSİZCE SOKMANIN BİR YOLUNU BULDUM. YOLA ÇIKALIM.",
["pln_hm1_end_01_03"] = "COMMİSSAR KÖHNE BİR APARTMANA SIĞINMIŞ. SİZİ GİZLİCE SOKACAĞIZ AMA YİNE DE ORTALIK KARIŞACAK. YOLA ÇIKIN.",
["pln_hm1_intro_01_01"] = "COMMİSSAR KENE GİBİ YAPIŞMIŞ SAKLANIYOR. BURASI ONUN İŞLERİNDEN BİRİ. ORTALIĞI DAĞITIN. BU ÇÖPLÜĞE YETERİNCE ZARAR VERİRSENİZ BİZİ ARAR. BEN DE İZİNİ SÜRERİM.",
["pln_hm1_intro_01_02"] = "COMMİSSAR'A ULAŞMAK İÇİN ONU BULMALIYIZ. BU MOTEL ONUN İŞLERİNDEN BİRİ. VEREBİLDİĞİNİZ KADAR ZARAR VERİN. ARARSA İZİNİ SÜRERİM.",
["pln_hm2_01_01"] = "MASKELERİ TAKIN EKİP.",
["pln_hm2_01_02"] = "KUTUDAN FIRLAYAN OYUNCAK GİBİ ATLAYIN. MASKELERİ TAKIN!",
["pln_hm2_02_01"] = "MASKENİZİ TAKIP ŞU LANET SANDIKTAN ÇIKIN.",
["pln_hm2_02_02"] = "SANDIKLARDAN ÇIKIN. ONLARI HAZIRLIKSIZ YAKALAYIN.",
["pln_hm2_02_03"] = "HOXTON HÜCREDE ÇÜRÜYOR, SİZ ORADA GÖTÜNÜZÜ KAŞIYORSUNUZ. ÇIKIN SANDIKTAN!",
["pln_hm2_02_04"] = "COMMİSSAR'I TAHTA KUTUYA KOYMALIYIZ, KENDİMİZ İÇİNDE KALMAMALIYIZ. İLERLEYİN!",
["pln_hm2_02_05"] = "SİZE OYUNCAKLAR VERİYORUM, SİZ HÂLÂ KUTUDA KALMAK İSTİYORSUNUZ. HAREKETE GEÇİN!",
["pln_hm2_02_06"] = "MASKELERİ TAKIP YÜRÜYÜN! HIZLANIN!",
["pln_hm2_03_01"] = "COMMİSSAR! YAKALAYIN!",
["pln_hm2_03_02"] = "O İŞTE! İNDİRİN!",
["pln_hm2_03_03"] = "O İŞTE! KAÇMASINA İZİN VERMEYİN!",
["pln_hm2_04_01"] = "LANET OLSUN, ŞİŞKO SIÇAN ASANSÖRDE. PEŞİNE DÜŞÜN! KAÇMADAN YAKALAYIN!",
["pln_hm2_04_02"] = "ASANSÖRE BİNDİ! PEŞİNDEN YUKARI ÇIKIN. KAÇMASINA İZİN VERMEYİN.",
["pln_hm2_04_03"] = "ASANSÖRLE YUKARI GİDİYOR! KOVALAYIN! KAÇARSA DENTİST ÇOK KIZAR.",
["pln_hm2_05_01"] = "SWAT GELİYOR! YAKINDALARMIŞ. ACABA ZATEN ONU VURMAYA HAZIRLAR MIYDI?",
["pln_hm2_05_02"] = "SWAT YOLDA. COMMİSSAR'LA MOTELDEKİ SAVAŞ HAKKINDA KONUŞMAK İSTİYORLARDIR HERHÂLDE.",
["pln_hm2_05_03"] = "VAY, SWAT'LARIN GELMESİ UZUN SÜRMEDİ. ZATEN YOLDALARMIŞ DEMEK.",
["pln_hm2_06_01"] = "DEVAM EDİN, MİLLET. BURALARDA OLMALI.",
["pln_hm2_06_02"] = "DEVAM EDİN MİLLET. İZİ KAYBETMEYİN!",
["pln_hm2_06_03"] = "YUKARI GİDİYOR. ÇIKAN MERDİVENLERİ ARAYIN.",
["pln_hm2_06_04"] = "ÇATI KATINDAKİ DAİRESİ EN ÜSTTE. BENCE ORAYA GİDİYOR.",
["pln_hm2_06_05"] = "ÜST KATA ÇIKMAYA ÇALIŞIN. ",
["pln_hm2_07_01"] = "AZ KALDI MİLLET. DEVAM EDİN.",
["pln_hm2_07_02"] = "BU MANYAĞIN İNİ İLERİDE OLMALI.",
["pln_hm2_07_03"] = "BURASI ÇATI KATI. COMMİSSAR BURADA OLMALI.",
["pln_hm2_08_01"] = "BU DAİRENİN İÇİNDE. AÇIN.",
["pln_hm2_08_02"] = "İŞTE BURASI. COMMİSSAR'IN DAİRESİ. GEÇİN.",
["pln_hm2_08_03"] = "İŞTE BURASI. KIRIP GİRİN. NASIL YAPTIĞINIZ UMURUMDA DEĞİL, YAPIN YETER!",
["pln_hm2_09_01"] = "NEREDE O?!",
["pln_hm2_09_02"] = "SIÇAN AŞAĞI MI ATLADI...? HAYIR. OLAMAZ.",
["pln_hm2_09_03"] = "O KURNAZ PİÇ ORTADAN MI KAYBOLDU?",
["pln_hm2_10_01"] = "KURNAZ PİÇ! KASA DAİRESİNİ PANİK ODASI OLARAK KULLANIYOR. SİZE TERMAL MATKAP BIRAKAYIM.",
["pln_hm2_10_02"] = "BİR KASA DAİRESİ! COMMİSSAR KIÇINI KURTARMAK İÇİN HER YOLU DENİYOR. TERMAL MATKAP YOLLUYORUM.",
["pln_hm2_10_03"] = "DELİ RUS KENDİNİ KASA DAİRESİ'NE KİLİTLEMİŞ! KIRIN AÇIN. SİZE TERMAL MATKAP YOLLUYORUM.",
["pln_hm2_11_01"] = "MATKAP BIRAKILDI. ALIN. O KASA DAİRESİ'Nİ AÇIN.",
["pln_hm2_11_02"] = "MATKAP BÖLGEDE. PİLOT 'BİR ÇATI PENCERESİNDEN' DEDİ. BULUN!",
["pln_hm2_11_03"] = "MATKABINIZ ORADA. KASA DAİRESİNDE ÇALIŞTIRIN.",
["pln_hm2_12_01"] = "SON BİR HAMLE YAPIYORLAR. O HELİKOPTERDEN UZAK DURUN!",
["pln_hm2_12_02"] = "COMMİSSAR ELİNDE KALAN HER ŞEYİ YOLLUYOR! LANET SALDIRI HELİKOPTERİNİ BİLE! MESAFENİZİ KORUYUN!",
["pln_hm2_12_03"] = "COMMİSSAR AĞIR SİLAHLARI ÇAĞIRDI. HEM DE ÇOK AĞIR SİLAHLARI. O HELİKOPTERDEN UZAK DURUN!",
["pln_hm2_13_01"] = "YAĞMURLAMA SİSTEMİYLE O YANGINLARI SÖNDÜRÜN.",
["pln_hm2_13_02"] = "COMMİSSAR BİR ŞEY Mİ ÇEVİRİYOR? O YANGINLARI SÖNDÜRÜN!",
["pln_hm2_13_03"] = "O YANGINLARI HALLETMENİZ GEREK. YANGIN FISKİYELERİNİ KULLANIN.",
["pln_hm2_13_04"] = "EKİP, YANGINLARI SÖNDÜRÜN. KARGAŞADA KAÇMASINI GÖZE ALMAK İSTEMEYİZ.",
["pln_hm2_13_05"] = "YANGINLARI HALLEDİN EKİP.",
["pln_hm2_13_06"] = "YANGIN FISKİYELERİNİ AÇIN. YANGINLARI SÖNDÜRMENİZ GEREK.",
["pln_hm2_14_01"] = "İÇERİSİ BİRAZ SICAKTI AMA İYİ YAPTINIZ.",
["pln_hm2_14_02"] = "UMARIM FAZLA KIZARMAMIŞSINIZDIR. HARİKA İŞ.",
["pln_hm2_14_03"] = "YANGINLAR SÖNDÜ. İYİ HALLETTİNİZ.",
["pln_hm2_14_04"] = "YANGINLAR SÖNDÜ. AFERİN MİLLET.",
["pln_hm2_14_05"] = "YANGINLAR TAMAM.",
["pln_hm2_14_06"] = "YANGINLAR KONTROL ALTINDA. ŞİMDİ İŞE DÖNELİM.",
["pln_hm2_15_01"] = "KAPI AÇILDI! ŞİMDİ BU İŞİ BİTİRME VAKTİ. ONU HALLEDİN.",
["pln_hm2_15_02"] = "KASA DAİRESİ AÇIK. İÇERİ GİRİN. İŞİNİ BİTİRİN. THE DENTIST İZLİYOR.",
["pln_hm2_15_03"] = "MATKAP BİTİRDİ. COMMİSSAR'IN DA BİTME VAKTİ.",
["pln_hm2_16_01"] = "İŞTE BU. COMMİSSAR ÖLDÜ. HOXTON'I GERİ ALMAYA BİR ADIM DAHA YAKLAŞTIK. HELİKOPTER GÖNDERİYORUM, YERİNİZDE KALIN. YUKARIDA İYİ İŞ ÇIKARDINIZ.",
["pln_hm2_16_02"] = "ÖLDÜ. İYİ DE OLDU. HELİKOPTER YOLDA MİLLET. DENTİST ONUNLA BİRKAÇ ŞİŞE ŞAMPANYA GÖNDERDİ. HOXTON DA MİNNETTARDIR EMİNİM. İYİ İŞ ÇIKARDINIZ.",
["pln_hm2_16_03"] = "VE SON. PİSLİK YOLDAŞ ÖLDÜ. HELİKOPTER GELİYOR. BUGÜN HARİKA İŞ ÇIKARDINIZ. THE DENTIST VE HOXTON SİZE TEŞEKKÜR EDECEK.",
["pln_hm2_17_01"] = "BU ONLARI ŞAŞIRTTI. ŞİMDİ COMMİSSAR'I BULUN.",
["pln_hm2_17_02"] = "BUNU BEKLEMİYORLARDI! ŞİMDİ ŞU RUS SIÇANINI BULMA VAKTİ.",
["pln_hm2_17_03"] = "YAKALADIK! COMMİSSAR BURALARDA BİR YERDE.",
["pln_hm2_18_01"] = "O KÖSTEBEK GÜÇLENDİRİLMİŞ KAPININ ÖBÜR TARAFINDA OLMALI. İÇERİDEKİ ADAMIMIZ BİR MİKTAR C4 BIRAKTI. ALIN.",
["pln_hm2_18_02"] = "İÇERİDEKİ ADAMIMIZ SİZE BİR AVUÇ PATLAYICI SAĞLADI. ALIP O KAPIYI ÇALIN.",
["pln_hm2_18_03"] = "KIZ İZCİ KURABİYESİ SATMADIĞIMIZI BİLİYORLAR HERHÂLDE. C4'Ü ALIP PATLATARAK GİRİN.",
["pln_hm2_19_01"] = "İYİ HABER: COMMİSSAR'IN ÇATI KATINDA KOCAMAN BİR KOKAİN ZULASI VAR. KÖTÜ HABER: OLABİLDİĞİNCE HIZLI SİFONU ÇEKİP DÖKÜYOR. TUVALETTEN AŞAĞI SERVET DÖNÜYOR. NE KADAR HIZLI VARIRSANIZ BONUS O KADAR BÜYÜK!",
["pln_hm2_19_02"] = "EKİP, O KİNCİ PİÇ COMMİSSAR SIRF İNAT OLSUN DİYE BİR SERVET DEĞERİNDE KOKAİNİ DÖKÜYOR! YUKARI ÇIKIP KURTARIN. NE KADAR HIZLI OLURSANIZ O KADARINI KURTARIRSINIZ!",
["pln_hm2_19_03"] = "VAY, COMMİSSAR'IN BURADA BİR SÜRÜ KOKAİNİ VAR AMA GERÇEK BİR RUS GİBİ YAKIP YIKMA TAKTİĞİ UYGULUYOR. YANİ MALI YOK EDİYOR. ÇABUK ULAŞMAZSANIZ BİR DÜNYA EK GELİRİ KAÇIRIRSINIZ!",
["pln_hm2_19_04"] = "COMMİSSAR BELLİ Kİ 'BENİM OLAMIYORSA KİMSENİN OLMASIN' DİYOR. KÖŞEYE SIKIŞTI, ADAMLARINA DAĞ GİBİ KOKAİNİ TUVALETLERE DÖKTÜRÜYOR! ACELE EDİP DURDURUN, KOKAİN SİZİN OLSUN!",
["pln_hm2_20_01"] = "MİLLET, UNUTMAYIN! YUKARI NE KADAR ERKEN ÇIKARSANIZ O KADAR ÇOK KOKAİN ALABİLİRİZ.",
["pln_hm2_20_02"] = "DAHA FAZLA KOKAİNİ GİDERDEN DÖKTÜLER. MİLLET, BÜYÜK VURGUN İSTİYORSANIZ ACELE ETMELİSİNİZ.",
["pln_hm2_20_03"] = "LANET OLSUN! BİR ÇANTA KOKAİNİ DAHA TUVALETE DÖKTÜLER! ACELE EDİN EKİP! SON KATA ÇIKIN!",
["pln_hm2_20_04"] = "LANET OLSUN, COMMİSSAR BİRAZ DAHA KOKAİNİ DOĞRUDAN TUVALETE DÖKTÜ. HEPSİ BİTMEDEN ACELE EDİN!",
["pln_hm2_20_05"] = "DAHA FAZLA KOKAİN TUVALETE GİTTİ. O MAL SAF, BİR SERVET EDER. YUKARI ÇIKIN!",
["pln_hm2_20_06"] = "O RUS PİÇİN MALI YOK ETTİĞİNE İNANAMIYORUM. HEPSİ GİTMEDEN ULAŞIN!",
["pln_hm2_20_07"] = "KAHRETSİN, DAHA FAZLA KOKAİN AKIP GİTTİ. BİNLERCE DOLAR BOKLARLA BİRLİKTE DÖNÜP GİDİYOR. ÇABUK OLUN!",
["pln_hm2_20_08"] = "KOKAİNİ TUVALETE DÖKÜYORLAR. MİLLET, HEPSİ GİTMEDEN YUKARI ÇIKIN!",
["pln_hm2_20_09"] = "ORADA YENİ ÇEK ALMIŞ HOLLYWOOD YAPIMCILARI GİBİ KOKAİN HARCIYORLAR! GAZA BASIN!",
["pln_hm2_20_10"] = "İÇERİSİ FIRIN GİBİ, TOZLAR HAVADA UÇUŞUYOR. PAY İSTİYORSANIZ HIZLANSANIZ İYİ OLUR!",
["pln_hm2_20_11"] = "ACELE EDİN, HER LANET SANİYE BİNLERCE DOLARLIK KOKAİN HARCIYORLAR!",
["pln_hm2_20_12"] = "HAYATLARI BUNA BAĞLIYMIŞ GİBİ KOKAİNİ GİDERDEN DÖKÜYORLAR! ACELE EDİN!",
["pln_hm2_20_13"] = "O KOKAİNİ CİDDİ CİDDİ DÖKÜYORLAR! YUKARI ÇIKIP DURDURUN ONLARI!",
["pln_hm2_20_14"] = "HER SANİYE DEĞERLİ MİLLET! HÂLÂ KALMIŞKEN O KOKAİNE ULAŞIN!",
["pln_hm2_20_15"] = "BİR YERDE TAKILMAYIN, YUKARI İLERLEMEYE DEVAM! DEĞECEK AMA HIZLA ZİYAN OLUYOR!",
["pln_hm2_20_16"] = "ODAKLANIN! YUKARI İLERLEYİN! KOKAİNİ SANKİ BUNUN EĞİTİMİNİ ALMIŞLAR GİBİ ZİYAN EDİYORLAR!",
["pln_hm2_20_17"] = "ÇABUK! ÇANTA ÇANTA KOKAİNİ DÖKÜYORLAR, BİR DE KEYİF ALIYORLAR GİBİ!",
["pln_hm2_20_18"] = "İLERLEMEYE DEVAM EDİN! SÜRELİ FIRSAT DİYE BUNA DENİR!",
["pln_hm2_20_19"] = "BİR VİTES DAHA ATAR MISINIZ? O KOKAİN YIĞINI KORKUTUCU HIZLA KÜÇÜLÜYOR!",
["pln_hm2_20_20"] = "GERÇEKTEN KAÇIYORMUŞ GİBİ KOŞUN! SADECE YOLUNUZDAKİLERİ ÖLDÜRÜN, BAŞKASINA ZAMAN VE MERMİ HARCAMAYIN!",
["pln_hm2_20_21"] = "YUKARI YETERİNCE HIZLI ÇIKARSANIZ BİR SERVET KAZANIRIZ. HADİ! BİRAZ GAYRET!",
["pln_hm2_21_01"] = "AH, BÜTÜN BU KOKAİNİN GİDERDEN AKIP GİTTİĞİNİ VE SİZİN HÂLÂ AĞIRDAN ALDIĞINIZI GÖRMEK BENİ ÜLSER EDECEK!",
["pln_hm2_21_02"] = "YARISI ŞİMDİDEN GİTTİ! İLERİ, YUKARI, BASTIRIN! O KOKAİNE ULAŞMALISINIZ!",
["pln_hm2_21_03"] = "OYALANMAYIN, KOKAİNE ULAŞIN! ŞAKALARI YOK! AH, ZAVALLI KALBİM...",
["pln_hm2_21_04"] = "HIZLANIN MİLLET! KAYBEDİLEN HER SANİYE, KAYBEDİLEN PARA DEMEK! BURADA DELİRİYORUM!",
["pln_hm2_21_05"] = "HATIRLATMAM GEREKİYOR MU? BİZ KONUŞURKEN SERVET DEĞERİNDE KOKAİN YOK EDİLİYOR!",
["pln_hm2_21_06"] = "ALLAH AŞKINA YUKARI ÇIKIP ONLARI DURDURUN! BU BİR TRAJEDİ!",
["pln_hm2_21_07"] = "SİZİ NEYİN BU KADAR GECİKTİRDİĞİNİ BİLMİYORUM AMA O KOKAİN SİZİ BEKLEMİYOR.",
["pln_hm2_21_08"] = "LANET OLSUN, O ODADA BOMBA PATLASA BİLE KOKAİN DAHA HIZLI MAHVOLAMAZDI! ÇIKIN! ŞURAYA! ARTIK!",
["pln_hm2_21_09"] = "O KOKAİNİN ÇOK PARA ETTİĞİNİ BİLİYORSUNUZ, DEĞİL Mİ? DEĞİL Mİ!? ÇABUK, ÇABUK, ÇABUK!",
["pln_hm2_21_10"] = "BİR ÇANTA KOKAİN DAHA GİTTİ. BİR TANE DAHA... VE... DEVAM EDEYİM Mİ? İÇLER ACISI.",
["pln_hm2_22_01"] = "AH BE, NEREDEYSE HEPSİ GİTTİ. HEPSİ! LÜTFEN, EN AZINDAN BİRAZINI ALMAYA ÇALIŞIN!",
["pln_hm2_22_02"] = "BU KADAR ÇOK PARANIN ZİYAN OLDUĞUNU HİÇ GÖRMEDİM! HADİ, SON KALANLARI ALIN!",
["pln_hm2_22_03"] = "ARTIK PEK KALMADI... BİRAZ HIZLANIRSANIZ FAZLADAN BİRKAÇ BİN KAZANABİLİRSİNİZ.",
["pln_hm2_22_04"] = "ARTIK KIRINTILAR KALDI! UMDUĞUMDAN AZ OLSA DA FAZLADAN PARADIR, GİDİP ALIN!",
["pln_hm2_22_05"] = "ACELE EDİN ARTIK! BUNCA KOKAİNİN ZİYAN OLMASI KALBİMİ KIRIYOR!",
["pln_hm2_22_06"] = "BİRAZ KOKAİN KALDI! ACELE EDERSENİZ BELKİ BİRAZ DAHA KAZANIRSINIZ! BELKİ!",
["pln_hm2_23_01"] = "EH! SON ÇANTA DA TUVALETE GİTTİ. ÜZGÜNÜM MİLLET, BU SEFER FAZLADAN KAZANÇ YOK.",
["pln_hm2_23_02"] = "TAMAMDIR! SON ÇANTAYI DA TUVALETE ATTILAR. BANA BİR DAKİKA VERİN, AZ ÖNCE OLANLARI ZİHNİMDE SİNDİRMEM GEREK...",
["pln_hm2_23_03"] = "BÜTÜN KOKAİNİ DÖKMEYİ BİTİRDİLER. LANET OLSUN EKİP! ÇOK BÜYÜK FIRSAT KAÇIRDIK!",
["pln_hm2_24_01"] = "TAMAM, NEYSE... COMMİSSAR'I ÇATI KATINDA BULUP ÖLDÜRELİM. O PİÇ BEDELİNİ ÖDEYECEK.",
["pln_hm2_24_02"] = "TAMAM, HER NEYSE... KAZANMANIN BAŞKA BİR YOLU HÂLÂ VAR: COMMİSSAR'I BULUP ÖLDÜRÜN! ARTIK MOTİVE OLDUĞUNUZU SANIYORUM!",
["pln_hm2_24_03"] = "HIMM... ÜZÜCÜ AMA KAYBEDECEK VAKTİMİZ YOK! ŞİMDİ COMMİSSAR'A ODAKLANIN, İZİNİ SÜRÜP GEBERTİN!",
["pln_hm2_25_01"] = "MİLLET, RANDEVUDA DEĞİLSİNİZ. GEZİNMEYİ BIRAKIP HIZLANIN. YÜRÜYÜN!",
["pln_hm2_25_02"] = "MİLLET, BURASI TURİSTİK GEZİ YERİ DEĞİL. YUKARI ÇIKIN, HADİ, KIPIRDAYIN!",
["pln_hm2_25_03"] = "PİZZA MI BEKLİYORSUNUZ? HADİ, KIPIRDAYIN.",
["pln_hm2_25_04"] = "HADİ, HIZLANMANIZ GEREKİYOR!",
["pln_hm2_25_05"] = "MİLLET, COMMİSSAR KAÇARSA HOXTON İÇERİDE ÇÜRÜR. KIMILDAYIN!",
["pln_hm2_25_06"] = "BUNU HOX İÇİN YAPIYORSUNUZ, KIPIRDAYALIM ARTIK!",
["pln_hm2_26_01"] = "COMMİSSAR BU ODADA NE ÇEVİRİYOR LAN?",
["pln_hm2_26_02"] = "VAY BE! COMMİSSAR, SENİ AZGIN İHTİYAR.",
["pln_hm2_26_03"] = "EE... PEK HARİKALAR DİYARI SAYILMAZ, DEĞİL Mİ?",
["pln_hm2_26_04"] = "COMMİSSAR, ADAM KAÇIRMAK DA DÂHİL PİS İŞLERLE ELİNİ KİRLETİYOR.",
["pln_hm2_26_05"] = "ADAM KAÇIRMA MI? O PİS RUS'UN SINIRI YOK.",
["pln_hm2_26_06"] = "O ADAM COMMİSSAR'I KIZDIRMAK İÇİN NE YAPTI BİLMİYORUM AMA KÖTÜ BİR ŞEY OLMALI.",
["pln_hm2_26_07"] = "BU ÇÖPLÜK, COMMİSSAR GİBİ BİR SIÇANIN SAKLANMASI İÇİN BİÇİLMİŞ KAFTAN.",
["pln_hm2_26_08"] = "ÜLKEMİZİN KALBİNDE BÖYLE BİR ÇÖPLÜK OLDUĞUNA İNANAMAZSINIZ.",
["pln_hm2_26_09"] = "NE BOKTAN BİR ÇÖPLÜK.",
["pln_hm2_27_01"] = "O KAPIYA MATKAP KURUP AÇIN!",
["pln_hm2_27_02"] = "KOLAY BİR ÇÖZÜMÜ OLMALI! O KAPIYA MATKAP KURUN MİLLET.",
["pln_hm2_27_03"] = "O KAPIYI MATKAPLA AÇIN MİLLET.",
["pln_hm2_28_01"] = "BU KAPI BİR TÜR MANYETİK MEKANİZMAYLA KİLİTLİ. AÇMANIN BİR YOLUNU BULUN!",
["pln_hm2_28_02"] = "KABLOLARI DUVARIN ARKASINA ALACAK VAKİTLERİ OLMAMIŞ GİBİ. ŞALTERİ BULUN.",
["pln_hm2_28_03"] = "KABLOLARI TAKİP EDİP BU KAPIYI AÇMANIN BİR YOLUNU BULABİLİRSİNİZ.",
["pln_hm2_29_01"] = "MERDİVEN KAPATILMIŞ! YAKINLARDA YUKARI ÇIKMANIN BİR YOLU OLMALI!",
["pln_hm2_29_02"] = "MERDİVEN KAPALI. YUKARI BAŞKA BİR YOL OLMALI.",
["pln_hm2_29_03"] = "BU YOLDAN YUKARI ÇIKILMIYOR. ETRAFA BAKIN. BAŞKA YOL OLMALI.",
["pln_hm2_30_01"] = "ŞİMDİ BEKLİYORUZ. COMMİSSAR ORADA SONSUZA KADAR SAKLANAMAZ.",
["pln_hm2_30_02"] = "HARİKA. ŞİMDİ BEKLEYİN. O SIÇAN YAKINDA ELİMİZDE OLACAK.",
["pln_hm2_30_03"] = "BIRAKIN MATKAP İŞİNİ YAPSIN. COMMİSSAR'I YAKINDA ALIRIZ.",
["pln_hm2_31_01"] = "O KASA DAİRESİNİ YAĞMALAMAYI UNUTMAYIN. GANİMETİ HELİKOPTERE TAŞIYIN. BİRAZ EK PARA KAZANMAK HEP GÜZELDİR BEYLER.",
["pln_hm2_31_02"] = "KASA DAİRESİNDEKİ GÜZEL GANİMETİ GÖRDÜĞÜNÜZE EMİNİM. BİRAZ DAHA KALABİLİRSENİZ HELİKOPTERE YÜKLEYİN.",
["pln_hm2_31_03"] = "COMMİSSAR'IN BÜTÜN ŞU KANLI PARASINA BAKIN. NEYSE, BİRİNİN KEYFİNİ SÜRMESİ GEREK. YAPABİLİRSENİZ HELİKOPTERE GÖTÜRÜN.",
["pln_hm2_34_01"] = "KOKAİN ORADA. MUHTEŞEMSİNİZ, MİLLET! ALABİLDİĞİNİZ KADARINI ÇANTALAYIN.",
["pln_hm2_34_02"] = "KOKAİN BU MİLLET. BAŞARACAĞINIZI BİLİYORDUM! ŞİMDİ ÇANTALAYIN.",
["pln_hm2_34_03"] = "MÜKEMMEL! O KOKAİN GÜZEL BİR İKRAMİYE OLUR. ÇANTALAYIN EKİP!",
["pln_hm2_brf_01_01"] = "SİZİ COMMİSSAR'IN MEKÂNINA SOKMAK İÇİN SANDIK KULLANIYORUZ. TRUVA ATI USULÜ. DAİRESİ ŞEHRİN BOKTAN BİR YERİNDEKİ PİS BİR ÇÖPLÜK. GÜVENLİK PEK İYİ DEĞİL AMA EMİNİM O VE ADAMLARI KENARDA BİR KOZ TUTUYORDUR. HEDEF BASİT: COMMİSSAR'I BULUN VE ÖLDÜRÜN. ORTALIK GÜRÜLTÜLÜ OLACAK, ONA GÖRE KUŞANIN.",
["pln_hm2_intro_01_01"] = "COMMİSSAR MOTEL SALDIRISINDAN SONRA HUZURSUZDUR AMA BUNU BEKLEMEYECEK. MASKELERİ TAKIP KÖSTEBEĞE HAK ETTİĞİNİ VERİN. İYİ ŞANSLAR.",
["pln_hm2_intro_01_02"] = "MOTELDE YAPTIKLARINIZDAN SONRA COMMİSSAR'IN ADAMLARI GERGİN OLACAK. YİNE DE BUNU BEKLEMİYORLARDIR. MASKELERİNİZİ TAKIP O SIÇANI İNDİRİN.",
["pln_hur_01_01"] = "SAAT İŞLİYOR, MİLLET!",
["pln_hur_01_02"] = "ZAMANA KARŞI YARIŞIYORSUNUZ, MİLLET!",
["pln_hur_01_03"] = "ÇABUK MİLLET.",
["pln_hur_01_04"] = "ACELE EDİN ÇOCUKLAR.",
["pln_hur_01_05"] = "DAHA HIZLI ÇALIŞIN!",
["pln_indif_01_01"] = "POLİSLER AĞIR TAKVİYE ÇAĞIRDI!",
["pln_indif_01_02"] = "TAMAM, POLİSLER İŞİ BİR ÜST SEVİYEYE TAŞIDI. DAHA ZORLU BİRLİKLER GELİYOR!",
["pln_indif_01_03"] = "SIÇTIK, POLİS AZ ÖNCE AĞIR TAKVİYE ÇAĞIRDI!",
["pln_indif_01_04"] = "MİLLET, DİNLEYİN. ÇOK DAHA SERT RAKİPLER YOLDA!",
["pln_indif_01_05"] = "SWAT İŞİ BÜYÜTÜYOR MİLLET. ORTALIK KARIŞACAK!",
["pln_indif_01_06"] = "ARKANIZI KOLLAYIN, DAHA ZORLU SWAT BİRLİKLERİ GELİYOR!",
["pln_indif_01_07"] = "HAZIRLANIN, ÇOK BELALI BİR POLİS GÜCÜ GELİYOR!",
["pln_indif_01_08"] = "DAHA FAZLA BİRİM, DAHA FAZLA SİLAH SİZE GELİYOR EKİP!",
["pln_indif_01_09"] = "DİŞİNİZİ SIKIN. POLİS BİR VİTES DAHA ATIYOR. AĞIR BİRLİKLER GELİYOR!",
["pln_indif_01_10"] = "SİKTİR, KÖTÜ POLİSLER GELİYOR; HEM DE ÇOK KÖTÜ POLİSLER. BAŞINIZI EĞİN!",
["pln_indif_01_11"] = "AĞIR TEÇHİZATLI DAHA FAZLA POLİS YAKLAŞIYOR. KİMİN PATRON OLDUĞUNU GÖSTERİN!",
["pln_indif_01_12"] = "ONLARA CEHENNEMİ YAŞATIN MİLLET, ONLAR DA SİZE AYNISINI YAPMAYI PLANLIYOR. YENİ BİRLİKLER GELİYOR!",
["pln_indif_01_13"] = "ÇOK DAHA FAZLA POLİS GELİYOR. SİLAHLARI DA ARTMIŞ GİBİ.",
["pln_jewelrystore_stage1_brief_a_01"] = "BU ŞEHİR MÜCEVHER ELDEN ÇIKARMAK İÇİN HARİKA. SATMASI KOLAY. DİPLOMATLAR VE ZENGİN ADAMLARIN GENÇ EŞLERİ SORGUSUZ SUALSİZ ALIYOR. ÇOCUK OYUNCAĞI OLACAK. BAŞLAYALIM.",
["pln_jewelrystore_stage1_brief_b_01"] = "TAMAM EKİP. BU KUYUMCUNUN BİRKAÇ VİTRİNİNDE ORTA DEĞERDE MÜCEVHER VE ALTIN SERGİLENİYOR. ",
["pln_jewelrystore_stage1_brief_b_02"] = "TAMAM EKİP, BURADA BİR SÜRÜ VİTRİN VAR. KIRIP KAPIN, GANİMET ÇANTALARINI AĞZINA KADAR DOLDURUN. ",
["pln_jewelrystore_stage1_brief_b_03"] = "PEKÂLÂ MİLLET, BU GÜZEL BİR FIRSAT. VİTRİNLERDE ÇEŞİT ÇEŞİT ORTA KALİTE ELMAS FALAN VAR. HÜNERİNİZİ GÖSTERİN, KENDİNİZİ KANITLAYIN, SONRA ÇIKIN. KLASİK BİR SOYGUN.",
["pln_jewelrystore_stage1_cnc_01"] = "SOYULMAK İÇİN ADETA YALVARAN BİR KUYUMCU BULDUM. BENİ ARAYIN.",
["pln_jewelrystore_stage1_cnc_02"] = "GÖRÜNÜŞE GÖRE BİRAZ HAFİFLETİLMEYE İHTİYACI OLAN BİR KUYUMCU VAR. BENİ ARAYIN.",
["pln_jewelrystore_stage1_cnc_03"] = "ELMAS BÖLGESİNDE TATLI BİR VURGUN, MİLLET. HERKESE PIRLANTA.",
["pln_jewelrystore_stage1_end_01"] = "BU DÜKKÂNIN SAHİBİ BİR AY SİGORTA EVRAKIYLA UĞRAŞACAK. GÜZEL VURGUN ÇOCUKLAR, EVE DÖNELİM.",
["pln_jewelrystore_stage1_end_02"] = "ORADA BAYAĞI GÜZEL BİR KAPKAÇ YAPTINIZ. BAHSE GİRERİM DAHA İYİ GÜVENLİĞE YATIRIM YAPACAKLAR YA DA KAPATACAKLAR. BİZİM SORUNUMUZ DEĞİL.",
["pln_jewelrystore_stage1_end_03"] = "BÜTÜN O MÜCEVHERLERİ KAPARAK İYİ İŞ ÇIKARDINIZ MİLLET. DİPLOMATİK BAĞLANTILARIMA ÖNCEDEN HABER VERDİM, BUNA AÇLAR. DOYURALIM ONLARI.",
["pln_jewelrystore_stage1_end_04"] = "GERÇEKTEN ZEVKTİ, ESKİ GÜNLERİ HATIRLATIYOR. KÜÇÜK BAŞLAYIP BASİT ŞEYLER YAPMAK, DEĞİL Mİ? İYİ İŞ.",
["pln_jewelrystore_stage1_end_05"] = "CRIME.NET KAYNIYOR. BURADA GÜZEL BİR SÜRPRİZ YAPTINIZ.",
["pln_jewelrystore_stage1_end_06"] = "DC'DE ARTIK MÜCEVHER KITLIĞI VAR. İŞTE BİZ BURADA DEVREYE GİRİYORUZ. İYİ İŞ EKİP!",
["pln_jewelrystore_stage1_end_07"] = "TAMAM, BUNLARI ELDEN ÇIKARMAYA HEMEN BAŞLAYACAĞIM. ZOR OLMAZ; TAM İDEAL MALLAR. GÜZEL İŞ!",
["pln_jewelrystore_stage1_intro_01"] = "TAMAM, BASKIN VAKTİ. İÇERİDE GARNET ÜRÜNLERİ DE GÖREBİLİRSİNİZ. BUNCA YAPTIĞIMIZDAN SONRA HÂLÂ İŞ BAŞINDA OLMALARINI SEVİYORUM. BU İŞE DEĞMESİ İÇİN EN AZ İKİ ÇANTA LAZIM.",
["pln_jewelrystore_stage1_intro_02"] = "BU DÜKKÂN MÜCEVHERLE TIKA BASA DOLU GÖRÜNÜYOR. HERKES TATİL DÖNEMİ İÇİN HAZIRLANIYOR HERHÂLDE. NEYSE, EN AZ DÖRT ÇANTA MÜCEVHER İSTİYORUM. BU BİZE GAYET İYİ YETER.",
["pln_jewelrystore_stage1_intro_03"] = "TAMAM, MEKÂNI SİLİP SÜPÜRMELİYİZ. SEKİZ ÇANTA YETERLİ OLUR. ACIMAYIN!",
["pln_jewelrystore_stage1_intro_04"] = "TAMAM, MÜCEVHER BASKINI VAKTİ. EN AZ ÜÇ ÇANTA LAZIM. EPEY KOLAY OLMALI.",
["pln_jewelrystore_stage1_intro_05"] = "TAMAM, KUYUMCU SOYGUNU VAKTİ. EN AZ ALTI ÇANTA LAZIM. ZORLAYABİLİR AMA SİZ YAPARSINIZ!",
["pln_jewelrystore_stage1_intro_06"] = "TAMAM, MÜCEVHER BASKINI VAKTİ. EN AZ ON ÇANTA LAZIM. BİRAZ ÇILGINCA AMA ÇILGINLIK SİZİN İŞİNİZ!",
["pln_jr1_01_01"] = "YETKİYİ VERİN EKİP.",
["pln_jr1_01_02"] = "GÖSTERİN ONLARA EKİP",
["pln_jr1_01_03"] = "VERİN COŞKUYU EKİP!",
["pln_jr1_02_01"] = "LOCKE'UN SANDIKLARINI BULUN MİLLET. ÜZERİNDE ÇAKAR IŞIK OLANLARI ARAYIN.",
["pln_jr1_02_02"] = "HEY MİLLET, LOCKE'UN BIRAKTIĞI SANDIKLARI BULMAYI UNUTMAYIN. ÜZERLERİNDE ÇAKAR IŞIK VAR.",
["pln_jr1_02_03"] = "HADİ EKİP. LOCKE O SANDIKLARI BULMAMIZI İSTİYOR. ONA NASIL YAPILDIĞINI GÖSTERİN.",
["pln_jr1_03_01"] = "PATLAYICILARI KAPIYA BIRAKIN MİLLET.",
["pln_jr1_03_02"] = "LOCKE O KAPIYI PATLATMAMIZI İSTİYOR. PATLAYICILARI ORAYA BIRAKSANIZ İYİ OLUR.",
["pln_jr1_03_03"] = "BU İŞTE LOCKE'UN TALİMATLARINA UYSAK İYİ OLUR. PATLAYICILARI KAPIYA GÖTÜRÜN.",
["pln_jr1_04_01"] = "DEDİĞİNİ YAPSANIZ İYİ OLUR.",
["pln_jr1_04_02"] = "BİRAZ KAÇIK GİBİ. EN İYİSİ YAPIN.",
["pln_jr1_04_03"] = "LOCKE BİRAZ... DELİ GİBİ KONUŞUYOR. DEDİĞİNİ YAPSAK İYİ OLUR.",
["pln_jr1_05_01"] = "YAKINDA GÜVENLİK ODASI OLMALI. ARK KAYNAĞIYLA KESİP GİRİN VE HAVA KİLİDİNE ONAY VERİN.",
["pln_jr1_05_02"] = "LOCKE GÜVENLİK ODASINA KESEREK GİRMEMİZİ İSTİYOR. BULUN EKİP, SONRA DİZİYİ ONAYLAYIN.",
["pln_jr1_05_03"] = "MİLLET, ORALARDA GÜVENLİK ODASI ARAYIN. ARK KAYNAK MAKİNESİYLE KESİP GİRİN VE DİZİYİ ONAYLAYIN.",
["pln_jr1_06_01"] = "ÇANTALARI BİR AN ÖNCE YUKARI, LOCKE'A ULAŞTIRIN EKİP. ORALARDA BÜYÜK BİR DİKEY KUYU ARAYIN.",
["pln_jr1_06_02"] = "BOŞLUĞU BULUN, O ÇANTALARI ÇELİK HALATLA HEMEN LOCKE'A YOLLAYIN.",
["pln_jr1_06_03"] = "DUYDUNUZ. ÇANTALARI ŞAFTTAKİ ÇELİK HALATLARA TAKIN. YUKARIYA, LOCKE'A GÖNDERİN.",
["pln_jr1_07_01"] = "İŞTE O. LOCKE.",
["pln_jr1_07_02"] = "DEMEK LOCKE BU.",
["pln_jr1_07_03"] = "İŞTE ORADA. LOCKE.",
["pln_jr1_08_01"] = "LOCKE'UN KAÇIŞ PLANI RADARLARI PATLATMAYA BAĞLI MİLLET. HALLEDİVERİN.",
["pln_jr1_08_02"] = "LOCKE RADARLARI SABOTE ETMEMİZİ İSTİYOR. İŞE KOYULSAK İYİ OLUR.",
["pln_jr1_08_03"] = "SIRADAKİ İŞİMİZ O RADARLARI DEVRE DIŞI BIRAKMAK MİLLET. YAPIN.",
["pln_jr1_09_01"] = "HARİKA İŞ EKİP. LOCKE PAYIMIZI ÇOKTAN GÖNDERDİ. HÂLÂ BU ADAMDAN EMİN DEĞİLİM AMA BELKİ GÜVENEBİLİRİZ.",
["pln_jr1_09_02"] = "YOĞUNDU EKİP. LOCKE PAYIMIZI ÇOKTAN GÖNDERDİ. HÂLÂ İÇİM RAHAT DEĞİL AMA BAKALIM BU ADAMLA İŞLER NEREYE GİDECEK.",
["pln_jr1_09_03"] = "İYİ İŞ MİLLET. LOCKE PAYIMIZI AKTARDI. BU ADAMI HENÜZ ÇÖZEMEDİM AMA BAKALIM İŞLER NASIL GİDECEK.",
["pln_jr1_brf_01_01"] = "LOCKE BİZİ ÇÖLDEKİ BİR MURKY TESİSİNİ VURMAYA GÖNDERİYOR. BLACK RİDGE. ESKİDEN HAVA KUVVETLERİNE AİT BİR YERDİ. MURKYWATER SOĞUK SAVAŞ'TAN SONRA ALIP KENDİ FORT KNOX'LARINA ÇEVİRMİŞ. BURADA CİDDİ GANİMET OLDUĞUNA BAHSE GİREBİLİRSİNİZ. NE BEKLEYECEĞİMDEN EMİN DEĞİLİM. İNTERNETTE PEK BİR ŞEY YOK, İSTİHBARATIMIZ AZ. AMA BİR ŞEY KESİN: BU İŞTEN GİZLİCE GEÇEMEZSİNİZ. GÜRÜLTÜYE GÖRE GİYİNİN.",
["pln_jr2_01_01"] = "ACELE EDİN MİLLET! KARGO BÖLÜMÜNE!",
["pln_jr2_01_02"] = "HADİ, EKİP. ÇIKIN O SAKLANDIĞINIZ DELİKTEN!",
["pln_jr2_01_03"] = "LOCKE'U DUYDUNUZ EKİP, KARGO BÖLÜMÜNE!",
["pln_jr2_02_01"] = "SAVAŞARAK UÇAĞIN SONUNA GİTMENİZ, MERDİVENLERDEN ÇIKIP SONRA YİNE SAVAŞARAK BU TARAFA DÖNMENİZ GEREKECEK. KARGO KUMANDALARINA ULAŞMANIN TEK YOLU BU.",
["pln_jr2_02_02"] = "UÇAĞIN ÖNÜNE KADAR SAVAŞIN, MERDİVENLERDEN YUKARI ÇIKIN, SONRA SONUNA KADAR GERİ GİDİN. O KONTROLLERE ULAŞMANIN TEK YOLU BU.",
["pln_jr2_02_03"] = "UÇAĞIN ÖN TARAFINA GİTMENİZ LAZIM MİLLET. SONRA MERDİVENLERDEN ÇIKIP EN ARKAYA GİDİN. KUMANDALARA ULAŞMANIN TEK YOLU BU.",
["pln_jr2_03_01"] = "ACELE EDİN MİLLET. PARANIN YAKININA İNMENİZ GEREKİYOR.",
["pln_jr2_03_02"] = "EKİP, PARAŞÜTLERLE ACELE EDİN. ROTADAN ÇIKMAYIN.",
["pln_jr2_03_03"] = "MİLLET, PARAŞÜTLERİ ALIN, ÇABUK! PARADAN ÇOK UZAKLAŞMAYIN!",
["pln_jr2_04_01"] = "LOCKE İÇİN O İŞARET FİŞEĞİNİ YAKIN EKİP.",
["pln_jr2_04_02"] = "EKİP, UNUTMAYIN: LOCKE GELMEDEN ÖNCE BİR İŞARET FİŞEĞİ YAKMALISINIZ.",
["pln_jr2_04_03"] = "EKİP, UNUTMAYIN. LOCKE O İŞARET FİŞEĞİNİ YAKMANIZI İSTİYOR.",
["pln_jr2_05_01"] = "LOCKE HAVALANMADAN ÖNCE PARAYI KAYIŞLARLA SIKICA SABİTLEMENİZ GEREKİYOR.",
["pln_jr2_05_02"] = "O KAYIŞLARI İYİCE SIKIŞTIRIN. LOCKE'UN GANİMETİ ERKENDEN DÜŞÜRMESİNİ İSTEMEYİZ.",
["pln_jr2_05_03"] = "BÜTÜN KAYIŞLARIN SAĞLAM OLDUĞUNDAN EMİN OLUN. LOCKE'A PARAYI KAZARA DÜŞÜRMEK İÇİN BAHANE VERMEYİN.",
["pln_jr2_06_01"] = "NE DÜŞÜNÜYOR Kİ LAN?",
["pln_jr2_06_02"] = "AKLINDAN NE GEÇİYOR?",
["pln_jr2_06_03"] = "SİZİ BUNDAN NASIL ÇIKARACAK?",
["pln_jr2_07_01"] = "TEKNEYE BİNİN EKİP! BURADA NEREDEYSE İŞİMİZ BİTTİ!",
["pln_jr2_07_02"] = "OYALANMAYIN EKİP. HERKES TEKNEYE!",
["pln_jr2_07_03"] = "LOCKE'UN DEDİĞİNİ DUYDUNUZ MİLLET. TEKNEYE BİNİN DE ÇIKALIM BURADAN.",
["pln_jr2_brf_01_01"] = "TAMAM, PLAN ŞU. LOCKE SİZİ KAÇAK OLARAK UÇAĞA SOKACAK. İŞARETİNİ BEKLEYİN, SONRA FIRLAYIN DIŞARI. DİRENİŞ HAFİF OLMALI, SADECE MÜRETTEBAT. PARA BÜYÜK PALETLERE PAKETLENMİŞ. KARGO KAPILARINDAN DIŞARI ATIN, YERE İNİNCE TOPLARIZ. BASİT.",
["pln_jr2_intro_01_01"] = "TAMAM EKİP... LOCKE'U SİZE BAĞLIYORUM.",
["pln_jr2_intro_01_02"] = "UMARIM YUKARIDA İYİSİNİZ EKİP. İŞTE LOCKE.",
["pln_jr2_intro_01_03"] = "TAMAM MİLLET. İŞTE LOCKE... YUKARIDA DİKKATLİ OLUN.",
["pln_jwl_01_any_01"] = "TAMAM, VURKAÇ VAKTİ.",
["pln_jwl_02_any_01"] = "BURADAN EN AZ DÖRT ÇANTA MÜCEVHER İSTİYORSUNUZ. KOLAY.",
["pln_jwl_03_any_01"] = "BU DÜKKÂNDAN EN AZ İKİ ÇANTA MÜCEVHER İSTİYORUZ. ANLAŞILDI MI?",
["pln_jwl_04_any_01"] = "DÜKKÂNDAN ANLAŞTIĞIMIZ MİKTARDA MÜCEVHER ARIYORUZ... DAHA FAZLASINI İSTERSENİZ DÖNÜP ALIN.",
["pln_jwl_05_any_01"] = "AÇGÖZLÜLÜĞÜNÜZ SİZE YOL GÖSTERSİN. İSTİYORSANIZ GİDİP ALIN. ",
["pln_jwl_06_any_01"] = "BU, BİLDİĞİNİZ SIRADAN BİR KUYUMCU SOYGUNU. ÖYLE BİR ŞEY VARSA TABİİ.",
["pln_jwl_07_any_01"] = "VİTRİNLERE GİRİŞİN.",
["pln_jwl_07_any_02"] = "VİTRİNLER KIRILABİLİR.",
["pln_jwl_08_any_01"] = "ARKAYA DA BAKIN.",
["pln_jwl_08_any_02"] = "ARKA ODALARA BAKIN.",
["pln_jwl_09_any_01"] = "O ÇANTALARI ARABAYA GÖTÜRÜN.",
["pln_jwl_09_any_02"] = "ÇANTALAR ARABAYA MİLLET.",
["pln_jwl_10_any_01"] = "NEREDEYSE YETERLİ.",
["pln_jwl_10_any_02"] = "DEVAM EDİN MİLLET.",
["pln_jwl_11_any_01"] = "TAMAM, İHTİYACIMIZ OLANIN HEPSİ BU.",
["pln_jwl_11_any_02"] = "VLAD İÇİN YETERLİ AMA CESARETİNİZ VARSA DAHA FAZLASINI ALIN.",
["pln_jwl_11_any_03"] = "VLAD'A FAZLASIYLA YETER. BİZE YETİYOR MU? KARAR SİZİN.",
["pln_jwl_12_any_01"] = "HADİ, HADİ, DAHA İYİSİNİ YAPABİLİRİZ!",
["pln_jwl_12_any_02"] = "GAZLAYIN MİLLET, DAHA FAZLASI!",
["pln_knk_jwl_a_00_003_01"] = "TACI ONA GÖTÜRÜN, VAKTİNİZ VARSA İÇERİDEKİ HER ŞEYİ ALIN... BOŞA HARCAMAK İSTEMEYECEĞİNİZ BİR SÜRÜ EK GELİR VAR. AMA HAREKETE GEÇMEYE KARAR VERDİĞİNİZDE HIZLI DAVRANIN.",
["pln_knk_jwl_a_01_any_01"] = "TAMAM, İŞTE BU. ÇABUCAK GİRİP VLAD'IN TACINI ALIN. DAHA FAZLASINI İSTERSENİZ KARAR SİZİN.",
["pln_knk_jwl_a_02_any_01"] = "SAYACI BAŞLATIYORUM. BİR KASA ARAYIN. KASADA DEĞİLSE PANİK YAPMAYIN; BİNADA.",
["pln_knk_jwl_a_03_any_01"] = "YARISINA GELDİK. ACELE EDİN!",
["pln_knk_jwl_a_03_any_02"] = "YARISINA GELDİK MİLLET. ACELE EDİN!",
["pln_knk_jwl_a_04_any_01"] = "MİNİBÜSÜN GİTMESİNE BİR DAKİKA VAR.",
["pln_knk_jwl_a_04_any_02"] = "MİNİBÜSÜN GİTMESİNE BİR DAKİKA VAR. SİZİNLE YA DA SİZSİZ.",
["pln_knk_jwl_a_05_any_01"] = "MİNİBÜSÜN GİTMESİNE 30 SANİYE VAR.",
["pln_knk_jwl_a_05_any_02"] = "MİNİBÜSÜN GİTMESİNE 30 SANİYE KALDI.",
["pln_knk_jwl_a_06_any_01"] = "MİNİBÜSE ULAŞMAK İÇİN ON SANİYENİZ VAR.",
["pln_knk_jwl_a_06_any_02"] = "MİNİBÜSE ULAŞMAK İÇİN ON SANİYENİZ VAR, HEMEN GİDİN.",
["pln_knk_jwl_a_06_any_03"] = "ON SANİYE.",
["pln_knk_jwl_a_07_any_01"] = "AZ ÖNCE BİRİNİN KAÇTIĞINI GÖRDÜM. BELAYA HAZIR OLUN.",
["pln_knk_jwl_a_07_any_02"] = "BİRİ KAÇTI.",
["pln_knk_jwl_a_08_any_01"] = "İÇERİDE GÜVENLİK KAMERASI OLMA İHTİMALİ YÜKSEK. GÖZÜNÜZÜ AÇIK TUTUN.",
["pln_knk_jwl_a_09_any_01"] = "GANİMET MİNİBÜSÜ YOLDA. TAHMİNİ VARIŞ: BİR DAKİKA.",
["pln_knk_jwl_a_09_any_02"] = "ŞOFÖR KAÇIŞ MİNİBÜSÜYLE BİR DAKİKAYA ORADA OLACAK.",
["pln_knk_jwl_a_09_any_03"] = "ŞOFÖR HAREKET HÂLİNDE. TAHMİNİ VARIŞ: BİR DAKİKA.",
["pln_knk_jwl_a_10_any_01"] = "ŞOFÖR KAÇMAK ZORUNDA KALDI, ORTALIK FAZLA KIZIŞTI. YER DEĞİŞTİRİYOR.",
["pln_knk_jwl_a_10_any_02"] = "DAYANIN, SİZİ ALMAK İÇİN FAZLA POLİS VAR.",
["pln_knk_jwl_a_10_any_03"] = "BEKLEYİN, SİZİ ALMAK İÇİN ORTALIK FAZLA SICAK.",
["pln_knk_jwl_a_11_any_01"] = "TAMAM, BELKİ TAÇ YAKINLARDADIR. BİNANIN İÇİNDE OLMALI.",
["pln_knk_jwl_a_11_any_02"] = "ETRAFA BAKIN, VLAD'İN TACI İÇERİDE BİR YERDE OLMALI.",
["pln_knk_jwl_a_11_any_03"] = "TAÇ O BİNADA, EMİNİM.",
["pln_knk_jwl_a_11_any_04"] = "ORADA OLMALI, TAÇ BİR YERDE ORADA.",
["pln_knk_jwl_a_12_any_01"] = "LANET OLSUN, SİZİ DIŞARIDA KİLİTLEDİLER! ETRAFINDAN DOLAŞMANIN YOLUNU BULUN!",
["pln_knk_jwl_a_12_any_02"] = "KAPIYI KİLİTLEDİLER. KAFANIZI KULLANIN.",
["pln_knk_jwl_a_12_any_03"] = "ŞİMDİ İŞLER İLGİNÇLEŞİYOR...",
["pln_knk_jwl_a_13_any_01"] = "TAMAM, İŞTE BU. KAÇIŞ MİNİBÜSÜNE GÖTÜRÜN... VLAD MEMNUN OLACAK.",
["pln_knk_jwl_a_13_any_02"] = "İŞTE BÖYLE. ŞUNU MİNİBÜSE GÖTÜRÜN!",
["pln_knk_jwl_a_13_any_03"] = "VLAD'IN KARISI ÇOK SEVİNECEK. ŞİMDİ O ŞEYİ ORADAN ÇIKARIN.",
["pln_knk_jwl_a_13_any_04"] = "BÜYÜK İKRAMİYE! ÇIKARALIM. AMA AÇGÖZLÜLÜK YAPIP KALMAK İSTERSENİZ SİZİ YARGILAMAM.",
["pln_knk_jwl_a_13_any_05"] = "VURGUN! VLAD'IN GÜLÜMSEDİĞİNİ BURADAN DUYUYORUM.",
["pln_knk_jwl_a_14_any_01"] = "İÇERİDE İLERLEMEYE DEVAM EDİN.",
["pln_knk_jwl_a_14_any_02"] = "ORADA DEVAM EDİN.",
["pln_knk_jwl_a_14_any_03"] = "ZAMAN AKIYOR; HIZLANIN, BÜTÜN GÜN VAKTİMİZ YOK.",
["pln_knk_jwl_a_14_any_04"] = "ZAMANA KARŞI YARIŞIYORUZ, MİLLET!",
["pln_knk_jwl_a_14_any_05"] = "İÇERİDE OYALANMAYIN, BİTİRİN ŞU İŞİ!",
["pln_knk_jwl_a_15_any_01"] = "ÇOK YAVAŞSINIZ MİLLET, KAÇIŞ ARACI GİTTİ...",
["pln_knk_jwl_a_15_any_02"] = "KAÇIŞ MİNİBÜSÜ AZ ÖNCE GİTTİ. BİR TUR ATIP GERİ GELMESİNİ SÖYLERİM AMA BU SEFER HAZIR OLUN.",
["pln_knk_jwl_a_15_any_03"] = "KAÇIŞ MİNİBÜSÜNÜZ AZ ÖNCE GİTTİ...",
["pln_knk_jwl_a_15_any_04"] = "KAHRETSİN, KAÇIŞ ARACINI AZ ÖNCE KAÇIRDINIZ.",
["pln_knk_jwl_a_15_any_05"] = "KAÇIŞ ARACI AZ ÖNCE SİZSİZ GİTTİ.",
["pln_knk_jwl_a_15_any_06"] = "DAHA HIZLI OLMAK GEREK ÇOCUKLAR. KAÇIŞ ARACI GİTTİ.",
["pln_knk_jwl_a_15_any_07"] = "YETERİNCE HIZLI OLAMADIK, KAÇIŞ ARACI AZ ÖNCE GİTTİ.",
["pln_knk_jwl_a_15_any_08"] = "KAÇIŞ ARACI SİZİ ALMADAN GİTTİ. ÜZGÜNÜM MİLLET, BİR SÜRE PARMAKLIKLAR ARDINDA KALACAKSINIZ.",
["pln_knk_jwl_a_15_any_09"] = "KUSURA BAKMAYIN BEYLER, ÇOK YAVAŞTINIZ. KAÇIŞ ARACI ÖZGÜRLÜĞÜNÜZLE BİRLİKTE GİTTİ. ÇIKTIĞINIZDA BENİ BULUN.",
["pln_knk_jwl_a_16_any_01"] = "KOLYE ARIYORSUNUZ, HATIRLADINIZ MI?",
["pln_knk_jwl_a_16_any_02"] = "MİLLET, BİR TAÇ ARIYORUZ. KASADA OLABİLİR AMA İÇERİDE OLMALI.",
["pln_knk_jwl_a_16_any_03"] = "MİLLET, O TACI BULUN, ÇABUK BULUN.",
["pln_knk_jwl_a_16_any_04"] = "MİLLET, ORADA NE ARADIĞINIZI UNUTMAYIN. BİR TAÇ ARIYORUZ.",
["pln_knk_jwl_a_16_any_05"] = "MİLLET, TAÇ MUHTEMELEN BİR KASA'DA YA DA BİR YERDE SERGİLENİYOR...",
["pln_ko1_01_01"] = "İŞTE ORADA. İŞİNİZİ YAPIN MİLLET AMA GAGE SESSİZCE YAPMANIZI TERCİH EDİYOR. ANA KAPI TAM KARŞINIZDA AMA BELKİ BAŞKA YOLLAR BULABİLİRSİNİZ.",
["pln_ko1_01_02"] = "İŞTE ORADA, TAM İLERİDE. İŞİNİZİ YAPIN MİLLET AMA SESSİZCE. GÜRÜLTÜ ÇIKARSA SİZİ ÇABUCAK ÇIKARMAM GEREKECEK.",
["pln_ko1_01_03"] = "DEPO BU. NE YAPMANIZ GEREKTİĞİNİ BİLİYORSUNUZ AMA SESSİZ KALIN. ALARM ÇALARSA SİZİ ÇIKARMAM GEREKECEK.",
["pln_ko1_02_01"] = "ETRAFA BAKIN. MURKYWATER KONTEYNERLERİNİ ARAYIN. BULABİLDİĞİNİZ DEĞERLİ HER ŞEYİ ALIN.",
["pln_ko1_02_02"] = "EVE DÖNEN BİR SÜRÜ MAL VAR. SİLAHLAR, MÜHİMMAT VE ŞU KARANLIK TİPLERİN AŞIRABİLDİĞİ NE VARSA. MURKYWATER'IN KONTEYNERLERİNE BAKIN.",
["pln_ko1_02_03"] = "ORADAN ÇIKARABİLECEĞİNİZ HER ŞEY İÇİN GÖZÜNÜZÜ AÇIK TUTUN. EN İYİ SEÇENEĞİNİZ MURKYWATER KONTEYNERLERİ; AÇIN ONLARI.",
["pln_ko1_03_01"] = "UYANIK OLUN BEYLER. DEPO DAHA ZOR OLACAK AMA ÖDÜLÜ DEĞER.",
["pln_ko1_03_02"] = "DEPO BURASI. DAHA İYİ GANİMETİN BURADA OLDUĞUNA BAHSE GİRERİM.",
["pln_ko1_03_03"] = "ARTIK CANAVARIN İNİNDESİNİZ MİLLET. GANİMET DAHA İYİ AMA RİSK DE DAHA BÜYÜK.",
["pln_ko1_04_01"] = "KULLANILMIŞ DİNARLAR. İZİ ZOR SÜRÜLÜR. MÜKEMMEL.",
["pln_ko1_04_02"] = "BUNLAR DENİZAŞIRI 'MÜTTEFİKLERİMİZDEN' GELEN, KULLANILMIŞ BANKNOTLAR. ",
["pln_ko1_04_03"] = "GÜZEL BİR KULLANILMIŞ DİNAR ZULASI. İYİ BULDUNUZ.",
["pln_ko1_05_01"] = "UMARIM BU KOKAİNİ BİZİM ASKERLERE VERMİYORLARDI.",
["pln_ko1_05_02"] = "BU KOKAİN ARTIK TERÖRÜ FİNANSE ETMEYECEK. SADECE ESKİ USUL AMERİKAN SUÇUNU.",
["pln_ko1_05_03"] = "KOLOMBİYA, BOLİVYA, MEKSİKA... NEREDEN GELİRSE GELSİN ARTIK BİZİM.",
["pln_ko1_06_01"] = "LANET OLSUN, BU ALTIN BÜYÜK İHTİMALLE SADDAM'IN SARAYINDAN ÇALINMIŞ!",
["pln_ko1_06_02"] = "ALTIN KÜLÇELERİ. MUHTEMELEN ÖZGÜRLÜĞÜN DÜŞMANLARINDAN ALINMIŞ. ",
["pln_ko1_06_03"] = "KÜLÇE ALTINLARIN ÇANTALANMASINI İZLEMEKTEN HİÇ SIKILMAM.",
["pln_ko1_07_01"] = "HARİKA İŞ. İZİ SÜRÜLEMEYEN SİLAHLARA HER ZAMAN ALICI BULUNUR.",
["pln_ko1_07_02"] = "TÜFEKLER, TABANCALAR VE MERMİLER. BU, GAGE'İ MUTLU EDER.",
["pln_ko1_07_03"] = "YASA DIŞI, İZLENEMEYEN SİLAHLAR. GAGE'İN OLAYI BU.",
["pln_ko1_08_01"] = "VAY BE, BU ORİJİNAL BİR GUSTOFF!",
["pln_ko1_08_02"] = "IRAKLI BİR DİKTATÖRÜN ELİNDE ON YEDİNCİ YÜZYIL İSVEÇ BAŞYAPITLARININ NE İŞİ VAR LAN?",
["pln_ko1_08_03"] = "EN SON IRAQİ NATİONAL GALLERY'DE GÖRÜLMÜŞTÜ. BU ADAMLARDA HİÇ UTANMA YOK.",
["pln_ko1_09_01"] = "O SUNUCUDA KİM BİLİR NELER VAR. PLANLAR, KAYITLAR, BELKİ AREA 51'İN ŞİFRESİ.",
["pln_ko1_09_02"] = "O SUNUCUDA HER ŞEY OLABİLİR. BELKİ BAŞKANIN E-POSTA ADRESİ.",
["pln_ko1_09_03"] = "BU ŞAİBELİ PİSLİKLER O SUNUCUDA NE SAKLIYORMUŞ GÖRMEK İÇİN SABIRSIZLANIYORUM.",
["pln_ko1_10_01"] = "OO, PARLAK! BUNU YAĞMALAYAN KALİTELİ ŞEYLERİ SEVİYORMUŞ.",
["pln_ko1_10_02"] = "BU MÜCEVHERLER KOLAY SATILIR.",
["pln_ko1_11_01"] = "SANIRIM NATİONAL GEOGRAPHİC'TE BUNUNLA İLGİLİ BELGESEL İZLEMİŞTİM.",
["pln_ko1_11_02"] = "İNSANLAR BU ANTİK BABİL ZIMBIRTISINA SERVET ÖDER.",
["pln_ko1_11_03"] = "BUNU SATABİLECEĞİM TEK BİR YER VAR. MARRAKECH.",
["pln_ko1_12_01"] = "BAHSE GİRERİM DELİ DİKTATÖR O GÜMÜŞ TABAKLARDAN YERDİ.",
