["pln_ko1_13_02"] = "10 SANİYELİK ZAMAN KİLİDİ OLAN İKİ KART OKUYUCU MU? O KASA DAİRESİNDE CİDDİ SİLAHLAR TUTTUKLARINA BAHSE GİREBİLİRSİNİZ.",
