["pln_ko1_end_02_01"] = "PEK GÜZEL DEĞİL. BÜYÜK BİR BAŞARI DA SAYILMAZ. AMA SAĞ ÇIKTIĞINIZ HER GÜN KAZANÇTIR. ",
