["pln_ko1b_05_01"] = "SIRADAKİ ADIM, KASA DAİRESİ'Nİ AÇMAK. DEPODA LEVYE BULUP ARKADAKİ SOĞUTMA FANLARINA SIKIŞTIRIN. İÇERİDE SICAKLIK YÜKSELECEK, ACİL DURUM SİSTEMİ DEVREYE GİRECEK.",
["pln_ko1b_05_02"] = "BU KASA DAİRELERİNİN BİR ZAYIFLIĞI VAR. İÇERİSİ ÇOK ISINIRSA GÜVENLİK SİSTEMİ KAPIYI AÇIYOR. DEPODA LEVYE ARAYIN, ARKADAKİ FANLARA SIKIŞTIRIN.",
["pln_ko1b_05_03"] = "BU KASA DAİRESİ'NİN ZAYIF NOKTASI VAR. SICAKLIK KONTROLLÜ. ARKADAKİ HAVALANDIRMA FANLARINA LEVYE SIKIŞTIRIN. SICAKLIK YÜKSELİR, ACİL DURUM SİSTEMİ KAPIYI AÇAR. KOLAY. ",
["pln_ko1b_06_01"] = "UNUTMAYIN, LEVYE BULUP KASA DAİRESİ'NİN FANLARINA SIKIŞTIRMALISINIZ. BÜYÜK İHTİMALLE DEPONUN İÇİNDEDİRLER.",
["pln_ko1b_06_02"] = "DEPODA LEVYE ARAYIN. KASA DAİRESİNİN FANLARINA SOKUN, GERİSİNİ TERMODİNAMİĞE BIRAKIN.",
["pln_ko1b_06_03"] = "LEVYE BULMANIZ GEREKİYOR. BÜYÜK İHTİMALLE DEPODALAR. KASA DAİRESİNİN FANLARINA SIKIŞTIRIN. İÇERİDE SICAKLIK YÜKSELİR VE... İŞTE OLDU!",
["pln_ko1b_07_01"] = "LEVYELERİN DEPONUN İÇİNDE OLDUĞUNU TAHMİN EDİYORUM.",
["pln_ko1b_07_02"] = "LEVYE BULMANIZIN EN OLASI YERİ DEPO.",
["pln_ko1b_07_03"] = "LEVYELER MUHTEMELEN DEPONUN İÇİNDEDİR. BAKIN.",
["pln_ko1b_08_01"] = "TAMAM. İLKİ TAMAM. ISI ARTIYOR. DAHA FAZLA FANI DURDURMAK İŞİ HIZLANDIRIR.",
["pln_ko1b_08_02"] = "TAMAM, HARİKA. SICAKLIK ARTIYOR. BEKLEYİN AMA DAHA FAZLA FAN SIKIŞTIRMAK İŞİ HIZLANDIRIR.",
["pln_ko1b_08_03"] = "İLK FAN TAMAM. SICAKLIK YÜKSELİYOR. HIZLANDIRMAK İÇİN DAHA FAZLA FANI SIKIŞTIRIN.",
["pln_ko1b_09_01"] = "GÜZEL. ISINIYOR. İÇERİDE NE VAR LAN?",
["pln_ko1b_09_02"] = "GÜZEL. SICAKLIK DAHA HIZLI ARTIYOR. İÇERİDE SICAK BİR ŞEY OLMALI.",
["pln_ko1b_09_03"] = "HARİKA. SICAKLIĞIN ARTIŞINA BAKIN. VAY BE, İÇERİDE CEHENNEMDEN SICAK BİR ŞEY OLMALI.",
["pln_ko1b_10_01"] = "FANLAR TAMAM. SICAKLIK HIZLA YÜKSELİYOR. İÇERİDE NE VAR LAN?",
["pln_ko1b_10_02"] = "SON FAN DA TAMAM. ŞU SICAKLIĞIN YÜKSELİŞİNE BAKIN. HİÇ İYİ HİSSETMİYORUM.",
["pln_ko1b_10_03"] = "SON FAN DEVRE DIŞI. SICAKLIK FIRLADI. İÇİNDEKİLER KAVRULUYORDUR!",
["pln_ko1b_11_01"] = "KASA DAİRESİNİN KAPISI AÇILDI. GİRİP GANİMETİ ALIN!",
["pln_ko1b_11_02"] = "KAPI BU. ŞİMDİ MALLARI ALIN.",
["pln_ko1b_11_03"] = "KASA DAİRESİ AÇILDI. İÇİNDE NE VARSA ALIN, EKİP!",
["pln_ko1b_12_01"] = "BU... NÜKLEER SAVAŞ BAŞLIĞI MI!? BEN... ŞEY... BAKIN, ALIN İŞTE. DİKKATLİCE!",
["pln_ko1b_12_02"] = "OLAMAZ... LANET BİR NÜKLEER BOMBA MI!? VLAD!",
["pln_ko1b_12_03"] = "BEN... ŞEY... TAMAM. DEMEK NÜKLEER SAVAŞ BAŞLIĞI ÇALIYORUZ. MİLLET, ONLARA ÇOK AMA ÇOK NAZİK DAVRANIN.",
["pln_ko1b_13_01"] = "VLAD, DELİRDİN Mİ! NÜKLEER BOMBALAR MI!?",
["pln_ko1b_13_02"] = "VLAD, ALIŞVERİŞ MERKEZİNİ DAĞITMAK BAŞKA. TAÇ ÇALMAK BAŞKA. AMA NÜKLEER BOMBA MI!?",
["pln_ko1b_13_03"] = "DELİRDİN Mİ VLAD? BUNLAR FAAL NÜKLEER BOMBALAR!",
["pln_ko1b_14_01"] = "O SAVAŞ BAŞLIKLARI ÇOK AĞIR. TAŞIMAK İÇİN FORKLİFTLERİ KULLANIN.",
["pln_ko1b_14_02"] = "O FORKLİFTLER SAVAŞ BAŞLIKLARINI TAŞIMAYA YARAR.",
["pln_ko1b_14_03"] = "LANET OLSUN, O SAVAŞ BAŞLIKLARI AĞIR. BELKİ FORKLİFTLERİ KULLANABİLİRSİNİZ.",
["pln_ko1b_15_01"] = "O TREN BİRAZ UZAKTA. NÜKLEER BAŞLIKLARI UZUN SÜRE TAŞIMANIZI İSTEMİYORUM. BİR ARABA BULMAYA ÇALIŞIN.",
["pln_ko1b_15_02"] = "TRENE ÇABUK ULAŞMANIN BİR YOLUNU ARAYIN. O ESKİ RUS NÜKLEER BOMBALARINI GEREKENDEN UZUN SÜRE ELİNİZDE TUTMANIZI İSTEMİYORUM.",
["pln_ko1b_15_03"] = "ETRAFTA ARABA VAR MI, BAKIN. O ŞAİBELİ RUS NÜKLEER BOMBALARINI VLAD'IN TRENİNE NE KADAR ÇABUK GÖTÜRÜRSENİZ O KADAR İYİ!",
["pln_ko1b_16_01"] = "İŞTE BÖYLE. ARTIK DEFOLUP GİDEBİLİR YA DA DÖNÜP DAHA ÇOK MURKY GANİMETİ KAPABİLİRSİNİZ.",
["pln_ko1b_16_02"] = "İŞİMİZ BİTTİ. ŞU ÇILGIN IVAN'I NÜKLEERLERİYLE BIRAKABİLİR YA DA DÖNÜP DAHA FAZLA GANİMET ALABİLİRSİNİZ.",
["pln_ko1b_16_03"] = "SONUNCU DA TAMAM. ŞİMDİ UZAKLAŞABİLİR YA DA DAHA FAZLA GANİMET İÇİN DEPOYA DÖNEBİLİRSİNİZ.",
["pln_ko1b_17_01"] = "SAMURAY ZIRHINI BURADA ÇALMIŞTINIZ. HATIRLADINIZ MI?",
["pln_ko1b_17_02"] = "SAMURAY ZIRHINI BURADAN ÇIKARDIĞIMIZ ZAMANI HATIRLIYOR MUSUNUZ? AHHH, GÜZEL GÜNLER!",
["pln_ko1b_17_03"] = "SESSİZ YAPTIĞIMIZDA ZIRHI BURADAN ALMIŞTIK, HATIRLADINIZ MI?",
["pln_ko1b_18_01"] = "İŞTE BÖYLE. ŞİMDİ DEFOLUP GİDİN ORADAN!",
["pln_ko1b_18_02"] = "İŞİMİZ BİTTİ. ŞİMDİ KAÇIN! VLAD'I NÜKLEER BOMBALARIYLA BIRAKIN.",
["pln_ko1b_18_03"] = "SONUNCU BU. TAVSİYEM Mİ? OLABİLDİĞİNCE HIZLI UZAKLAŞIN!",
["pln_ko1b_brf_01_01"] = "\"VLAD İÇİN MURKYWATER DEPOSUNU VURUYORUZ. HEDEFİN NE OLDUĞUNU, NEREDE OLDUĞUNU BİLMİYORUM AMA KENDİ ŞİRKET İŞARETLİ NAKLİYE KONTEYNERLERİNDEN BİRİNDEKİ KASA DAİRESİNDE SAKLI. İÇERİ GİRİN, KASA DAİRESİNİ BULUN, ÇILGIN RUS HER NE İSTİYORSA ÇIKARIN. MURKY'LER VARDIĞINIZDA YÜKSEK ALARMDA OLACAK, POLİS DE ÇABUK MÜDAHALE EDECEK. İÇERİ GİRİP İŞİ HIZLI YAPMALISINIZ. HIZ DEMEK GÜRÜLTÜ DEMEK. BUNDA PARMAK UCUNDA YÜRÜMEK YOK. DAHA BAŞTAN EMNİYETLER AÇIK. UNUTMAYIN, ETRAFTA GANİMET DOLU. NE KAPABİLİYORSUNUZ BAKIN.\"",
["pln_ko1b_brf_02_01"] = "BÜYÜK PLAN YOK. DALIN, ALABİLDİĞİNİZ KADAR MAL ALIP ÇIKARIN. MURKY'LERE ZARAR VERMENİN ÖZEL YOLLARI VARSA DA SİZİ SUÇLAYAMAM.",
["pln_ko1b_intro_01_01"] = "ESKİ GÜNLER GİBİ, HA?",
["pln_ko1b_intro_01_02"] = "BURAYLA İLGİLİ SABAH 4 ANILARIM VAR...",
["pln_ko1b_intro_01_03"] = "HAREKETLİLİK ÇOK. SOĞUKKANLI OLUN.",
["pln_mad_01_01"] = "RUSYA'YA HOŞ GELDİNİZ MİLLET! GÜZEL KARŞILAMA EKİBİ, DEĞİL Mİ? ",
["pln_mad_01_02"] = "İŞTE RUSYA EKİP! BU ADAMLAR ŞAKA YAPMIYOR!",
["pln_mad_01_03"] = "VAY... KIL PAYIYDI! BU RUSLAR GERÇEKTEN PARTİLERİNİN BASILMASINI İSTEMİYOR.",
["pln_mad_02_01"] = "O HAVA SAVUNMALARI ÇALIŞTIĞI SÜRECE FEDOR, EMP'Yİ BIRAKAMAZ. DEVRE DIŞI BIRAKMANIN BİR YOLUNU BULUN EKİP.",
["pln_mad_02_02"] = "UÇAKSAVAR SAVUNMASINI DEVRE DIŞI BIRAKMANIZ YA DA YOK ETMENİZ GEREK. YOLUNU BULUN, YOKSA SIÇTIK.",
["pln_mad_02_03"] = "EKİP, O UÇAKSAVARLARI BİR AN ÖNCE HALLETMELİSİNİZ. BİR YOL BULUN!",
["pln_mad_03_01"] = "EKİP, ŞURADAKİ BİLGİSAYAR İSTASYONU İŞE YARAYABİLİR. BANA DİZÜSTÜ BİLGİSAYAR FALAN BULMAYA ÇALIŞIN.",
["pln_mad_03_02"] = "O BİLGİSAYAR İSTASYONUNDA BİR DİZÜSTÜ BİLGİSAYAR OLMALI. BULABİLİR MİSİNİZ, BAKIN.",
["pln_mad_03_03"] = "BİLGİSAYAR İSTASYONUNDA DİZÜSTÜ BULURSANIZ ONUNLA SİZE YARDIM EDEBİLİRİM.",
["pln_mad_04_01"] = "DİZÜSTÜ BİLGİSAYARI UÇAKSAVARA BAĞLAYIN!",
["pln_mad_04_02"] = "DİZÜSTÜ BİLGİSAYARI UÇAKSAVARA BAĞLAYIN. BELKİ MARİFETİMİ GÖSTEREBİLİRİM.",
