["pln_mad_12_02"] = "LANET OLSUN BILE... EMP ÇATIDAN DÜŞTÜ, ARTIK KERESTE FABRİKASININ DIŞINDA DEĞİL, İÇİNDE.",
["pln_mad_12_03"] = "GERÇEKTEN Mİ BILE? EKİP, EMP KERESTE FABRİKASININ DIŞINA DEĞİL İÇİNE DÜŞTÜ. ŞİMDİ İÇERİ GİRMEMİZ GEREK.",
["pln_mad_13_01"] = "GÜZEL BIRAKTIN BILE! EKİP, EMP KERESTE FABRİKASININ DIŞINDAKİ ALANDA.",
