["pln_mad_13_03"] = "EMP BIRAKILDI. KERESTE FABRİKASININ HEMEN DIŞINA GİDİP ALIN.",
["pln_mad_14_01"] = "TAMAM EKİP. KERESTE FABRİKASINA GİRMENİN BİR YOLUNU BULMALIYIZ. DELİLİK OLABİLİR AMA AZ ÖNCE HACKLEDİĞİMİZ UÇAKSAVARI KULLANSAK? YÖNÜNÜ DEĞİŞTİRİP DUVARI HAVAYA UÇURSAK?",
["pln_mad_14_02"] = "KERESTE FABRİKASINA GİRMENİN YOLUNU BULMAMIZ GEREKECEK. ELE GEÇİRDİĞİMİZ UÇAKSAVAR TOPUYLA DUVARDA DELİK AÇABİLİR MİYİZ?",
["pln_mad_14_03"] = "KERESTE FABRİKASINA GİRMELİYİZ. AZ ÖNCE HACKLEDİĞİMİZ UÇAKSAVARI KULLANIP YÖNÜNÜ DEĞİŞTİRMEYİ DENESENİZ? DENEMEYE DEĞER.",
["pln_mad_15_01"] = "İŞTE BU! ÇILGINCAYDI EKİP! ŞİMDİ İÇERİ GİRİN.",
["pln_mad_15_02"] = "İŞTE BİZ BÖYLE YAPARIZ! İYİ İŞ MİLLET. ŞİMDİ DEĞİRMENE GİRİN.",
["pln_mad_15_03"] = "KENDİ OYUNCAKLARINI ONLARA KARŞI KULLANMAK... BAYILDIM. ŞİMDİ KERESTE FABRİKASINA GİRİN.",
["pln_mad_16_01"] = "TAMAM MİLLET. KULLANABİLMEK İÇİN ÖNCE ŞU GÜZELLİĞİ ŞARJ ETMEMİZ LAZIM. BİRAZ SÜRECEK.",
