["pln_mad_18_02"] = "ŞARJ KESİLDİ! YENİDEN BAŞLATIN!",
["pln_mad_18_03"] = "LANET OLSUN, PARALI ASKERLER EMP'YE ULAŞIP ŞARJI DURDURDU.",
