["pln_mad_19_02"] = "SİKTİR, PARALI ASKERLER EMP'NİN DOLMASINI DURDURDU! YÜKÜ BOŞALMAYA BAŞLIYOR!",
["pln_mad_19_03"] = "MİLLET! PARALI ASKERLER EMP'YLE HER OYNADIĞINDA DOLUM AZALIYOR! DOKUNMALARINA İZİN VERMEYİN!",
["pln_mad_20_01"] = "TAMAM, GÜZEL. ŞARJ YENİDEN BAŞLADI.",
["pln_mad_20_02"] = "GÜZEL, EMP YENİDEN ŞARJ OLUYOR.",
["pln_mad_20_03"] = "EMP YENİDEN ŞARJ OLUYOR.",
["pln_mad_21_01"] = "MİLLET, DİNLEYİN! EMP PATLAYINCA BÜYÜK İHTİMALLE BİR SÜRE SİZİNLE İLETİŞİM KURAMAYACAĞIM. KAPAKTAN GİZLİ LABORATUVARA İNMELİSİNİZ.",
["pln_mad_21_01a"] = "EMP MANYETİK KİLİDİ AÇMIŞ OLMALI. AŞAĞI İNİNCE TARAYICIYI VE DENEKLERİ BULUN.",
["pln_mad_21_02"] = "MİLLET, EMP PATLAYINCA MUHTEMELEN HABERLEŞMEMİZİ DE KESECEK. AMA NE YAPACAĞINIZI BİLİYORSUNUZ. KAPAKTAN LABORATUVARA GİRİP DENEKLERİ ARAYIN.",
["pln_mad_21_03"] = "EMP NEREDEYSE HAZIR, İYİ DİNLEYİN! BU BEBEK GÜÇLÜ. BAŞKA ŞEYLERİN YANINDA İLETİŞİMİMİZİ DE KESERSE ŞAŞIRMAYIN.",
["pln_mad_21_03a"] = "AMA PLANA BAĞLI KALIRSAK SORUN ÇIKMAZ. KAPAKTAN LABORATUVARA GİRİN, TARAYICIYI VE DENEKLERİ BULUN.",
["pln_mad_22_01"] = "EKİP? BENİ DUYUYOR MUSUNUZ BİLMİYORUM AMA NE YAPACAĞINIZI BİLİYORSUNUZ: KAPAKTAN LABORATUVARA GİRİN.",
["pln_mad_22_02"] = "EMP MANYETİK KİLİDİ HALLETTİ. LABORATUVARA GİDEN YOLUNUZ AÇIK. GİDELİM!",
["pln_mad_22_03"] = "İŞTE BU! EMP İŞİNİ YAPTI! ŞİMDİ KAPAKTAN LABORATUVARA GİRİN.",
["pln_mad_22_04"] = "MİLLET, BENİ DUYUYOR MUSUNUZ? ALO? LABORATUVARA KAPAKTAN GİRİN. AÇIK OLMASI LAZIM.",
["pln_mad_23_01"] = "DOSTUM, EMP BÜTÜN FABRİKAYI KAPATTI GİBİ... EL FENERLERİNİZİ KULLANIP RÖNTGEN CİHAZINI BULUN.",
["pln_mad_23_02"] = "ELEPHANT'IN İSTEDİĞİ VERİLERİ ALMAK İÇİN BİR RÖNTGEN CİHAZI GEREKECEK.",
["pln_mad_23_03"] = "VERİLERİ ALMAK İÇİN GEREKEN RÖNTGEN CİHAZINI BULMAYA ÇALIŞIN. ONSUZ PEK BİR ŞEY YAPAMAYIZ.",
["pln_mad_24_01"] = "LANET! LABORATUVARA GİRDİĞİMİZ ANDA ODAYI GAZLA DOLDURMUŞ OLMALILAR. GAZIN NEREDEN VERİLDİĞİNİ BULUP KAPATIN!",
["pln_mad_24_02"] = "NE OLUYOR LAN! BÜTÜN ODA GAZLA DOLDU. ÇABUK! NEREDEN GELDİĞİNİ BULUP KAPATMANIN YOLUNU BULUN!",
["pln_mad_24_03"] = "KAHRETSİN! PİÇLER BİZİ DURDURMAK İÇİN ODAYI GAZLA DOLDURDU. EKİP, ÇABUK OLUN, KAPATMANIN YOLUNU BULUN!",
["pln_mad_25_01"] = "GAZI KAPATMANIN BİR YOLUNU BULMALISINIZ.",
["pln_mad_25_02"] = "MİLLET, GAZI KAPATMANIN YOLUNU ARAYIN!",
["pln_mad_25_03"] = "GAZI KAPATMANIN BİR YOLU OLMALI!",
["pln_mad_26_01"] = "İYİ İŞ MİLLET. BU, TARAMA ODASINDAKİ GAZI TEMİZLER.",
["pln_mad_26_02"] = "İŞTE BU EKİP. TARAMA ODASINDAKİ GAZ SORUNU ÇÖZÜLMÜŞ OLMALI.",
["pln_mad_26_03"] = "GÜZEL, BU GAZI GİDERİR. BÜYÜK İHTİMALLE ARTIK ODAYA GİREBİLİRSİNİZ.",
["pln_mad_27_01"] = "TAMAM, BURADAKİ BİLİM İNSANLARI BAYAĞI İLERİ TEKNOLOJİ KULLANIYOR. EL İZİ ONAYI İÇİN BAŞ BİLİM İNSANI GEREKECEK. NEREYE SAKLANDIĞINA BAKIN.",
["pln_mad_27_02"] = "LANET OLSUN! MATKAPLA DELİNEBİLEN GELENEKSEL GÜVENLİK KAPISININ NESİ VAR? EL İZİ YETKİLENDİRMESİ İÇİN BAŞ BİLİM İNSANININ KENDİSİ GEREKECEK GİBİ. BULUN ONU.",
["pln_mad_27_03"] = "AA, BİLİMKURGU FİLMİNDE OLDUĞUMUZU BİLMİYORDUM. NEYSE, TAMAM. BİR TÜR EL İZİ ONAYI İÇİN BAŞ BİLİM İNSANINI BULMALISINIZ. NEREYE SAKLANDIĞINA BAKIN.",
["pln_mad_28_01"] = "EKİP, BAŞ BİLİM İNSANINI BULMALISINIZ.",
["pln_mad_28_02"] = "HEY, BAŞ BİLİM İNSANINI BULMAZSANIZ O KAPIDAN GEÇEMEZSİNİZ.",
["pln_mad_28_03"] = "BAŞ BİLİM İNSANINI BULUP GÜVENLİK KAPISINA GÖTÜRÜN.",
["pln_mad_29_01"] = "BEKLE, NE? BAŞ BİLİM İNSANI ÖLDÜ MÜ? O KAPIYI GEÇMEMİZİN TEK YOLU ONUN ELİ... SANIRIM ELLERİNİZİ BİRAZ KİRLETMENİZ GEREKECEK...",
["pln_mad_29_02"] = "KAHRETSİN! BAŞ BİLİM İNSANINI MI ÖLDÜRDÜLER? BİLMİYORUM MİLLET. YETKİLENDİRME İÇİN HÂLÂ ELİ LAZIM... NE GEREKİYORSA YAPIN...",
["pln_mad_29_03"] = "BAŞ BİLİM İNSANI ÖLDÜ MÜ? SİKTİR. ONSUZ GÜVENLİĞİ GEÇEMEYİZ... ASLINDA TEKNİK OLARAK ONA DEĞİL, ELİNE İHTİYACIMIZ VAR...",
["pln_mad_30_01"] = "TANRIM, İĞRENÇ. EH, GEREKENİ ALDINIZ. TARAYICIYA KOYUN HERHÂLDE?",
["pln_mad_30_02"] = "VAY BE, GERÇEKTEN YAPTINIZ... SİZDE DE HİÇ ACIMA YOK. TARAYICIYA GETİRİN DE BU HİÇ YAŞANMAMIŞ GİBİ YAPALIM.",
["pln_mad_30_03"] = "ELİNİ Mİ KESTİNİZ? KARANLIK İŞLER BUNLAR AMA İŞ İŞTİR. TARAYICIYA KOYUP KAPIYI AÇIN.",
["pln_mad_31_01"] = "EVET, İŞE YARADI. BİLİM İNSANININ ÖLÜ OLMASI FARK ETMİYOR GİBİ. TEKNOLOJİ ACIMASIZ. NEYSE, TARAYICIYI BAŞLATIN.",
["pln_mad_31_02"] = "İŞE YARAMIŞ GİBİ. ARTIK TARAMA İŞLEMİNİ BAŞLATABİLİRSİNİZ.",
["pln_mad_31_03"] = "TAMAM, YETKİLENDİRME İŞE YARADI. ŞİMDİ TARAYICIYI ÇALIŞTIRIN.",
["pln_mad_32_01"] = "ELEKTRİK GERİ GELDİ GALİBA MİLLET. ",
["pln_mad_32_02"] = "GÜZEL, ELEKTRİK GERİ GELMİŞ GİBİ. ",
["pln_mad_32_03"] = "ELEKTRİK GERİ GELİYOR GİBİ.",
["pln_mad_33_01"] = "TAMAM MİLLET. DENEKLERİ ARAYIP TARAYICIYA GÖTÜRMELİSİNİZ. AŞAĞI YUKARI AYNI GÖRÜNÜYOR OLMALARI LAZIM.",
["pln_mad_33_02"] = "İSTİHBARAT DOĞRUYSA TARAMANIZ GEREKEN DENEKLER BİRBİRİNİN AYNISI.",
["pln_mad_33_03"] = "TAMAM. ŞİMDİ DENEKLERİ BULUP TARAYICIYA GÖTÜRÜN. KEL ADAMLAR ARIYORSUNUZ.",
["pln_mad_34_01"] = "JIMMY'NİN SÖZÜNÜ ETTİĞİ DENEKLERDEN BİRİ OLMALI. İHTİYACIMIZ OLAN BİLGİYİ ALMAK İÇİN CESEDİ TARAYICIYA GÖTÜRÜN.",
["pln_mad_34_02"] = "TAMAM, DENEKLERDEN BİRİ OLMALI. GEREKEN BİLGİYİ ALMAK İÇİN CESEDİ TARAYICIYA GÖTÜRÜN.",
["pln_mad_34_03"] = "O CESEDİ TARAYICIYA GÖTÜRÜN.",
["pln_mad_35_01"] = "TAMAM, TARAMAYA BAŞLAMAK İÇİN HER ŞEY HAZIR.",
["pln_mad_35_02"] = "CESET YERİNDE, TARAMAYI BAŞLATIN EKİP.",
["pln_mad_35_03"] = "İŞTE BU. ŞİMDİ TARAMAYA BAŞLAYABİLİRİZ.",
["pln_mad_36_01"] = "TAMAM, TARAMA SÜRÜYOR. ŞİMDİ KESİLMEDEN TAMAMLANDIĞINDAN EMİN OLUN.",
["pln_mad_36_02"] = "PARALI ASKERLERİN TARAMA İŞLEMİNİ DURDURMASINA İZİN VERMEYİN!",
["pln_mad_36_03"] = "RÖNTGEN CİHAZINI KORUYUN! PARALI ASKERLERİ YAKLAŞTIRMAYIN!",
["pln_mad_37_01"] = "TARAMAYI DURDURDULAR! YENİDEN BAŞLATIN!",
["pln_mad_37_02"] = "LANET OLSUN, TARAMAYI KESTİLER! YENİDEN BAŞLATIN!",
["pln_mad_37_03"] = "MİLLET, PİÇLER TARAMAYI DURDURDU! TEKRAR ÇALIŞTIRIN!",
["pln_mad_38_01"] = "HARİKA, TARAMA TEKRAR ÇALIŞIYOR.",
["pln_mad_38_02"] = "GÜZEL, TARAMA YENİDEN BAŞLADI.",
["pln_mad_38_03"] = "TARAMA YENİDEN SÜRÜYOR. ŞİMDİ DEVAM ETMESİNİ SAĞLAYIN.",
["pln_mad_39_01"] = "İŞTE BU! TARAMA TAMAMLANDI. AFERİN MİLLET.",
["pln_mad_39_02"] = "HARİKA İŞ EKİP. TARAMA TAMAMLANDI.",
["pln_mad_39_03"] = "TARAMA TAMAMLANDI. İYİ İŞ EKİP.",
["pln_mad_40_01"] = "ELEKTRİĞİ KESTİLER!",
["pln_mad_40_02"] = "ARGH, TARAYICININ ELEKTRİĞİNİ KESTİLER!",
["pln_mad_40_03"] = "KAHRETSİN, TARAYICININ ELEKTRİĞİNİ KESTİLER!",
["pln_mad_41_01"] = "HARİKA! ELEKTRİK GELDİ. TARAYICIYI YENİDEN ÇALIŞTIRIN.",
["pln_mad_41_02"] = "TAMAM, GÜZEL. ELEKTRİĞİ AÇTINIZ. TARAMA İŞLEMİNE DÖNÜN.",
["pln_mad_41_03"] = "ELEKTRİK GELDİ! DENEKLERİ TARAMAYA DÖNÜN.",
["pln_mad_42_01"] = "TAMAM, VERİLER DİĞER ODADAKİ SUNUCUYA AKTARILIYOR. GİDİP ALABİLİR YA DA KALIP DAHA FAZLA CESET TARAYABİLİRSİNİZ. EMİNİM JIMMY BİR İŞE YARAR BULUR; BU DA BİZE DAHA FAZLA PARA DEMEK.",
["pln_mad_42_02"] = "TARAMA VERİLERİ DİĞER ODADAKİ SUNUCUDA TOPLANIYOR. KALIP DAHA FAZLA VERİ TOPLAYABİLİRSİNİZ YA DA GİDEBİLİRSİNİZ. AMA EMİNİM JIMMY ZAHMETİMİZİN KARŞILIĞINI VERİR.",
["pln_mad_42_03"] = "VERİLER DİĞER ODADAKİ SUNUCUDA SAKLANIYOR. ALIP BURADAN DEFOLABİLİRSİNİZ YA DA KALIP DAHA FAZLA CESET TARAYABİLİRSİNİZ. JIMMY'NİN KARŞILIĞINI VERECEĞİNDEN EMİNİM.",
["pln_mad_43_01"] = "İYİ SEÇİM EKİP. SONUÇTA MESELE PARA. İŞİ BİLİYORSUNUZ, DAHA FAZLA VERİ İÇİN O CESETLERİ TARAMAYA DEVAM EDİN.",
["pln_mad_43_02"] = "DOĞRU SEÇİM, MİLLET. TARAMAYA DEVAM EDİN. RUSYA'YA KADAR KÜÇÜK BİR ÖDEME İÇİN GELMEDİK, DEĞİL Mİ?",
["pln_mad_43_03"] = "MÜKEMMEL KARAR MİLLET. BÜTÜN CESETLERİ TARARSANIZ JIMMY İYİ PARA ÖDEYECEK. PARA ONUN İÇİN SORUN DEĞİL GİBİ.",
["pln_mad_44_01"] = "HEPSİ TAMAM! TARANACAK CESET KALMADI. ŞİMDİ SUNUCUYU ALMALIYIZ, YOKSA HEPSİNİ BOŞUNA YAPTIK.",
["pln_mad_44_02"] = "MÜKEMMEL EKİP. BÜTÜN CESETLER TARANDI. ŞİMDİ VERİLERİ SAKLAYAN O SUNUCUYU ELE GEÇİRMELİYİZ.",
["pln_mad_44_03"] = "ALABİLDİĞİMİZ BÜTÜN VERİLERİ ALIRSAK JIMMY BAYILACAK. AKAN'A FENA KOYMUŞ OLURUZ.",
["pln_mad_45_01"] = "HARİKA İŞ, MİLLET! O SUNUCU ŞU AN ÇOK PARA EDİYOR. DÜŞÜRMEYİN.",
["pln_mad_45_02"] = "İŞTE BU! ŞİMDİ ORADAN SAĞ ÇIKMAYA BAKIN.",
["pln_mad_45_03"] = "MÜKEMMEL, SUNUCU GÜVENE ALINDI. ŞİMDİ ÇIKALIM BURADAN.",
["pln_mad_46_01"] = "BEKLEYİN! EVRAK ÇANTASINI UNUTTUM... LABORATUVARDA BİR YERDE OLMALI. GİTMEDEN ÖNCE ALMALISINIZ. İÇİNDE NE OLDUĞUNA BAKMAYIN, SADECE ALIN.",
["pln_mad_46_02"] = "LANET! EVRAK ÇANTASINI UNUTMUŞUM. EKİP, DİNLEYİN. LABORATUVARDA BİR YERDE BİR EVRAK ÇANTASI VAR.",
["pln_mad_46_02a"] = "ONU BULUP YANINIZDA GETİRMENİZ GEREK. ÖNEMLİ OLMASA İSTEMEZDİM.",
["pln_mad_46_03"] = "DOĞRU YA! AZ KALSIN UNUTUYORDUM: LABORATUVARDA BİR EVRAK ÇANTASI VAR. ONU ALMANIZ GEREKECEK, MİLLET. ÖNEMLİ.",
["pln_mad_47_01"] = "ALDINIZ MI? EVRAK ÇANTASINI? GÜZEL! ŞİMDİ ÇIKALIM ORADAN.",
["pln_mad_47_02"] = "EVRAK ÇANTASINI ALDINIZ MI? MÜKEMMEL! O ZAMAN GİTME VAKTİ!",
["pln_mad_47_03"] = "BU MU? EVRAK ÇANTASI? MÜKEMMEL! ARTIK ÇIKABİLİRİZ!",
["pln_mad_48_01"] = "NE, AKIL MI OKUYORSUNUZ? EVET, O EVRAK ÇANTASINI İSTİYORUM. NEREDEN BİLDİNİZ?",
["pln_mad_48_02"] = "HAHA, AKLIMI OKUDUNUZ MİLLET. O EVRAK ÇANTASINI GERÇEKTEN İSTİYORUM.",
["pln_mad_48_03"] = "O EVRAK ÇANTASINI İSTEDİĞİMİ NASIL BİLDİNİZ? NEYSE, AFERİN!",
["pln_mad_49_01"] = "MİLLET, FEDOR GÖLDE BEKLİYOR. GİTME VAKTİ.",
["pln_mad_49_02"] = "FEDOR'U DUYDUNUZ. KIÇINIZI GÖLE GÖTÜRÜN.",
["pln_mad_49_03"] = "ALMAYA GELDİĞİMİZ HER ŞEYİ ALDIK. ŞİMDİ GÖLE GİDİN. FEDOR SİZİ BEKLİYOR.",
["pln_mad_50_01"] = "MÜKEMMEL MİLLET. İYİ BİR ŞEY YAPTIĞIMIZI BİLMEK GERÇEKTEN GÜZEL. AMA FİKİR EDİNMEYİN, SIRADA BANKA FALAN SOYACAĞIZ.",
["pln_mad_50_02"] = "AFERİN MİLLET. SUNUCU GÜVENE ALINDI, JIMMY MEMNUN OLACAK.",
["pln_mad_50_03"] = "HARİKA, SUNUCU GÜVENE ALINDI. ARTIK JIMMY BU KONUDA ÇENESİNİ KAPATABİLİR. BİZ PAYIMIZA DÜŞENİ YAPTIK.",
["pln_mad_51_01"] = "BURADA YAPACAK BAŞKA BİR ŞEY YOK. GİDELİM.",
["pln_mad_51_02"] = "NEYİ BEKLİYORSUNUZ? HADİ GİDELİM.",
["pln_mad_51_03"] = "İŞİMİZ BİTTİ EKİP. GİTME VAKTİ.",
["pln_mad_52_01"] = "TAMAM, UÇAKSAVARI KONTROL EDEN RADAR BU. YERLE BİR EDİN. ",
["pln_mad_52_02"] = "O RADAR UÇAKSAVARI KONTROL EDİYOR. PATLATMAK GEREKİYOR.",
["pln_mad_52_03"] = "O RADAR UÇAKSAVARI KONTROL EDİYOR GİBİ. PATLATMALISINIZ.",
["pln_mad_53_01"] = "BILE SİZE BİRAZ PATLAYICI BIRAKABİLDİ. İNDİĞİNİZ YERİN YAKININDA OLMALI, ALIN.",
["pln_mad_53_02"] = "BILE İNİŞ NOKTANIZIN YAKININA BİRAZ PATLAYICI BIRAKTI. BULUN.",
["pln_mad_53_03"] = "MİLLET, İNDİĞİNİZ YERİ ARAYIN. BILE SİZE PATLAYICI BIRAKTI.",
["pln_mad_54_01"] = "MÜKEMMEL, PATLAYICILAR ELİNİZDE. ŞİMDİ RADARA YERLEŞTİRİN.",
["pln_mad_54_02"] = "GÜZEL, PATLAYICILARI BULDUNUZ. RADARA GİDİP HAVAYA UÇURUN.",
["pln_mad_54_03"] = "PATLAYICILARI ALDINIZ MI? HARİKA. RADARA GİDİP YERLEŞTİRİN DE PATLATALIM.",
["pln_mad_55_01"] = "EKİP, HÂLÂ O RADARI PATLATMANIZ GEREKİYOR.",
["pln_mad_55_02"] = "RADAR HÂLÂ ÇALIŞIYOR. PATLAYICILARLA HAVAYA UÇURUN.",
["pln_mad_55_03"] = "MİLLET, RADAR HÂLÂ ÇALIŞIYOR MU? YOK ETMENİZ GEREKİYOR. BILE'IN BIRAKTIĞI PATLAYICILARI KULLANIN!",
["pln_mad_56_01"] = "O RADARI BİR ŞEKİLDE İNDİRMELİYİZ. UÇAKSAVARLA HAVAYA UÇURABİLİYOR MUSUNUZ, BAKIN.",
["pln_mad_56_02"] = "O RADARI DEVRE DIŞI BIRAKMALIYIZ. UÇAKSAVARIN FÜZELERİ İŞİ GÖRÜR. KULLANABİLİYOR MUSUNUZ, BAKIN.",
["pln_mad_56_03"] = "RADARIN BİR AN ÖNCE YOK EDİLMESİ GEREK. BELKİ UÇAKSAVAR TOPUNU ÇEVİRİP PATLATABİLİRSİNİZ?",
["pln_mad_57_01"] = "O FÜZELERİ RADARA GETİRİN!",
["pln_mad_57_02"] = "O FÜZELER İŞİ GÖRÜR. RADARA GÖTÜRÜN!",
["pln_mad_57_03"] = "İŞTE BU! O FÜZELER TAM ARADIĞIMIZ ŞEY. RADARA GÖTÜRÜN. ",
["pln_mad_58_01"] = "FÜZELERİ RADARIN YANINA YERLEŞTİRİP ETKİNLEŞTİRİN. ÇOCUK OYUNCAĞI.",
["pln_mad_58_02"] = "FÜZELERİ RADARA YAKLAŞTIRIP ETKİNLEŞTİRİN. BİRAZDAN HER ŞEY GÜMLEYECEK.",
["pln_mad_58_03"] = "FÜZELERİ RADARIN YANINA YERLEŞTİRİP ETKİNLEŞTİRİN. BU İŞİ ÇÖZER.",
["pln_mad_59_01"] = "HARİKA İŞ EKİP. BILE ŞİMDİ EMP'YLE YOLDA VE KERESTE FABRİKASININ YAKININA BIRAKACAK.",
["pln_mad_59_02"] = "UÇAKSAVAR SAVUNMASI ORTADAN KALKTIĞINA GÖRE BILE EMP'Yİ KERESTE FABRİKASININ YAKININA RAHATÇA BIRAKABİLİR.",
["pln_mad_59_03"] = "MÜKEMMEL, EKİP. UÇAKSAVAR SAVUNMASI YOK, BILE ARTIK EMP'Yİ KERESTE FABRİKASININ YAKININA BIRAKABİLİR.",
["pln_mad_60_01"] = "İŞTE UÇAKSAVAR. BUNU PATLATIRSAK KENDİMİZİ DE PATLATIRIZ. SİSTEMİNİ KIRMAMIZ LAZIM, O DİZÜSTÜ BİLGİSAYARA ERİŞMEMİ SAĞLAYIN.",
["pln_mad_60_02"] = "BUNU DEVRE DIŞI BIRAKMAK İÇİN BAĞLI OLDUĞU DİZÜSTÜ BİLGİSAYARIN SİSTEMİNİ KIRMALIYIZ.",
["pln_mad_60_03"] = "RADARI PATLATSAK BİLE BUNU DİZÜSTÜNDEN KONTROL EDEBİLİRLER. HACKLEMELİYİZ.",
["pln_mad_61_01"] = "EMP İKİ İŞE YARAYACAK: GİZLİ LABORATUVARA GİRİŞ YOLU AÇACAK. DAHA ÖNEMLİSİ, ÜZERLERİNDE DENEY YAPTIKLARI HER KİMSE ONLARI BAYILTACAK. DUYDUĞUMA GÖRE ONLARLA SAVAŞMAK MÜMKÜN DEĞİL.",
["pln_mad_61_02"] = "EMP BİZE SADECE GİRİŞ YOLU AÇMAYACAK, DENEKLERİ DE BAYILTACAK. GÜVENİN BANA, BU ADAMLARLA UĞRAŞMAK İSTEMEZSİNİZ.",
["pln_mad_61_03"] = "EMP BİZE İÇERİ GİRME YOLU AÇACAK AMA ASIL İŞİ DENEKLERİ BİZİM İÇİN HALLETMEK. SÖYLENTİLER DOĞRUYSA BU ADAMLARLA KAPIŞMAK İSTEMEYİZ.",
["pln_mad_62_01"] = "ELEPHANT ÖZELLİKLE EVRAK ÇANTASINI UNUTMAMAMI SÖYLEDİ! BULUN!",
["pln_mad_62_02"] = "O EVRAK ÇANTASI OLMADAN GİDEMEYİZ!",
["pln_mad_62_03"] = "EKİP, NE OLUYOR? EVRAK ÇANTASI OLMADAN GİTMİYORUZ.",
["pln_mad_63_01"] = "BU ADAMA NE OLMUŞ LAN?! NEYSE, ADAMIN ELİ LAZIM.",
["pln_mad_63_02"] = "NASIL BİR HAYVAN BUNU YAPAR? ŞİMDİ DE ELİNİ KESMEMİZ GEREK... ",
["pln_mad_63_03"] = "NE UYGUN, ARTIK KAÇAMAZ. ELİNİ KESİP TARAYICIYA GETİRİN.",
["pln_mad_brf_01_01"] = "VİCDANA GELECEK ONCA ZAMAN VARKEN ŞİMDİ Mİ AKLINIZA GELDİ? HOŞUMA GİTTİĞİNİ SÖYLEYEMEM AMA HATA YAPTIĞINIZI DA SÖYLEYEMEM. JIMMY DENEN BU ADAMIN ANLATTIKLARINA BAKILIRSA AKAN'IN GERÇEKTEN DURDURULMASI GEREKİYOR. HEDEFİNİZ KUŞ UÇMAZ KERVAN GEÇMEZ BİR YERDEKİ KERESTE FABRİKASI. ASLINDA TUHAF BİR RUS ÖRGÜTÜNÜN İŞLETTİĞİ GİZLİ BİR LABORATUVAR. JIMMY, BU GERÇEKLİĞİN ÖTESİNDEKİ ŞEYLERLE İLGİLİ DENEYLER YAPTIKLARINI SÖYLÜYOR. LABORATUVARA GİRİP AKAN'IN PEŞİNDE OLDUĞU VERİLERİ ALIN. İYİ ŞANSLAR MİLLET.",
["pln_mad_intro_01_01"] = "LANET OLSUN! BÜTÜN FABRİKANIN ÇEVRESİNE UÇAKSAVAR SAVUNMASI KURMUŞLAR. UÇAĞI ÇEVİR BILE! MİLLET, PARAŞÜTLERİ KULLANIP ATLAMALISINIZ! HEMEN!",
["pln_mad_intro_01_02"] = "SİKTİR! BU PİÇLER UÇAKSAVAR SAVUNMASI KURMUŞ! BILE, UÇAĞI HEMEN GERİ ÇEVİR! MİLLET, PARAŞÜTLERİ KULLANIP ATLAYIN! BİR ŞEYLER DÜŞÜNÜRÜZ!",
["pln_mad_intro_01_03"] = "UÇAKSAVAR SAVUNMASI MI?! TAŞAK MI GEÇİYORSUN?! UÇAĞI GERİ ÇEVİR BILE! HEMEN YAP! MİLLET, PARAŞÜTLERİ ALIP ATLAYIN!",
["pln_mallcrasch_stage1_brief_01"] = "EVET. DOĞRU DUYDUNUZ. VLAD CİDDİ. ALIŞVERİŞ MERKEZİNE GİRİP KIRABİLDİĞİMİZ KADAR ÇOK ŞEYİ KIRACAĞIZ.",
["pln_mallcrasch_stage1_brief_01b"] = "YETERİNCE ZARAR VERİNCE BU MÜŞTERİ HARAÇ KONUSUNDAKİ TAVRINI BAŞTAN DÜŞÜNECEK. PİS BİR İŞ AMA SİZ DE ELLERİNİZİ KİRLETMEYİ SEVİYORSUNUZ, DEĞİL Mİ?",
["pln_mallcrasch_stage1_end_a_01"] = "İŞTE BU MİLLET. VLAD MESAJINI İLETECEK. PARAMIZI ALALIM.",
["pln_mallcrasch_stage1_end_a_02"] = "AVM YIKIMI TAMAM. KUDURAN POLİSLER TAMAM. GİDİP YAŞLI VLAD'DAN PARAMIZI ALALIM.",
["pln_mallcrasch_stage1_end_a_03"] = "TAMAM, BİTTİ. BAKALIM ÇILGIN RUS'UN SIRADA BİZİM İÇİN NE İŞİ VAR. ",
["pln_mallcrasch_stage1_end_a_04"] = "TAMAM, BU ZAVALLI ALIŞVERİŞ MERKEZİNİ BUGÜNLÜK YETERİNCE HIRPALADIK. İYİ İŞ. VLAD AMACINA ULAŞTI. BUNDAN SONRA BİRAZ ORTALIKTAN KAYBOLMALIYIZ BENCE.",
["pln_mallcrasch_stage1_end_b_01"] = "TAMAM, BU CİDDİ ANLAMDA AŞIRIYDI. VLAD BAYILACAK. ÇOK İŞİNE YARAYACAK.",
["pln_mallcrasch_stage1_end_b_02"] = "SANIRIM HER ŞEYİ SİLİP SÜPÜRDÜNÜZ. HEPSİNİ. VARINI YOĞUNU. İYİ İŞ.",
["pln_mallcrasch_stage1_end_b_03"] = "AŞIRIYDI, BAŞKA SÖZE GEREK YOK. GÜVENLİ EVDE GÖRÜŞÜRÜZ.",
["pln_mallcrasch_stage1_intro_a_01"] = "AVM'YE GİRİP GÖRDÜĞÜNÜZ HER ŞEYİ DAĞITIN. MÜMKÜNSE SİVİLLERİ UZAK TUTUN, GEREKSİZ POLİS BASKISI İSTEMİYORUZ. ",
["pln_mallcrasch_stage1_intro_a_02"] = "ELİNİZDEN GELDİĞİNCE ÇOK DÜKKÂNA VE CAMLI İÇ MEKÂNA VURUN. NAKİT VE DEĞERLİ EŞYA KAPABİLİRSENİZ FIRSATÇILIK YAPIN, ANLADINIZ. ",
["pln_mallcrasch_stage1_intro_a_03"] = "TAMAM, ALIŞVERİŞ MERKEZİ İLERİDE. GİRİN, ELİNİZDE NE VARSA SALDIRIN VE ÇIKIN. İNSAN KAYBINI EN AZA İNDİRİN. BU İŞTE ZARAR MALA VERİLECEK, CANA DEĞİL. SANA DİYORUM WOLF.",
["pln_mallcrash_stage1_01_any_01"] = "BÜTÜN ALIŞVERİŞ MERKEZİNİ DAĞITIN. YA DÜKKÂNLARI TEK TEK MAHVEDİN YA DA HEPSİNİ YAKACAK BİR ŞEY BULUN.",
["pln_mallcrash_stage1_01_any_02"] = "VLAD'IN NE KADAR CİDDİ OLDUĞUNU GÖSTERMEK İÇİN 50 BİN DOLARLIK GÜZEL EŞYAYI PARÇALAYACAĞIZ.",
["pln_mallcrash_stage1_02_any_01"] = "BİR YERLERDE ATEŞE VERİLEBİLECEK BENZİN YA DA DETERJAN VARDIR MUHTEMELEN.",
["pln_mallcrash_stage1_03_any_01"] = "DEPO DOLAPLARINI ARAYIN, İÇLERİNDE MALZEME OLABİLİR.",
["pln_mallcrash_stage1_04_any_01"] = "O KAPI KONTRPLAK GİBİ GÖRÜNÜYOR. KİLİDİNİ VURUN.",
["pln_mallcrash_stage1_05_any_01"] = "TAMAM, YAKLAŞIK 5000 DOLAR OLDU.",
["pln_mallcrash_stage1_05_any_02"] = "BEŞ BİN DOLAR MİLLET.",
["pln_mallcrash_stage1_06_any_01"] = "10 BİN.",
["pln_mallcrash_stage1_06_any_02"] = "10 BİN DOLAR DEĞERİNDE.",
["pln_mallcrash_stage1_07_any_01"] = "15.000 DOLARLIK EŞYA.",
["pln_mallcrash_stage1_07_any_02"] = "15 BİN, MİLLET.",
["pln_mallcrash_stage1_08_any_01"] = "20 BİN.",
["pln_mallcrash_stage1_08_any_02"] = "20 BİNE ULAŞTINIZ! DEVAM EDİN!",
["pln_mallcrash_stage1_09_any_01"] = "25 BİN, YARILADIK MİLLET.",
["pln_mallcrash_stage1_09_any_02"] = "İKİ-BEŞ-SIFIR-SIFIR-SIFIR, YARILADINIZ! DEVAM EDİN!",
["pln_mallcrash_stage1_10_any_01"] = "30 BİN DOLAR...",
["pln_mallcrash_stage1_10_any_02"] = "30 BİN MİLLET, DEVAM EDİN!",
["pln_mallcrash_stage1_11_any_01"] = "35 BİN DOLAR.",
["pln_mallcrash_stage1_11_any_02"] = "35 BİN, MİLLET.",
["pln_mallcrash_stage1_12_any_01"] = "40 BİN OLDU, SADECE ON KALDI!",
["pln_mallcrash_stage1_12_any_02"] = "ŞİMDİYE KADAR 40 BİN DOLARLIK HASAR VERİLDİ.",
["pln_mallcrash_stage1_13_any_01"] = "45 BİN.",
["pln_mallcrash_stage1_13_any_02"] = "AZ KALDI MİLLET, KIRK BEŞ BİN.",
["pln_mallcrash_stage1_14_any_01"] = "50 BİN, VAY BE, GERİYE BİR ŞEY KALDI MI?",
["pln_mallcrash_stage1_14_any_02"] = "İŞTE BU! ARTIK VLAD'LA UĞRAŞMAMALARI GEREKTİĞİNİ BİLİYORLAR.",
["pln_mallcrash_stage1_14_any_03"] = "50 BİNLİK MAL ÇÖPE GİTTİ!",
["pln_mallcrash_stage1_15_any_01"] = "DEVAM ETMEK İSTERSENİZ VLAD 50 BİNİN ÜZERİNDEKİ HER ŞEY İÇİN BONUS VERİYOR!",
["pln_mallcrash_stage1_15_any_02"] = "İSTERSENİZ KALIP ORTALIĞI DAĞITABİLİRSİNİZ AMA KAÇIŞ ARACI YAKINDA GELİYOR!",
["pln_mallcrash_stage1_16_any_01"] = "ÇABUK AŞAĞI İNİN MİLLET. POLİSLERİN KAÇIŞ BİLETİMİZİ MAHVETMESİNİ İSTEMEYİZ.",
["pln_mallcrash_stage1_17_any_01"] = "POLİSLER MİNİBÜSÜ PARÇALADI!",
["pln_mallcrash_stage1_18_any_01"] = "BEKLEYİN MİLLET, BİR HELİKOPTER GELİYOR.",
["pln_mallcrash_stage1_19_any_01"] = "YAKINDA ORADA!",
["pln_mallcrash_stage1_20_any_01"] = "HELİKOPTERE GİDİN!",
["pln_man_00a_01"] = "LİMUZİN GELDİ. TAXMAN BURADA.",
["pln_man_00a_02"] = "TAMAM, TEKRAR EDEYİM: TAXMAN IRS'TEN, BÜYÜK BİR ŞİRKETLE ŞÜPHELİ ANLAŞMA YAPIYOR. ONLARA HAYATİ VERİLER İÇEREN BİR SUNUCU SATIYOR.",
["pln_man_00a_03"] = "ONLARI KAZIKLAYIP HEM TAXMAN'İ HEM SUNUCUYU KAPACAĞIZ. BUNLARLA 25.000.000 DOLARLIK BİR HACK YAPACAĞIZ. ALEX, VİNÇ HAZIR MI?",
["pln_man_00b_01"] = "TAMAM MİLLET, DOĞRU ANDA ANLAŞMAYI BOZUN. SONRA ALEX LİMUZİNİ ORADAN KALDIRACAK. HAZIR OLUN!",
["pln_man_01_01"] = "UNUTMAYIN MİLLET, HEM TAXMAN HEM SUNUCU GEREKİYOR. SUNUCUNUN ONDA OLDUĞUNU DOĞRULAYINCA KORKUTUP LİMUZİNE SOKUN.",
["pln_man_01_02"] = "MİLLET, BUNU DOĞRU YAPMALIYIZ. HEM TAXMAN HEM SUNUCU LAZIM, YOKSA HER ŞEY BOKA GİDER. SUNUCUNUN ONDA OLDUĞUNDAN EMİN OLUN.",
["pln_man_02_01"] = "ŞEY... POLİS TELSİZİMDİR. KAPATAYIM. POLİS KİLOMETRELERCE UZAKTA.",
["pln_man_02_02"] = "NE... POLİS TELSİZİ TARAYICIMDIR O. POLİSLERİN YAKINDA OLDUĞU YOK. ",
["pln_man_02_03"] = "ONA ALDIRMAYIN, POLİS TELSİZİM. BURADA POLİS YOK.",
["pln_man_03_01"] = "PENCEREDEN BAKIN, TAXMAN BEYAZ GÖMLEKLİ ADAM.",
["pln_man_03_02"] = "İŞTE ORADA, BEYAZ GÖMLEKLİ TAXMAN. ",
["pln_man_03_03"] = "BEYAZ GÖMLEKLİ, İŞTE O BİZİM TAXMAN. ",
["pln_man_04_01"] = "MÜŞTERİLERİ HEMEN KÖŞEYİ DÖNÜNCE KARŞINIZDA OLACAK. HAZIRLANIN.",
