["pln_man_brf_01"] = "TAXMAN BÜYÜK BİR ŞİRKETLE ANLAŞMA YAPARAK AKILLILIK ETTİĞİNİ SANDI AMA BİLGİ SIZDI. ŞİMDİ DAHA BÜYÜK KÖPEK BALIKLARI OYUNA TAMAMEN GİRMEK İSTİYOR. ANLAŞMAYI GÖREN, TERK EDİLMİŞ KOCA BİR BİNA BİZİM. DÜZENEĞİMİZ HAZIR. ALEX VİNÇLE YARDIM EDECEK. TAXMAN'İ KORKUTUP LİMUZİNİNE SOKUN, BİRAZ SARSIN; SUNUCUYU VE KODLARI BİZE VERİR. KONU $25,000,000 OLUNCA HER YOL MUBAH.",
["pln_man_cbf_01"] = "TAMAM EKİP, EŞYALARINIZI TOPLAYIP WASHINGTON D.C.'YE GİDİN. STURR ADINDA BİR BEYEFENDİNİN PEŞİNDEYİZ. BAY STURR, PİS VE KOCAMAN BİR ŞİRKETLE ANLAŞARAK ÇOK PARA KAZANMAK İSTEYEN SİNSİ BİR IRS ÇALIŞANI. AMA BENCE O PARAYI DAHA İYİ KULLANABİLİRİZ. YAPALIM.",
["pln_man_cnc_01"] = "WASHINGTON D.C.'DE AÇGÖZLÜ BİR IRS ÇALIŞANIYLA KÜÇÜK BİR... SÜRPRİZ GÖRÜŞME AYARLADIM. ",
["pln_man_cnc_02"] = "WASHINGTON D.C.'YE GİDİP KİRLİ ANLAŞMA YAPMAYA ÇALIŞAN PİSLİK BİR VERGİ MEMURUNU KAÇIRIN.",
