["pln_misc_sj_dgh_01_01"] = "İŞTE ORADALAR, TAM WICK'İN DEDİĞİ GİBİ. MİNİBÜSE GÖTÜRÜP ŞİMDİLİK BAĞLAYIN. GİDERKEN YANIMIZDA GÖTÜRECEĞİZ. WICK ONLARLA BİRAZ \"SOHBET\" ETMEK İSTİYOR DA. ",
["pln_misc_sj_dgh_01_02"] = "İŞTE ONLAR! WICK'İN DEDİĞİ GİBİ BURADALARMIŞ. BAĞLAYIP MİNİBÜSÜN YANINA BIRAKIN. DÖNÜNCE WICK O PİSLİKLERİN İCABINA BAKAR. ",
["pln_misc_sj_dgh_01_03"] = "EVET, KESİNLİKLE ONLAR. GÖRMEK BİLE KANIMI KAYNATIYOR. BAĞLAYIP MİNİBÜSÜN YANINA BIRAKIN. GİDERKEN BİZİMLE GELİYORLAR. WICK BU KONUDA ÇOK NETTİ.",
["pln_misc_sj_dgh_02_01"] = "BİRİNİ ÖLDÜRDÜNÜZ MÜ? LANET OLSUN, O PİÇ HAK ETMEDİ DİYEMEM AMA WICK BU ZEVKİ KENDİ TATMAK İSTİYORDU.",
["pln_misc_sj_dgh_02_02"] = "LANET OLSUN! İÇLERİNDEN BİRİNİ ÖLDÜRMEYECEKTİNİZ MİLLET... WICK ONLARLA KENDİSİ ‘SOHBET’ ETMEK İSTİYORDU. BİRİYLE YETİNMESİ GEREKECEK GALİBA. ",
["pln_misc_sj_dgh_02_03"] = "KENDİNİZİ TUTAMADINIZ, DEĞİL Mİ? EH, O PİÇ OLMADAN DÜNYA DAHA GÜZEL AMA WICK İŞİN PARÇASI OLAMADIĞI İÇİN ÜZÜLECEK. DİĞERİNİ ONA BIRAKSANIZ İYİ OLUR.",
["pln_misc_sj_dgh_03_01"] = "NE YAPTINIZ LAN MİLLET! ONLARI ŞİMDİ ÖLDÜRMEYECEKTİNİZ! WICK DERSLERİNİ VERMEK İÇİN CANLI İSTİYORDU... UMARIM ÖLDÜKLERİNİ BİLMEKLE YETİNİR.",
["pln_misc_sj_dgh_03_02"] = "HAYIR! LANET OLSUN EKİP... WICK ONLARLA KENDİSİ İLGİLENMEK İSTİYORDU. BU PİÇLERE GERÇEKTEN TAKMIŞTI. SANIRIM ÖLDÜKLERİNİ BİLMEKLE YETİNMEK ZORUNDA KALACAK.",
["pln_misc_sj_dgh_03_03"] = "LANET OLSUN! NEDEN YAPTINIZ? ONLARI WICK'E GETİRMENİZ GEREKİYORDU, KENDİNİZ ÖLDÜRMENİZ DEĞİL... NASIL TEPKİ VERECEĞİNDEN EMİN DEĞİLİM. O İĞRENÇ VİDEOYU GÖRDÜĞÜNDEN BERİ TEK KONUŞTUĞU BU...",
["pln_misc_sj_dgh_04_01"] = "GÜZEL. BİZ BANKAYLA İLGİLENİRKEN PİÇLER KORKUDAN KIVRANSIN. ",
["pln_misc_sj_dgh_04_02"] = "İYİ İŞ. BİZ BANKAYLA İLGİLENİRKEN ŞİMDİLİK ONLARI ORADA BIRAKIN.",
["pln_misc_sj_dgh_04_03"] = "İŞTE BÖYLE. BİZ BANKADA İŞİMİZİ YAPARKEN ONLAR ALTLARINA İŞESİN.",
