["pln_moon_brf_01"] = "VLAD'IN KAYINBİRADERİ POLİSLERDEN ALIŞVERİŞ MERKEZİNİN YÜKLEME ALANINA SAKLANDI. KOKAİNİ ÇEŞİTLİ KUTULARA GİZLEMİŞ. O KUTULAR DA ARTIK MERKEZİN HER YANINDAKİ DÜKKÂNLARA DAĞILMIŞ. KENDİNİ NOEL BABA KILIĞINA SOKUP VOTKA ÇALMIŞ, SARHOŞ DA OLMUŞ. NE REZALET. POLİSLER SARHOŞ NOEL BABA'DAN ŞÜPHELENİP YAKALAMIŞ. ONU KURTARIN VE KOKAİNİ HANGİ KUTULARA KOYDUĞUNU HATIRLIYOR MU SORUN.",
["pln_nai_01_01"] = "ATLAYIP ‘BÖÖ!’ DİYE BAĞIRMAYA HAZIRLANIN MİLLET.",
