["pln_nai_02_03"] = "ANNEM HEP DIŞARISI KOCAMAN BİR DÜNYA DERDİ AMA BU...",
["pln_nai_03_01"] = "PİŞİRMEYE BAŞLAMAK İÇİN EFEDRİN HAPLARI EKLEMEMİZ GEREKİYOR. BULUP KARIŞTIRICIYA ATIN.",
