["pln_nai_08_03"] = "TAMAM. EVET, BU İYİ. AMA DAHA FAZLASI GEREKECEK.",
["pln_nai_09_01"] = "TAMAM, ŞİMDİ O METİ PARÇALAMALISINIZ. VURUN KIRIN EKİP!",
["pln_nai_09_02"] = "METAMFETAMİN DONDU AMA BÖYLE ÇIKARAMAYIZ. PARÇALAYIN. KIRIN, VURUN, PATLATIN; PARÇALAYIN DA NASIL OLURSA OLSUN!",
