["pln_nai_10_02"] = "UNUTMAYIN, O METAMFETAMİNİ PARÇALAMANIZ GEREK.",
["pln_nai_10_03"] = "METİ KÜÇÜK PARÇALARA BÖLMELİSİNİZ. HINCINIZI ONDAN ÇIKARIN EKİP!",
["pln_nai_11_01"] = "PİŞİRMEYE DEVAM ETMEK İÇİN DAHA FAZLA TABLET EKLEYİN. YA DA KAÇMAK İÇİN HELİKOPTERE İŞARET VERİN; SİZE KALMIŞ.",
["pln_nai_11_02"] = "PEKÂLÂ. ŞİMDİ PİŞİRMEYE DEVAM EDEBİLİR YA DA HELİKOPTERE İŞARET VERİP BU İŞİ BİTİREBİLİRSİNİZ.",
["pln_nai_11_03"] = "PİŞİRMEYE DEVAM EDECEKSENİZ KARIŞTIRICIYA DAHA FAZLA HAP ATIN EKİP. YA DA FİŞEĞİ YAKIP KAÇIN. SİZE KALMIŞ!",
["pln_nai_12_01"] = "İYİ YER. ŞİMDİ BEKLİYORUZ.",
["pln_nai_12_02"] = "TAMAM, ŞİMDİ PİLOTU BEKLEYİN.",
["pln_nai_12_03"] = "İŞTE BU. ŞİMDİ PİLOTUN HABER VERMESİNİ BEKLEYİN.",
