["pln_nai_13_03"] = "HELİKOPTER BU. BİNİN, EKİP!",
["pln_nai_14_01"] = "ÇANTALARI YERDEKİ KONTEYNERLERDEN BİRİNE ATIN YETER. SONRA ALMASI İÇİN... BİRİNİ GÖNDERİRİM.",
["pln_nai_14_02"] = "ŞİMDİ O ÇANTALARI ZEMİNDEKİ KONTEYNERE KOYUN. ALACAK BİRİNİ BULACAĞIMA EMİNİM.",
["pln_nai_14_03"] = "ŞİMDİ O ÇANTALARI AŞAĞIDAKİ KONTEYNERLERE KOYUN. GERİ DÖNÜP ALACAĞIZ.",
["pln_nai_15_01"] = "ŞİMDİ BAKMAYIN AMA...",
["pln_nai_15_02"] = "BU, GECENİN ÇOCUKLARININ O TATLI MÜZİĞİ DEĞİL.",
["pln_nai_15_03"] = "BİR ŞEY DUYDUM...",
["pln_nai_16_01"] = "SUÇ TARİHİNİN EN BÜYÜK ÇUVALLAMALARI ARASINDA BU EPEY ÜST SIRALARA GİRER. POLİSLERİN KAHKAHALARINI BURADAN DUYUYORUM. BİR DAHAKİNE ŞANSINIZ YAVER GİDER UMARIM.",
["pln_nai_16_02"] = "FOKUR FOKUR KAYNASIN, DERTLE TASA ÇOĞALSIN. DAHA ÇOK DERTLE TASA TABİİ. ÖZELLİKLE TASA.",
["pln_nai_17_01"] = "TEK BİR ÇANTA BİLE YOK MU?! BU BİR KÂBUS!",
["pln_nai_17_02"] = "HİÇBİR ŞEY ALAMADINIZ MI? BENİ ÖLDÜRECEKSİNİZ!",
["pln_nai_17_03"] = "HİÇBİR ŞEY ÇIKARAMADINIZ MI? ",
["pln_nai_18_01"] = "FENA BİR MİKTAR TOPLAMADINIZ. BENZİN PARASINI ANCA ÇIKARIR. BİR DAHAKİNE BELKİ DAHA FAZLASINI YAPARIZ.",
["pln_nai_18_02"] = "İŞ TAMAMEN BATMADI. YİNE DE LEATHERFACE'İN MERDİVEN ALTINDAKİNDEN AZ DOLU ÇANTA VAR!",
["pln_nai_18_03"] = "ASGARİ BİR VURGUN AMA İDARE EDER. GELECEK YIL DAHA ŞANSLI OLURSUNUZ EKİP.",
["pln_nai_19_01"] = "GÜZEL VURGUN! BU EPEY PARA GETİRİR. İYİ İŞ!",
["pln_nai_19_02"] = "EPEY İYİ SAYIDA ÇANTA KAPTINIZ. GÜZEL İŞ!",
["pln_nai_19_03"] = "ŞAKA MI ŞEKER Mİ GANİMETİNİZ BAYAĞI İYİ. EVE GELİN EKİP, PAYLAŞALIM!",
["pln_nai_20_01"] = "VAY BE! HARİKAYDINIZ! KAZANDIĞINIZ PARANIN TADINI ÇIKARIN, HAK ETTİNİZ.",
["pln_nai_20_02"] = "GELDİK, GÖRDÜK, KIÇLARINA TEKMEYİ BASTIK!",
["pln_nai_20_03"] = "HARİKASINIZ! BİR NUMARALI HAYRANINIZIM!",
["pln_nai_21_01"] = "GELDİLER.",
["pln_nai_21_02"] = "İŞTE JOHNNY!",
["pln_nai_21_03"] = "KORKUN... HEM DE ÇOK KORKUN.",
["pln_nai_21_04"] = "O POLİSLERİN KORKUDAN ÇIĞLIK ATTIĞINI DUYMAK İSTİYORUM!",
["pln_nai_21_05"] = "BİR, İKİ, POLİS GELİYOR SİZİN İÇİN...",
["pln_nai_22_01"] = "YAŞIYOR! YAŞIYOR!",
["pln_nai_22_02"] = "BU CANAVAR GİBİ OLACAK!",
["pln_nai_22_03"] = "PİŞİYOR. NE GÜZEL MÜZİK YAPIYOR!",
["pln_nai_brf_01_01"] = "BU GECE GEÇ SAATTE LABORATUVARDAYIZ, GÖZLERİNİZE TEKİNSİZ BİR MANZARA SUNARIZ. MASADA PİŞİRİN, KÖPÜRSÜN, KAYNASIN. POLİS DE GELİP BAŞIMIZA BELA SALMASIN.",
["pln_nai_cbf_01_01"] = "ŞEKER Mİ ŞAKA MI, KOKLA BAKALIM AYAĞIMI. VER BİR ŞEY, SOKAKTA SATAYIM. VERMEZSEN DE TAKMAM BEN; YETER Kİ DONUNLA PİŞİRME SEN.",
["pln_nai_cnc_01_01"] = "BU GECE ORMAN KARANLIK VE ÜRKÜTÜCÜ EKİP. HADİ BİRAZ MET PİŞİRELİM.",
["pln_nai_cnc_01_02"] = "CADILAR BAYRAMI SÜRPRİZİ MİLLET. ORMANDAKİ KULÜBEYE GERİ DÖNÜYORUZ.",
["pln_nai_cnc_01_03"] = "CADILAR BAYRAMI İKRAMLARI PİŞİRME VAKTİ EKİP. ORMANDAKİ METAMFETAMİN LABORATUVARINA GİDİN.",
["pln_nai_intro_01_01"] = "BİRAZ METAMFETAMİN PİŞİRMEYE GELDİK. TIPKI GEÇEN YAZ YAPTIĞIMIZ GİBİ.",
["pln_nai_intro_01_02"] = "İŞİ BİLİYORSUNUZ EKİP. HADİ BİRAZ MET PİŞİRELİM.",
["pln_nai_intro_01_03"] = "BİR OYUN OYNAMAK İSTER MİSİNİZ? MET PİŞİRME OYUNU?",
