["pln_nightclub_stage1_07_any_01"] = "ONLARI KONTROL ALTINDA TUTUN. KAÇAN OLMASIN!",
["pln_nightclub_stage1_08_any_01"] = "TAMAM, BULDUNUZ. ŞİMDİ O KASAYI MATKAPLA AÇIN, MUHTEMELEN NAKİTLE DOLU.",
["pln_nightclub_stage1_09_any_01"] = "MİLLET, O KASAYI AÇMAMIZ GEREKİYOR.",
