["pln_nightclub_stage1_17_any_01"] = "MİNİBÜSE BİNİN! MİNİBÜSE BİNİN!",
["pln_nightclub_stage1_17_any_02"] = "GİTME VAKTİ MİLLET!",
["pln_nightclub_stage1_18_any_01"] = "HADİ, HADİ, HADİ! KOŞUN!",
["pln_nightclub_stage1_bag_01_01"] = "DOKTOR ÇANTASI BANYODA.",
["pln_nightclub_stage1_bag_02_01"] = "MÜHİMMAT ÇANTASI DEPODA BULUNABİLİR.",
["pln_nightclub_stage1_bag_03_01"] = "KAMYONET GELDİ. KOLAY KAÇMAK İSTERSENİZ ÇANTALARI PENCEREDEN ATABİLİRSİNİZ.",
["pln_nightclub_stage1_brief_01"] = "TAMAM, TASTEFUL KULÜBÜNÜ ZİYARET EDİP, ŞEY, NAKİT REZERVLERİNİ ÖZGÜRLEŞTİRECEĞİZ. ÖZEL BİR ŞEY YOK. MÜDÜRÜN OFİSİNİ BULUN, KALABALIĞI KONTROL EDİN, TEK PARÇA ÇIKTIĞIMIZDAN EMİN OLUN.",
["pln_nightclub_stage1_brief_01b"] = "HA, BURADA MUHTEMELEN RAKİP RUS MAFYASI DA VARDIR. BİLİYORUM, VLAD BANA DA PEK BİR ŞEY ANLATMIYOR.",
["pln_nightclub_stage1_dj_01_01"] = "DJ'E İNTERNETTE BULDUĞU BOKTAN ŞARKILARI ÇALMASI İÇİN PARA VERDİM. BÖYLECE DAHA AZ SİVİLİN ATEŞ HATTINA GİRME RİSKİ VAR. ",
["pln_nightclub_stage1_end_a_01"] = "VAY. RUSLAR BU TAKTİĞE YAKIP YIKMA DERDİ. ÇOK SALDIRGAN. EMİNİM VLAD TEŞEKKÜR İÇİN SİZE BİRER VOTKA KOYAR.",
["pln_nightclub_stage1_end_a_02"] = "POLİS BU İŞTE BURNUMUZU KANATTI. NEDENSE VLAD'İN BİLGİ SAKLADIĞINI DÜŞÜNÜYORUM... HER ZAMANKİ GİBİ. AMA İYİ YAPTINIZ... BAKALIM BİZİM VLAD NE DİYECEK.",
["pln_nightclub_stage1_end_a_03"] = "NE BAR KAVGASIYDI AMA. ŞİMDİ VLAD MUHTEMELEN ZİRVEDEDİR, KURNAZ İHTİYAR RUS. HADİ GİDİP PARANIZI ALALIM.",
["pln_nightclub_stage1_end_a_04"] = "DİSKO CEHENNEMİ. İYİ İŞ. PARAMIZI ALALIM.",
