["pln_nmh_66_01"] = "YANLIŞ ADAM, ARAMAYA DEVAM EDİN!",
["pln_nmh_66_02"] = "BİZİM ADAM DEĞİL.",
["pln_nmh_67_01"] = "ETRAFTA SANTRİFÜJLER VAR. KAN ÖRNEKLERİNİ DOĞRULAMAYA BAŞLAMAK İÇİN KULLANIN.",
["pln_nmh_68_01"] = "%65 VEYA DAHA YÜKSEK VİRÜS YOĞUNLUĞU GEREKİYOR.",
["pln_nmh_69_01"] = "İKİ TÜP GEREKECEK. BİRİ TESTİ GEÇEMEZSE DAHA FAZLA KAN ALIP YENİDEN BAŞLAMALISINIZ.",
["pln_nmh_70_01"] = "ŞİMDİ O KAN NUMUNESİNİ DOĞRULAYIN.",
["pln_nmh_70_02"] = "BİR SANTRİFÜJ BULUN.",
["pln_nmh_70_03"] = "BİR SANTRİFÜJE GİDİP O NUMUNEYİ TEST EDİN.",
["pln_nmh_71_01"] = "O NUMUNE YETMEDİ. BAŞKASINI ALMALISINIZ MİLLET.",
["pln_nmh_71_02"] = "O NUMUNENİN YOĞUNLUĞU GEREKENİN YANINA BİLE YAKLAŞMADI. TEKRAR DENEMELİSİNİZ.",
["pln_nmh_71_03"] = "KAHRETSİN, YETERİNCE İYİ DEĞİL. BİR TANE DAHA ALIN.",
["pln_nmh_71_04"] = "HÂLÂ YETMİYOR, BAŞKA ÖRNEK ALMALISINIZ.",
["pln_nmh_72_01"] = "AZ ÖNCE BİR ŞİŞE Mİ KIRDINIZ? O ŞEYİ ÜSTÜNÜZE BULAŞTIRMAYIN!",
["pln_nmh_72_02"] = "O KIRILAN BİR NUMUNE ŞİŞESİ MİYDİ? KANA DOKUNMAYIN!",
["pln_nmh_72_03"] = "KAHRETSİN, BİR ŞİŞE KAYBETTİNİZ.",
["pln_nmh_72_04"] = "ŞİŞELERİ DÜŞÜRMEK İYİ DEĞİL MİLLET.",
["pln_nmh_72_05"] = "TÜPLER YERE ÇARPINCA KIRILIR, BİLİYORSUNUZ...",
["pln_nmh_73_01"] = "DİKKATLİ OLUN MİLLET. BUNLARDAN BİRİNİ TAŞIRKEN YERE DÜŞERSENİZ KIRABİLİRSİNİZ.",
["pln_nmh_73_02"] = "KAN NUMUNESİ TAŞIRKEN YERE DÜŞMEYİN MİLLET, BÜYÜK İHTİMALLE KIRILIRLAR.",
["pln_nmh_73_03"] = "AYAKTA KALIN MİLLET. YERE DÜŞERSENİZ TÜPLER KIRILABİLİR!",
["pln_nmh_74_01"] = "İKİ NUMUNE GEREKİYOR. GİDİP ALIN.",
["pln_nmh_74_02"] = "HASTADAN BİRAZ KAN ALMANIZ GEREKİYOR.",
["pln_nmh_74_03"] = "İĞNEDEN FALAN MI KORKUYORSUNUZ? BATIRIN!",
["pln_nmh_74_04"] = "O KANI ALIN MİLLET.",
["pln_nmh_75_01"] = "ASANSÖRÜ ŞİMDİDEN ÇAĞIRIN BARİ. BİR NUMUNE DAHA, SONRA ÇIKABİLİRSİNİZ!",
["pln_nmh_76_01"] = "ASANSÖRÜ ÇAĞIRIN.",
["pln_nmh_76_02"] = "ASANSÖR DÜĞMESİNE BASIN.",
["pln_nmh_77_01"] = "HARİKA, ŞİMDİ ORAYA ULAŞANA KADAR DAYANMANIZ YETER.",
["pln_nmh_78_01"] = "LANET ŞEY SÜREKLİ DURUYOR. SİSTEMİ AŞMAM GEREK. SİZE ULAŞMASI BİRAZ SÜRECEK.",
["pln_nmh_79_01"] = "BELKİ... İKİ DAKİKA. İŞİM KESİLMEZSE TABİİ.",
["pln_nmh_80_01"] = "BU TUHAF, MİLLET. PANOLAR DELİ GİBİ YANIP SÖNÜYOR. BİR TERSLİK VAR... SANIRIM BÜYÜK BELA GELİYOR. LANET OLSUN, BU İŞİN KARANLIK OLDUĞUNU BİLİYORDUM.",
["pln_nmh_80_02"] = "MİLLET, İÇİME KÖTÜ BİR HİS DOĞUYOR. ASKERÎ SANAYİ İLETİŞİM KANALLARI ÇILDIRDI. FENA DİKKAT ÇEKMİŞİZ GİBİ.",
["pln_nmh_80_03"] = "KAHRETSİN MİLLET, TAŞRA TELSİZLERİ FENA KIZIŞIYOR. BİRİLERİ YAPTIĞIMIZ İŞLE ÇOK İLGİLENİYOR. BÜYÜK BELAYA HAZIR OLUN.",
["pln_nmh_81_01"] = "ANA ELEKTRİĞİ KESMİŞ OLMALILAR, BİR AN ÖNCE GERİ GETİRMELİSİNİZ!",
["pln_nmh_81_02"] = "ELEKTRİĞİ KESTİLER, GERİ GETİRİN! ÇABUK! YOKSA ASANSÖR HAREKET ETMEZ.",
["pln_nmh_81_03"] = "KAHRETSİN, HIZLILAR. ELEKTRİĞİ TEKRAR AÇIN!",
["pln_nmh_81_04"] = "ELEKTRİĞİ KESTİLER, YENİDEN AÇIN!",
["pln_nmh_81_05"] = "PİÇLER ELEKTRİĞİ KESTİ. GERİ VERMELİSİNİZ.",
["pln_nmh_82_01"] = "ELEKTRİĞİ GERİ GETİRMEDEN ASANSÖR HİÇBİR YERE GİTMEZ.",
["pln_nmh_82_02"] = "ASANSÖRÜ TEKRAR ÇALIŞTIRMALISINIZ. ELEKTRİĞİ GERİ VERİN.",
["pln_nmh_82_03"] = "HADİ MİLLET, ŞU ELEKTRİĞİ YENİDEN AKITIN.",
["pln_nmh_83_01"] = "HARİKA, GÜZEL YAPTINIZ. ŞİMDİ İLERLEYİN.",
["pln_nmh_83_02"] = "ELEKTRİK GELDİ, HARİKA. ŞİMDİ DURMAYIN.",
["pln_nmh_84_01"] = "ELEKTRİĞİ YİNE KESTİLER, GERİ VERİN!",
["pln_nmh_84_02"] = "YİNE ELEKTRİK KESİLDİ! TEKRAR AÇIN!",
["pln_nmh_85_01"] = "İŞTE BÖYLE. DURUN... ŞİMDİ HAVA DESTEĞİYLE İLGİLİ BİR ŞEY Mİ ALIYORUM? NE OLUYOR LAN...",
["pln_nmh_85_02"] = "TAMAM, GÜZEL. ŞİMDİ... BİR SANİYE... MİLLET... HAVA DESTEĞİ GÖNDERMEKTEN BAHSEDİYORLAR! ACELE ETMELİSİNİZ...!",
["pln_nmh_86_01"] = "BİR BAĞLANTIMA BİZİM İÇİN ASANSÖRE SOĞUTUCU SAKLATTIM. ŞİŞELERİ İÇİNE BIRAKIN!",
["pln_nmh_87_01"] = "SOĞUTUCUYA İKİ TÜP KOYDUĞUMUZ ANDA KAÇMAYA HAZIRSINIZ.",
["pln_nmh_87_02"] = "ÇIKABİLMEK İÇİN SOĞUTUCUYA İKİ ŞİŞE KOYUN.",
["pln_nmh_87_03"] = "TÜPLERİ SOĞUTUCUYA KOYUN MİLLET. İKİSİNİ DE. SONRA DEFOLUP GİDİN.",
["pln_nmh_88_01"] = "O SOĞUTUCUYA DAHA FAZLA KAN KOYMANIZ LAZIM MİLLET.",
}
